/* テキスト拡充・第4弾(担当:soc1 中学社会・社会総合 23単元) */
(function (L) {
  function add(id, o) { var x = L[id]; if (!x) return; ['pat', 'more'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); }); }

  /* ===== 中学地理:世界のすがた ===== */
  add('c_m1', {
    pat: [
      { name: '時差の計算(経度の差 ÷ 15)', freq: 'とてもよく出る', when: '2つの都市の経度と、片方の日時が示され「もう一方は何日の何時か」と聞かれたら、この型です。', how: ['2地点が東経どうし・西経どうしなら経度を引き算、東経と西経なら足し算して経度の差を出す。', '経度の差を15でわり、時差(時間)を出す。', '東にある地点ほど時刻が進んでいるので、東なら足す・西なら引く。', '0時や24時をまたいだら、日付も1日動かす。'], ex: { q: '日本(東経135度)が1月10日午後3時のとき、西経45度の地点は何日の何時ですか。', a: '1月10日午前3時', exp: '東経と西経なので経度の差は135+45=180度。180÷15=12時間の時差です。西経45度の地点は日本より西にあるので12時間おくれ、15時−12時間=3時。日付はまたがないので1月10日午前3時です。' } },
      { name: '飛行機の到着時刻(時差+飛行時間)', freq: 'とてもよく出る', when: '「〇時に出発し、〇時間飛んだ。到着したときの現地時刻は?」という形なら、この型です。', how: ['まず出発地の時刻のまま、飛行時間を足して「出発地の時刻で何時に着くか」を出す。', '次に、出発地と到着地の時差を経度から求める。', '到着地が西なら時差を引き、東なら足して現地時刻に直す。', '日付が変わっていないか最後に確かめる。'], ex: { q: '日本(東経135度)を2月1日午前10時に出発し、ロンドン(経度0度)まで13時間飛んだ。到着したときのロンドンの時刻は?', a: '2月1日午後2時', exp: '日本の時刻で考えると、10時+13時間=23時に着きます。ロンドンとの時差は135÷15=9時間で、ロンドンは9時間おくれているので、23−9=14時。2月1日午後2時です。' } },
      { name: '雨温図から気候帯を当てる', freq: 'とてもよく出る', when: '折れ線(気温)と棒(降水量)のグラフが並び「どの都市か」「どの気候か」と聞かれたら、この型です。', how: ['いちばん寒い月の気温を見る(18℃以上なら熱帯、−3℃未満なら冷帯の目安)。', '1年の降水量の合計が少なければ乾燥帯を疑う。', '気温の山が1月にあれば南半球だと判断する。', '温帯なら「夏に乾燥=地中海性」「1年中平均して降る=西岸海洋性」「夏に多雨=温暖湿潤」と区別する。'], ex: { q: '1年中、月平均気温が25℃以上あり、毎月200mm前後の雨が降る都市の気候は何ですか。', a: '熱帯(熱帯雨林気候)', exp: 'いちばん寒い月でも18℃をこえているので熱帯です。さらに乾季がなく1年中雨が多いので、熱帯雨林気候と判断できます。乾季と雨季があればサバナ気候です。' } },
      { name: '宗教・文化の手がかりから地域を当てる', freq: 'よく出る', when: '「豚肉を食べない」「牛を神聖とする」など、暮らしのきまりが文章で示されたら、この型です。', how: ['食べ物のきまり・祈りの回数・祭りなどのキーワードを丸で囲む。', 'キーワードを宗教に結びつける(豚肉→イスラーム、牛→ヒンドゥー教など)。', 'その宗教が多い地域(西アジア・北アフリカ、インドなど)を答える。'], ex: { q: '「1日5回、聖地メッカの方向に祈る」「豚肉を食べない」という暮らしのきまりをもつ宗教は何ですか。', a: 'イスラーム(イスラム教)', exp: '1日5回の礼拝とメッカへの祈り、豚肉を口にしないことは、イスラームの代表的なきまりです。信者は西アジアや北アフリカ、東南アジアのインドネシアなどに多くいます。' } }
    ],
    more: [
      { lv: 1, q: '経度0度の本初子午線が通る都市はどれですか。', choices: ['パリ', 'ロンドン', 'ローマ', 'ベルリン'], a: 'B(ロンドン)', exp: '本初子午線は、イギリスのロンドンにあった旧グリニッジ天文台を通る経線です。ここが経度0度で、東西それぞれ180度まで数えます。' },
      { lv: 1, q: '3つの大洋のうち、いちばん面積が大きいのはどれですか。', a: '太平洋', exp: '面積は太平洋 > 大西洋 > インド洋の順です。太平洋は、地球上のすべての陸地を合わせたよりも広い大洋です。' },
      { lv: 1, q: '6つの大陸のうち、いちばん面積が大きい大陸はどれですか。', a: 'ユーラシア大陸', exp: 'ユーラシア大陸はヨーロッパとアジアをふくむ大陸で、いちばん大きな大陸です。日本はこの大陸の東にある島国です。' },
      { lv: 1, q: '赤道が通っている大陸はどれですか。', choices: ['アフリカ大陸', 'オーストラリア大陸', '北アメリカ大陸', '南極大陸'], a: 'A(アフリカ大陸)', exp: '赤道はアフリカ大陸の中央部や南アメリカ大陸の北部を通ります。オーストラリア大陸は赤道より南、北アメリカ大陸は北にあります。' },
      { lv: 1, q: '冬が長く、短い夏の間だけ地面の表面の氷がとけて、こけ類が育つ気候を何といいますか。', a: '寒帯のツンドラ気候', exp: '寒帯は1年中気温が低く、樹木が育ちません。そのうち、夏に少しだけ氷がとけてこけ類が生えるのがツンドラ気候です。' },
      { lv: 1, q: '経度は、東と西にそれぞれ何度まであるか答えなさい。', a: '東経・西経それぞれ180度まで', exp: '本初子午線(0度)から東へ東経180度、西へ西経180度まで数えます。東経180度と西経180度は同じ線です。' },
      { lv: 1, q: 'ヒンドゥー教の信者の多くが、神聖な動物として食べない動物は何ですか。', a: '牛', exp: 'ヒンドゥー教では牛を神の使いとして大切にするため、牛肉を食べません。信者はおもにインドに多くいます。' },
      { lv: 2, q: '日本(東経135度)が12月31日午後11時のとき、東経15度の地点は何日の何時ですか。', a: '12月31日午後3時', exp: '東経どうしなので引き算で、135−15=120度。120÷15=8時間の時差です。東経15度の地点は西にあるので8時間おくれ、23−8=15時です。' },
      { lv: 2, q: '西経90度の地点が7月1日午前6時のとき、日本(東経135度)は何日の何時ですか。', a: '7月1日午後9時', exp: '経度の差は135+90=225度で、225÷15=15時間。日本は東にあるので15時間進んでいて、6+15=21時、つまり午後9時です。' },
      { lv: 2, q: '乾燥帯のうち、少しだけ雨が降り、たけの短い草原が広がる気候を何といいますか。', a: 'ステップ気候', exp: '乾燥帯は砂漠気候とステップ気候に分かれます。ステップ気候では短い草が育つので、羊などを連れた遊牧が行われてきました。' },
      { lv: 2, q: 'アフリカの国の国境線に、まっすぐな直線が多いのはなぜですか。', a: 'かつてアフリカを植民地にしたヨーロッパの国々が、民族の分布に関係なく緯線や経線を使って境界を決めたから。', exp: '国境が民族の住む地域と合っていないため、独立後に民族どうしの対立が起こる原因にもなりました。「ヨーロッパ」「植民地」「緯線・経線」が要点です。' },
      { lv: 2, q: '南アメリカ州の多くの国はスペイン語を話しますが、ブラジルの公用語は何語ですか。', choices: ['英語', 'フランス語', 'ポルトガル語', 'オランダ語'], a: 'C(ポルトガル語)', exp: 'ブラジルはかつてポルトガルの植民地だったため、ポルトガル語が公用語です。ほかの多くの国はスペインの植民地だったのでスペイン語を話します。' },
      { lv: 2, q: 'オーストラリアに古くから住んでいた先住民を何といいますか。', a: 'アボリジニ', exp: 'オーストラリアの先住民はアボリジニです。ニュージーランドの先住民マオリと混同しやすいので注意しましょう。' },
      { lv: 2, q: '熱帯の地域で、床を地面から高くした住居が見られるのはなぜですか。', a: '湿気や熱がこもるのを防ぎ、風通しをよくするため。', exp: '熱帯は暑くて雨が多く、地面がしめりやすいので、床を高くして風を通します。大雨のときの浸水を防ぐ役目もあります。' },
      { lv: 2, q: 'EU(ヨーロッパ連合)の多くの国で使われている共通の通貨を何といいますか。', a: 'ユーロ', exp: 'ユーロを使う国の間では両替が不要になり、国境をこえた買い物や貿易がしやすくなりました。ただしEU加盟国でもユーロを使っていない国があります。' },
      { lv: 3, q: '日本(東経135度)を3月20日午後9時に出発し、ロサンゼルス(西経120度)まで10時間飛んだ。到着したときのロサンゼルスの日時は?', a: '3月20日午後2時', exp: '日本の時刻で21時+10時間=翌3月21日7時に到着。時差は(135+120)÷15=17時間で、ロサンゼルスは17時間おくれるので、7−17=−10 → 前日の14時。出発した日付と同じ3月20日になります。' },
      { lv: 3, q: '赤道付近の地域が1年中暑いのはなぜですか。「太陽」という語を使って説明しなさい。', a: '赤道付近は1年を通じて太陽の光がほぼ真上から当たり、同じ面積が受けとる太陽のエネルギーが多いから。', exp: '光がななめに当たると、同じ量の光が広い面積に散らばるので、地面はあたたまりにくくなります。高緯度ほど寒いのは、このななめの当たり方が理由です。' },
      { lv: 3, q: 'オーストラリアのシドニーで、1年のうち平均気温がいちばん高くなるのは何月ごろですか。また、その理由も答えなさい。', a: '1月ごろ(12〜2月)。南半球にあり、北半球と季節が逆になるから。', exp: '地軸がかたむいたまま地球が太陽のまわりを回るので、北半球が冬のとき南半球は夏になります。雨温図で気温の山が1月付近にあれば南半球と判断できます。' },
      { lv: 3, q: '中国が外国の企業を招くために設けた経済特区が、おもに南部の沿岸部に置かれた理由を説明しなさい。', a: '港があり、原料の輸入や製品の輸出に便利で、外国(ホンコンなど)とも結びつきやすかったから。', exp: '経済特区は外国の資本や技術を取り入れるための地域です。沿岸部が発展した一方、内陸部との経済格差が課題になりました。' },
      { lv: 3, q: 'アメリカ合衆国の北緯37度付近より南の地域(サンベルト)に、先端技術産業が集まるようになった理由を説明しなさい。', a: '気候が温暖で、広い土地を安く使え、働く人も集めやすかったから。', exp: 'もともと工業の中心は五大湖周辺でしたが、20世紀後半からサンベルトでコンピューターや航空宇宙などの産業がさかんになりました。「温暖」「土地」「労働力」の3点が要点です。' }
    ]
  });

  /* ===== 中学地理:日本のすがた ===== */
  add('c_jgeo', {
    pat: [
      { name: '日本の東西南北の端の島', freq: 'よく出る', when: '「日本の最も東(西・南・北)にある島」や、その島が属する都道府県を聞かれたら、この型です。', how: ['北=択捉島(北海道)、南=沖ノ鳥島(東京都)、東=南鳥島(東京都)、西=与那国島(沖縄県)と4つセットで覚える。', '南と東はどちらも東京都の島だと注意する。', '沖ノ鳥島はなぜ護岸工事をしたかなど、排他的経済水域と結びつけて考える。'], ex: { q: '日本の最東端の島はどこで、何都道府県に属しますか。', a: '南鳥島(東京都)', exp: '最東端は南鳥島、最南端は沖ノ鳥島で、どちらも東京都に属します。北は北海道の択捉島、西は沖縄県の与那国島です。「南」と「東」の取りちがえに注意しましょう。' } },
      { name: '雨温図で日本の気候区を当てる', freq: 'とてもよく出る', when: '日本の都市の雨温図が数枚並んでいたら、この型です。', how: ['冬の降水量が多い → 日本海側の気候。', '夏の降水量が多く冬は少ない → 太平洋側の気候。', '1年中雨が少なく温暖 → 瀬戸内の気候。', '冬の気温が0℃を大きく下回る → 北海道の気候、気温の差が大きく雨が少ない → 内陸(中央高地)の気候。'], ex: { q: '冬(12〜2月)の降水量が多く、夏の降水量はそれより少ない都市は、どの気候に属しますか。', a: '日本海側の気候', exp: '冬に北西からふく季節風が、日本海の上で水蒸気をふくみ、山地にぶつかって雪や雨を降らせます。そのため日本海側では冬の降水量が多くなります。' } },
      { name: '統計表から工業地帯・地域を判定', freq: 'とてもよく出る', when: '工業地帯ごとの出荷額や業種別の割合のグラフ・表から「どれか」を答えさせる問題は、この型です。', how: ['出荷額がいちばん大きく、機械の割合がとても高い → 中京工業地帯。', '金属の割合が比較的高い → 阪神工業地帯。', '化学の割合が高い → 瀬戸内工業地域。', '数値の大小だけでなく、その理由(自動車工業・石油化学コンビナートなど)と結びつけて確かめる。'], ex: { q: '製造品出荷額が全国で最も多く、そのうち機械工業の割合が約7割をしめる工業地帯はどこですか。', a: '中京工業地帯', exp: '中京工業地帯は愛知県を中心に、自動車などの輸送用機械の生産がさかんなので、機械工業の割合がとても高くなります。出荷額も工業地帯の中で最大です。' } },
      { name: '排他的経済水域と離島の役割', freq: 'よく出る', when: '「なぜ小さな島を守るのか」「日本の国土面積に比べて海の面積が広いのはなぜか」と問われたら、この型です。', how: ['排他的経済水域は海岸線から200海里(約370km)と思い出す。', 'その範囲の水産資源や鉱産資源は、沿岸国が利用できることを確認する。', '島が1つあるだけで周りに広い水域が生まれる、と理由をつなげる。'], ex: { q: '沖ノ鳥島で、島が波にけずられてなくならないように護岸工事が行われたのはなぜですか。', a: '島がなくなると、周りの広い排他的経済水域を失うから。', exp: '沖ノ鳥島の周りには、日本の国土面積より広い排他的経済水域が広がっています。島が水没すると、その水域の水産資源や鉱産資源を利用する権利を失うおそれがあるため、工事が行われました。' } }
    ],
    more: [
      { lv: 1, q: '日本の最北端の島はどこですか。', a: '択捉島', exp: '択捉島は北方領土の1つで、北海道に属します。北方領土は現在ロシアが占拠しており、日本は返還を求めています。' },
      { lv: 1, q: '日本でいちばん長い川はどれですか。', choices: ['利根川', '石狩川', '信濃川', '北上川'], a: 'C(信濃川)', exp: '信濃川は長野県・新潟県を流れ、日本海に注ぐ日本最長の川です。流域面積が最大なのは利根川なので、「長さ」と「流域面積」を区別しましょう。' },
      { lv: 1, q: '日本の標準時子午線(東経135度)が通る兵庫県の市はどこですか。', a: '明石市', exp: '日本は東経135度の時刻を標準時としています。この経線は兵庫県明石市を通ります。' },
      { lv: 1, q: '夏に日本の太平洋側にふく季節風は、どの方角からふきますか。', a: '南東', exp: '夏は太平洋から南東の季節風がふき、太平洋側に雨を多く降らせます。冬は大陸から北西の季節風がふきます。' },
      { lv: 1, q: '排他的経済水域は、海岸線から何海里までの範囲ですか。', a: '200海里', exp: '200海里は約370kmです。領海(12海里)とまちがえやすいので、領海12海里・排他的経済水域200海里とセットで覚えましょう。' },
      { lv: 1, q: '日本列島の太平洋側を南から北へ流れる暖流を何といいますか。', a: '黒潮(日本海流)', exp: '黒潮は太平洋側を流れる暖流です。千島海流(親潮)は北から流れてくる寒流で、2つがぶつかる潮目はよい漁場になります。' },
      { lv: 1, q: '夏に東北地方の太平洋側にふき、冷害の原因となる冷たくしめった北東の風を何といいますか。', a: 'やませ', exp: 'やませがふくと日照時間が少なく気温が上がらないため、稲が育ちにくくなる冷害が起こることがあります。' },
      { lv: 2, q: '瀬戸内の地域で1年を通じて降水量が少ないのはなぜですか。', a: '北の中国山地と南の四国山地が、夏と冬の季節風をさえぎるから。', exp: '季節風は山地にぶつかる手前で雨や雪を降らせるので、山地にはさまれた瀬戸内には乾いた風がふきます。そのため水不足に備えて、ため池がつくられてきました。' },
      { lv: 2, q: '川が山地から平地に出るところに土砂が積もってできた、扇形でゆるやかな傾きの地形を何といいますか。また、その地形によく見られる土地利用は何ですか。', a: '扇状地。水はけがよいので果樹園に利用されることが多い。', exp: '扇状地は粒の大きい砂や小石が積もり、水がしみこみやすい土地です。そのため水田より果樹園に向いています。山梨県の甲府盆地が代表例です。' },
      { lv: 2, q: '三陸海岸のように、山地が海にしずんでできた、入り組んだ海岸を何といいますか。', a: 'リアス海岸', exp: 'リアス海岸は湾が深く波がおだやかなので、かきやわかめなどの養殖に向いています。一方、津波が湾の奥で高くなりやすいという弱点もあります。' },
      { lv: 2, q: '現在の日本の人口ピラミッドに最も近い形はどれですか。', choices: ['富士山型', 'つりがね型', 'つぼ型', '星型'], a: 'C(つぼ型)', exp: '少子高齢化が進み、子どもの割合が小さく高齢者の割合が大きいので、すそがすぼまったつぼ型になっています。富士山型は子どもが多い発展途上国に多い形です。' },
      { lv: 2, q: '高知平野や宮崎平野で、温暖な気候とビニールハウスを利用して、野菜をほかの地域より早い時期に出荷する栽培方法を何といいますか。', a: '促成栽培', exp: 'ほかの産地のものが少ない時期に出荷すると、高い値段で売れます。逆に、すずしい気候を生かして出荷を遅らせるのが抑制栽培です。' },
      { lv: 2, q: '北海道東部の根釧台地でさかんな農業は何ですか。', a: '酪農', exp: '根釧台地は夏でもすずしく、稲作や畑作に向かないため、牧草を育てて乳牛を飼う酪農がさかんです。' },
      { lv: 2, q: '中京工業地帯で、製造品出荷額がいちばん多い工業は何ですか。', a: '自動車などの輸送用機械をふくむ機械工業', exp: '愛知県豊田市などを中心に自動車工業がさかんで、関連する部品工場も周りに集まっています。' },
      { lv: 2, q: '山間部や離島などで人口が大きく減り、学校や病院、交通機関の維持が難しくなる状態を何といいますか。', a: '過疎', exp: '人口が減りすぎて地域の生活が成り立ちにくくなる状態が過疎です。反対に、人口が集中しすぎて交通渋滞などが起こる状態を過密といいます。' },
      { lv: 3, q: '日本は国土面積が約38万km²なのに、排他的経済水域をふくむ海の面積は、国土面積の10倍以上あります。その理由を説明しなさい。', a: '日本は島国で、周りに多くの離島が散らばっており、それぞれの島から200海里の排他的経済水域が広がるから。', exp: '海に囲まれた島国であることと、南鳥島や沖ノ鳥島のように遠くはなれた島があることの2点が理由です。' },
      { lv: 3, q: '東京都では、夜間人口よりも昼間人口のほうが多くなっています。その理由を説明しなさい。', a: '神奈川県・埼玉県・千葉県などの周りの県から、多くの人が東京都の会社や学校へ通勤・通学してくるから。', exp: '昼間は通勤・通学者が流れこみ、夜は自宅のある周りの県へ帰ります。そのため周りの県では、逆に夜間人口のほうが多くなります。' },
      { lv: 3, q: '太平洋ベルトに工業地帯・地域が集中した理由を、2つ説明しなさい。', a: '①原料を輸入し、製品を輸出するのに便利な港が多いから。②平野が広がり、働く人や製品を買う人が多く集まっていたから。', exp: '日本は鉄鉱石や石油などの原料の多くを輸入にたよるため、海ぞいが有利でした。人口が多いことは、労働力と市場の両方になります。' },
      { lv: 3, q: '1970年代以降、北関東などの内陸部に工業団地が多くつくられるようになった理由を説明しなさい。', a: '高速道路が整備され、トラックで部品や製品を運びやすくなったうえ、広い土地を安く手に入れやすかったから。', exp: '自動車や電子部品のように、軽くて高価な製品は港から遠くても運べます。高速道路のインターチェンジ付近に工業団地ができたのはこのためです。' },
      { lv: 3, q: '日本海側の地域で冬に雪が多くなるしくみを、「季節風」「日本海」「山地」の語を使って説明しなさい。', a: '大陸からの冷たい北西の季節風が、日本海をわたるときに水蒸気をふくみ、日本列島の山地にぶつかって雪を降らせるから。', exp: '大陸から来た風はもともと乾いていますが、日本海の上で水分を補給します。山をこえた太平洋側には乾いた風がふくので、冬は晴れの日が多くなります。' }
    ]
  });

  /* ===== 中学地理:地形図 ===== */
  add('c_chizu', {
    pat: [
      { name: '縮尺から実際の距離を出す', freq: 'とてもよく出る', when: '「地図上で〇cmの長さは、実際には何km(m)か」と聞かれたら、この型です。', how: ['地図上の長さ × 縮尺の分母 で、実際の長さ(cm)を出す。', 'cm → m は100でわる、m → km は1000でわる。', '逆に実際の長さから地図上の長さを求めるときは、分母でわる。'], ex: { q: '2万5千分の1の地形図で4cmの長さは、実際には何kmですか。', a: '1km', exp: '4×25000=100000cmです。100でわると1000m、さらに1000でわると1kmになります。2万5千分の1では「4cm=1km」と覚えておくと速く解けます。' } },
      { name: '等高線の間隔から縮尺を見ぬく', freq: 'よく出る', when: '地形図に縮尺が書かれておらず、等高線の数値だけがわかるときは、この型です。', how: ['細い主曲線の間隔を読む。', '主曲線が10mごとなら2万5千分の1、20mごとなら5万分の1。', '太い計曲線なら、50mごと=2万5千分の1、100mごと=5万分の1。'], ex: { q: 'ある地形図で、太い等高線(計曲線)が50mごとに引かれていました。この地形図の縮尺は何分の1ですか。', a: '2万5千分の1', exp: '2万5千分の1では主曲線10mごと・計曲線50mごと、5万分の1では主曲線20mごと・計曲線100mごとです。計曲線50mなので2万5千分の1とわかります。' } },
      { name: '面積の計算(長さを先に直す)', freq: 'よく出る', when: '地図上の長方形や正方形の範囲の「実際の面積」を聞かれたら、この型です。', how: ['たて・横それぞれを、先に実際の長さ(mやkm)に直す。', '直した長さどうしをかけ算する。', '1km²=1000m×1000m=1000000m²の換算に注意する。'], ex: { q: '2万5千分の1の地形図で、たて2cm・横3cmの長方形の範囲の実際の面積は何km²ですか。', a: '0.375km²', exp: 'たて2×25000=50000cm=500m、横3×25000=75000cm=750m。面積は500×750=375000m²です。1km²=1000000m²なので0.375km²になります。地図上の面積に分母をかけるだけではまちがいです。' } },
      { name: '尾根と谷を等高線から見分ける', freq: 'よく出る', when: '等高線の曲がり方が示され、「尾根か谷か」「川はどこを流れるか」を問われたら、この型です。', how: ['等高線の数値で、どちらが高い側かを確かめる。', '等高線が高い側へ食いこんでいれば谷、低い側へはり出していれば尾根。', '川は谷を通り、高い方から低い方へ流れる。'], ex: { q: '等高線が、標高の高い側へV字形に食いこんでいる場所は、尾根と谷のどちらですか。', a: '谷', exp: '谷は周りより低いので、同じ高さの線が奥(高い側)まで入りこみます。尾根はその反対で、等高線が低い側へはり出します。川は谷に沿って流れます。' } },
      { name: '2地点の傾き(勾配)を求める', freq: '難関校で出る', when: '2地点の標高と、地図上の距離が示されて「どちらが急か」「傾きは何分の1か」を問われたら、この型です。', how: ['地図上の距離を実際の水平距離(m)に直す。', '2地点の標高の差を求める。', '標高差 ÷ 水平距離 で勾配を出し、分数で比べる。'], ex: { q: '2万5千分の1の地形図で、2cmはなれた2地点の標高差が100mでした。この間の平均の勾配は何分の1ですか。', a: '5分の1', exp: '水平距離は2×25000=50000cm=500mです。勾配は100÷500=5分の1になります。分母が小さいほど急な坂を表します。' } }
    ],
    more: [
      { lv: 1, q: '2万5千分の1の地形図で1cmの長さは、実際には何mですか。', a: '250m', exp: '1×25000=25000cm=250mです。cmからmに直すときは100でわります。' },
      { lv: 1, q: '5万分の1の地形図で、細い等高線(主曲線)は何mごとに引かれていますか。', a: '20m', exp: '5万分の1では主曲線20mごと、計曲線100mごとです。2万5千分の1(主曲線10mごと)と区別しましょう。' },
      { lv: 1, q: '「卍」の地図記号は何を表しますか。', choices: ['神社', '寺院', '城あと', '史跡'], a: 'B(寺院)', exp: '卍は寺院の記号です。神社は鳥居の形「⛩」で表します。寺院と神社の取りちがえはよくあるまちがいです。' },
      { lv: 1, q: '「文」の地図記号は何を表しますか。', a: '小・中学校', exp: '「文」は小学校・中学校を表します。高等学校は「文」を丸で囲んだ記号です。' },
      { lv: 1, q: '方位記号がない地形図では、上はどの方位を表しますか。', a: '北', exp: '地形図は、ふつう上が北になるようにかかれています。方位記号がないときは「上が北」と考えます。' },
      { lv: 1, q: '等高線の間隔がせまいところは、傾きがゆるやかですか、急ですか。', a: '急', exp: '間隔がせまいということは、短い水平距離で高さが大きく変わるということです。だから傾きが急になります。' },
      { lv: 1, q: '昔の消火の道具「さすまた」の形をもとにした地図記号は、何を表しますか。', a: '消防署', exp: '消防署の記号は、江戸時代の火消しが使った道具「さすまた」がもとになっています。交番(×印)と区別しましょう。' },
      { lv: 2, q: '5万分の1の地形図で3cmの長さは、実際には何kmですか。', a: '1.5km', exp: '3×50000=150000cm=1500m=1.5kmです。5万分の1では「2cm=1km」と覚えると便利です。' },
      { lv: 2, q: '実際の距離2kmは、2万5千分の1の地形図上では何cmになりますか。', a: '8cm', exp: '2km=200000cmです。これを25000でわると8cmになります。実際→地図は「分母でわる」と覚えましょう。' },
      { lv: 2, q: '2万5千分の1の地形図で、1辺4cmの正方形の範囲の実際の面積は何km²ですか。', a: '1km²', exp: '1辺は4×25000=100000cm=1kmなので、面積は1km×1km=1km²です。長さを先に直してからかけ算するのがコツです。' },
      { lv: 2, q: '太い等高線(計曲線)が100mごとに引かれている地形図の縮尺は何分の1ですか。', a: '5万分の1', exp: '計曲線が100mごとなら5万分の1、50mごとなら2万5千分の1です。主曲線(20mと10m)の場合もあわせて覚えましょう。' },
      { lv: 2, q: '扇状地の中央部(扇央)で多く見られる土地利用はどれですか。', choices: ['水田', '果樹園', '工業地帯', '港'], a: 'B(果樹園)', exp: '扇央は砂や小石が積もって水はけがよいので、水田には向かず果樹園に使われます。水がわき出る扇端には集落や水田が見られます。' },
      { lv: 2, q: '川が海に流れこむあたりに、細かい土砂が積もってできた低く平らな地形を何といいますか。', a: '三角州', exp: '三角州は河口付近にできる低く平らな土地で、水田や市街地に利用されます。広島市の中心部が代表例です。' },
      { lv: 2, q: '等高線が、標高の低い側へはり出している場所は、尾根と谷のどちらですか。', a: '尾根', exp: '尾根は山の高いところが続く部分で、周りより高いので等高線が低い側へはり出します。谷はその逆で、高い側へ食いこみます。' },
      { lv: 2, q: '5万分の1の地形図で、たて2cm・横5cmの長方形の範囲の実際の面積は何km²ですか。', a: '2.5km²', exp: 'たて2×50000=100000cm=1km、横5×50000=250000cm=2.5km。面積は1×2.5=2.5km²です。' },
      { lv: 3, q: 'ある地図で10cmの長さが、実際には2.5kmでした。この地図の縮尺は何分の1ですか。', a: '2万5千分の1', exp: '2.5km=250000cmです。250000÷10=25000なので、縮尺は2万5千分の1です。単位をcmにそろえてから比べましょう。' },
      { lv: 3, q: '同じ範囲を、2万5千分の1の地図と5万分の1の地図にかきました。5万分の1の地図での面積は、2万5千分の1の地図での面積の何倍になりますか。', a: '4分の1倍', exp: '5万分の1では長さがたて・横ともに半分になるので、面積は1/2×1/2=1/4になります。長さの比をそのまま面積に使わないことが大切です。' },
      { lv: 3, q: '2万5千分の1の地形図で、標高150mの地点Aと標高50mの地点Bが、地図上で8cmはなれています。AB間の平均の勾配は何分の1ですか。', a: '20分の1', exp: '水平距離は8×25000=200000cm=2000m、標高差は150−50=100mです。勾配は100÷2000=20分の1です。' },
      { lv: 3, q: '地形図で、川の両側の等高線がV字形になって上流側を指していました。この川はどちら向きに流れていると考えられますか。理由もあわせて答えなさい。', a: 'V字の先が指す方とは反対の、標高の低い方へ流れている。谷の等高線は高い側(上流側)へ食いこむから。', exp: '等高線のV字の先は、より高い上流側を指しています。川は高い方から低い方へ流れるので、V字の開いている側へ流れます。' },
      { lv: 3, q: '標高80mの地点Aと標高70mの地点Bの間に、標高120mの尾根があります。地点Aから地点Bを直接見通すことはできますか。理由も答えなさい。', a: '見通せない。AとBを結ぶ視線よりも、間にある尾根のほうが高く、視線がさえぎられるから。', exp: '断面図をかくと、AとBを結んだ直線はおよそ70〜80mの高さを通るのに、間の尾根は120mあるので、視線が山にぶつかります。見通しの問題は断面図をかいて考えます。' }
    ]
  });

  /* ===== 中学歴史:古代 ===== */
  add('c_ancient', {
    pat: [
      { name: '古代のできごとの並べかえ', freq: 'とてもよく出る', when: '「次のできごとを古い順に並べなさい」とあり、飛鳥〜平安のできごとが並んでいたら、この型です。', how: ['それぞれのできごとが「何世紀・どの天皇や人物のときか」を思い出す。', '年代を書き出せないときは、因果(原因→結果)で順番を決める。', 'たとえば「口分田が足りない → 墾田永年私財法 → 荘園が広がる」のように鎖にする。'], ex: { q: '次を古い順に並べなさい。ア 墾田永年私財法 イ 大化の改新 ウ 大宝律令', a: 'イ→ウ→ア', exp: '大化の改新は645年、大宝律令は701年、墾田永年私財法は743年です。改新で公地公民の方針が示され、律令で制度が整い、その後口分田が不足して私有を認めた、という流れで覚えましょう。' } },
      { name: '文化財と時代の組み合わせ', freq: 'とてもよく出る', when: '寺院・仏像・文学作品などの名前や写真があり、「どの時代の文化か」を問われたら、この型です。', how: ['飛鳥文化=法隆寺(仏教がはじめて栄えた)。', '天平文化=東大寺・正倉院(唐の影響が強い)。', '国風文化=平等院鳳凰堂・かな文字の文学(日本風)。', '作品の特徴(国際的か、日本風か)で時代を決める。'], ex: { q: '法隆寺が建てられた時期の文化を何といいますか。', a: '飛鳥文化', exp: '法隆寺は聖徳太子が建てたとされる寺で、現存する世界最古の木造建築として知られます。日本で初めて仏教を中心に栄えた飛鳥文化を代表する建物です。' } },
      { name: '律令の税(租・調・庸)の区別', freq: 'よく出る', when: '「稲」「地方の特産物」「布」「都での労役」などの語があり、税の名前を問われたら、この型です。', how: ['租=口分田の収穫の約3%の稲を納める。', '調=地方の特産物を納める(都まで運ぶ)。', '庸=都での労役のかわりに布を納める。', 'ほかに雑徭(地方での労役)、兵役(防人など)もあると整理する。'], ex: { q: '口分田の収穫のうち約3%の稲を納める税を何といいますか。', a: '租', exp: '租は稲で納め、おもに地方(国府)に納められました。調と庸は都まで自分で運ばなければならず、農民にとって大きな負担でした。' } },
      { name: '政策の「結果」を説明する(墾田永年私財法など)', freq: 'よく出る', when: '「この法令が出された結果、どのような変化が起こったか」と問われたら、この型です。', how: ['法令の内容を一言でまとめる(何を認めた/禁じたか)。', 'だれが得をしたかを考える(貴族・寺社など)。', 'その結果、しくみがどう変わったか(公地公民がくずれる)を書く。'], ex: { q: '墾田永年私財法が出された結果、どのような変化が起こりましたか。', a: '貴族や寺社が開墾を進めて私有地(のちの荘園)を広げ、公地公民のしくみがくずれていった。', exp: '新しく開墾した土地の永久私有を認めたので、人や道具を集められる貴族や寺社が土地を広げました。土地をすべて国のものとする公地公民の原則が、ここから崩れていきます。' } }
    ],
    more: [
      { lv: 1, q: '3世紀ごろ、卑弥呼が治めていた国を何といいますか。', a: '邪馬台国', exp: '中国の歴史書『魏志』倭人伝に、邪馬台国の女王卑弥呼が魏に使いを送ったことが書かれています。' },
      { lv: 1, q: '縄目の文様がつけられた土器が使われていた時代を何といいますか。', a: '縄文時代', exp: '縄文時代の人々は狩りや漁、木の実の採集で暮らし、たて穴住居に住んでいました。' },
      { lv: 1, q: '大陸から伝わった稲作が広まり、高床倉庫がつくられた時代を何といいますか。', a: '弥生時代', exp: '弥生時代には稲作が広まり、米をたくわえる高床倉庫がつくられました。たくわえの差から、身分の差や争いも生まれました。' },
      { lv: 1, q: '大阪府堺市にある大仙古墳(仁徳天皇陵古墳)は、どのような形の古墳ですか。', choices: ['円墳', '方墳', '前方後円墳', '上円下方墳'], a: 'C(前方後円墳)', exp: '大仙古墳は日本最大の前方後円墳です。前が四角、後ろが円の形で、大和政権の大王の墓と考えられています。' },
      { lv: 1, q: '役人の心がまえを示した十七条の憲法を定めた人物はだれですか。', a: '聖徳太子(厩戸皇子)', exp: '聖徳太子は推古天皇のもとで、蘇我馬子と協力して政治を行いました。冠位十二階や遣隋使の派遣も行いました。' },
      { lv: 1, q: '710年に奈良につくられた都を何といいますか。', a: '平城京', exp: '平城京は唐の都長安にならってつくられ、碁盤の目のように道路が整えられていました。794年には平安京に都がうつります。' },
      { lv: 1, q: '紫式部がかな文字を使って書いた長編の物語は何ですか。', a: '源氏物語', exp: '源氏物語は国風文化を代表する作品です。同じころ清少納言は随筆の『枕草子』を書きました。' },
      { lv: 2, q: '645年、中大兄皇子とともに蘇我氏をたおし、大化の改新を始めた人物はだれですか。', a: '中臣鎌足', exp: '中臣鎌足はのちに藤原の姓をあたえられ、藤原氏の祖先となりました。中大兄皇子はのちの天智天皇です。' },
      { lv: 2, q: '大化の改新で示された「公地公民」とは、どのような方針ですか。', a: '豪族が支配していた土地と人々を、国(天皇)が直接支配するという方針。', exp: 'それまで土地や人々は豪族が私有していました。公地公民によって、国が土地を人々に分けあたえ、税をとるしくみがめざされました。' },
      { lv: 2, q: '仏教の力で国を守ろうとして、東大寺に大仏をつくらせた天皇はだれですか。', a: '聖武天皇', exp: '奈良時代には伝染病やききんが続きました。聖武天皇は国ごとに国分寺・国分尼寺を建て、都には東大寺と大仏をつくらせました。' },
      { lv: 2, q: '班田収授法で、6歳以上の男女にあたえられた田を何といいますか。', a: '口分田', exp: '口分田は戸籍にもとづいてあたえられ、死ぬと国に返すきまりでした。この田の収穫から租を納めました。' },
      { lv: 2, q: '九州北部の守りのために、おもに東国から送られた兵士を何といいますか。', a: '防人', exp: '白村江の戦いのあと、唐や新羅の攻撃に備えて九州北部に置かれました。防人の歌は『万葉集』にも収められています。' },
      { lv: 2, q: '894年に遣唐使の停止を提案した人物はだれですか。', a: '菅原道真', exp: '唐がおとろえていたことや、航海が危険なことを理由に提案しました。これ以後、日本風の国風文化が発達していきます。' },
      { lv: 2, q: '摂関政治が最もさかんだったときの中心人物を、父と子の組み合わせで答えなさい。', a: '藤原道長と藤原頼通', exp: '道長は娘を次々と天皇のきさきにして権力をふるいました。子の頼通は平等院鳳凰堂を建てました。' },
      { lv: 2, q: 'メソポタミア文明が栄えた川の組み合わせはどれですか。', choices: ['ナイル川', 'チグリス川・ユーフラテス川', 'インダス川', '黄河'], a: 'B(チグリス川・ユーフラテス川)', exp: 'メソポタミア文明はチグリス川・ユーフラテス川の流域で栄え、くさび形文字や太陰暦が使われました。ナイル川はエジプト文明です。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 壬申の乱 イ 大宝律令の制定 ウ 白村江の戦い', a: 'ウ→ア→イ', exp: '白村江の戦いは663年、壬申の乱は672年、大宝律令は701年です。白村江で敗れたあと国の守りを固め、天智天皇の死後の後継ぎ争い(壬申の乱)に勝った天武天皇のもとで律令づくりが進みました。' },
      { lv: 3, q: '奈良時代に墾田永年私財法が出された背景を説明しなさい。', a: '人口がふえたうえ、重い税からにげる人も出て、あたえるための口分田が不足したから。', exp: '開墾をすすめるため、まず三世一身法(723年)で3代までの私有を認めましたが、効果がうすかったため、743年に永久私有を認めました。' },
      { lv: 3, q: '藤原氏が摂政・関白として大きな権力をもつことができた理由を説明しなさい。', a: '娘を天皇のきさきにし、生まれた子を天皇に立てて、天皇の母方の祖父(外戚)として政治の実権をにぎったから。', exp: '天皇が幼いときは摂政、成人後は関白として政治を行いました。天皇との親せき関係が力の源だったことがポイントです。' },
      { lv: 3, q: '平安時代の中ごろに国風文化が生まれた背景を説明しなさい。', a: '遣唐使が停止されたあと、それまでに取り入れた唐の文化をもとに、日本の風土や生活に合った文化が発達したから。', exp: 'かな文字、寝殿造、大和絵などが代表です。唐の文化をすてたのではなく、日本風に作りかえた点が大切です。' },
      { lv: 3, q: '奈良・平安時代の僧について述べた文として正しいものはどれですか。', choices: ['鑑真は何度も渡航に失敗しながら唐から来日し、唐招提寺を開いた。', '行基は朝廷に命じられて遣唐使となり、唐で仏教を学んだ。', '空海は比叡山に延暦寺を開き、天台宗を広めた。', '最澄は高野山に金剛峯寺を開き、真言宗を広めた。'], a: 'A(鑑真は何度も渡航に失敗しながら唐から来日し、唐招提寺を開いた。)', exp: '比叡山・延暦寺・天台宗は最澄、高野山・金剛峯寺・真言宗は空海です。行基は民衆に布教しながら橋や池をつくり、のちに大仏づくりに協力しました。' }
    ]
  });

  /* ===== 中学歴史:中世 ===== */
  add('c_medieval', {
    pat: [
      { name: '鎌倉幕府と室町幕府のしくみの比較', freq: 'とてもよく出る', when: '「将軍を補佐する役職」「地方の監視役」など、幕府の役職名を問われたら、この型です。', how: ['鎌倉=執権(北条氏)、京都の監視に六波羅探題。', '室町=管領(細川・斯波・畠山氏)、関東に鎌倉府。', '問題文の時代(承久の乱の後か、足利氏か)を確かめて、どちらの幕府か決める。'], ex: { q: '室町幕府で、将軍を補佐した役職を何といいますか。', a: '管領', exp: '鎌倉幕府の「執権」と、室町幕府の「管領」はよくすりかえられます。鎌倉=北条氏の執権、室町=有力な守護大名がつく管領、とセットで覚えましょう。' } },
      { name: '御恩と奉公を説明する', freq: 'とてもよく出る', when: '「将軍と御家人の関係」を説明させる記述問題は、この型です。', how: ['御恩=将軍が御家人の領地を認めたり、新しい領地をあたえたりすること。', '奉公=御家人が京都や鎌倉の警備をし、戦いのときに命がけで戦うこと。', '「土地」を仲立ちにした主従関係だとまとめる。'], ex: { q: '鎌倉時代の「御恩」とは何ですか。', a: '将軍が御家人の先祖からの領地を保護したり、手がらに応じて新しい領地をあたえたりすること。', exp: '御恩と奉公は、土地を仲立ちにした将軍と御家人の主従関係です。元寇のあと御恩(恩賞の土地)が十分にあたえられず、この関係がゆらいだことも出題されます。' } },
      { name: '室町時代の一揆の区別', freq: 'よく出る', when: '「土一揆」「国一揆」「一向一揆」の名前と内容の組み合わせを問われたら、この型です。', how: ['正長の土一揆(1428年)=農民が借金の帳消し(徳政)を求めた。', '山城の国一揆(1485年)=武士と農民が守護大名を追い出し、自治を行った。', '加賀の一向一揆(1488年)=浄土真宗の信者が守護大名をたおし、約100年自治を行った。', '「だれが」「何を求めたか」で見分ける。'], ex: { q: '浄土真宗(一向宗)の信者が守護大名をたおし、約100年にわたって自治を行った一揆は何ですか。', a: '加賀の一向一揆', exp: '加賀(石川県南部)で起きた一向一揆です。宗教の信者の団結が特徴です。借金の帳消しを求めた正長の土一揆、守護大名の軍を追い出した山城の国一揆と区別しましょう。' } },
      { name: '中世の文化と人物の組み合わせ', freq: 'とてもよく出る', when: '人物名と作品名が並び「正しい組み合わせ」を選ばせる問題は、この型です。', how: ['鎌倉=運慶ら(東大寺南大門の金剛力士像)、『平家物語』、『徒然草』(兼好法師)、『方丈記』(鴨長明)。', '室町=雪舟(水墨画)、観阿弥・世阿弥(能)、金閣(足利義満)、銀閣(足利義政)。', '人物から作品、作品から人物の両方向で言えるか確かめる。'], ex: { q: '日本の水墨画を大成した室町時代の画僧はだれですか。', a: '雪舟', exp: '雪舟は中国(明)にわたって水墨画を学び、日本の風景をえがきました。能を大成した世阿弥と、どちらも室町時代なのでとりちがえに注意しましょう。' } }
    ],
    more: [
      { lv: 1, q: '1192年に征夷大将軍に任じられた人物はだれですか。', a: '源頼朝', exp: '源頼朝は1185年に守護・地頭を置き、1192年に征夷大将軍になりました。鎌倉幕府は鎌倉を本拠地としました。' },
      { lv: 1, q: '鎌倉幕府で、将軍を補佐する役職を何といいますか。', a: '執権', exp: '執権の地位は北条氏が代々受けつぎ、幕府の実権をにぎりました。これを執権政治といいます。' },
      { lv: 1, q: '1221年に、朝廷の力を取りもどそうとして承久の乱を起こした上皇はだれですか。', a: '後鳥羽上皇', exp: '幕府軍が勝利し、後鳥羽上皇は隠岐に流されました。これにより幕府の力が西国にもおよぶようになりました。' },
      { lv: 1, q: '元寇(文永の役・弘安の役)のときの鎌倉幕府の執権はだれですか。', a: '北条時宗', exp: '北条時宗はフビライ・ハンの服属の要求を退け、2度の元の襲来に対応しました。' },
      { lv: 1, q: '室町幕府を開いた人物はだれですか。', a: '足利尊氏', exp: '足利尊氏は後醍醐天皇と対立し、京都に新しい天皇を立てて征夷大将軍になりました。' },
      { lv: 1, q: '京都の北山に金閣を建てた室町幕府の将軍はだれですか。', choices: ['足利尊氏', '足利義満', '足利義政', '足利義昭'], a: 'B(足利義満)', exp: '金閣は足利義満、銀閣は足利義政です。義満は南北朝を統一し、日明貿易も始めました。' },
      { lv: 1, q: '武士として初めて太政大臣になった人物はだれですか。', a: '平清盛', exp: '平清盛は娘を天皇のきさきにして権力をにぎり、兵庫の港(大輪田泊)を整えて日宋貿易を行いました。' },
      { lv: 2, q: '1232年に、武士の裁判の基準として御成敗式目を定めた執権はだれですか。', a: '北条泰時', exp: '御成敗式目は武士の慣習をもとにした、最初の武家法です。のちの武家の法律の手本になりました。' },
      { lv: 2, q: '承久の乱のあと、朝廷の監視や西国の御家人の統率のために、京都に置かれた機関を何といいますか。', a: '六波羅探題', exp: '承久の乱で上皇側についた貴族や武士の領地は取り上げられ、東国の御家人が地頭として送りこまれました。' },
      { lv: 2, q: '1297年に鎌倉幕府が出した永仁の徳政令の目的は何ですか。', a: '生活に苦しむ御家人を救うため、御家人が売ったり質に入れたりした土地を、ただで取りもどさせること。', exp: '元寇の負担や分割相続で御家人は苦しくなっていました。しかし徳政令の後はお金を貸す人がいなくなり、かえって混乱しました。' },
      { lv: 2, q: '後醍醐天皇の建武の新政が、約2年でくずれたのはなぜですか。', a: '公家を重んじる政治を行ったため、幕府をたおすのに活躍した武士たちの不満が高まったから。', exp: '恩賞が公家にかたよったことなどに武士が反発し、足利尊氏が兵をあげました。その後、南朝と北朝が対立する南北朝時代になります。' },
      { lv: 2, q: '日明貿易で「勘合」という証明書が使われたのはなぜですか。', a: '正式な貿易船と、倭寇(海賊)の船を区別するため。', exp: '明は倭寇の取りしまりを求めていました。足利義満は倭寇を取りしまり、勘合をもった船だけで貿易を行いました。' },
      { lv: 2, q: '1467年に始まった応仁の乱の原因として正しいものはどれですか。', choices: ['元の襲来への恩賞の不足', '将軍のあとつぎ問題と、有力な守護大名どうしの対立', '後鳥羽上皇の挙兵', 'キリスト教の禁止'], a: 'B(将軍のあとつぎ問題と、有力な守護大名どうしの対立)', exp: '8代将軍足利義政のあとつぎ争いに、細川氏と山名氏の対立が結びつき、京都を中心に約11年続きました。' },
      { lv: 2, q: '戦国時代に広がった「下剋上」とは、どのような風潮ですか。', a: '身分の下の者が、実力で上の者をたおして地位をうばう風潮。', exp: '応仁の乱のあと幕府の力がおとろえ、家来が主君をたおして戦国大名になる例が各地で見られました。' },
      { lv: 2, q: '銀閣と同じ敷地にある東求堂同仁斎に見られ、たたみや床の間をもつ、現在の和室のもとになった建築様式を何といいますか。', a: '書院造', exp: '書院造は室町時代の東山文化を代表する様式です。平安時代の貴族の住まいである寝殿造と区別しましょう。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 文永の役 イ 承久の乱 ウ 御成敗式目の制定', a: 'イ→ウ→ア', exp: '承久の乱は1221年、御成敗式目は1232年、文永の役は1274年です。乱のあと西国にも御家人が広がり、裁判の基準が必要になって式目がつくられた、という因果で覚えましょう。' },
      { lv: 3, q: '元寇のあと、御家人の幕府への不満が高まった理由を説明しなさい。', a: '国を守る戦いだったため新しい領地が得られず、御家人は戦いの費用を負担したのに、十分な恩賞(御恩)をもらえなかったから。', exp: '奉公に対して御恩があたえられない状態になり、御恩と奉公の関係がゆらぎました。これが幕府がほろぶ原因の1つになります。' },
      { lv: 3, q: '守護大名と戦国大名のちがいを説明しなさい。', a: '守護大名は幕府に任命された守護が力を強めたもので、幕府の権威にたよっていた。戦国大名は幕府から独立し、自分の実力で領国を支配し、分国法などを定めた。', exp: '「幕府に任命されたか、実力で支配したか」がいちばんのちがいです。戦国大名には守護大名が成長した者も、家来から下剋上で成り上がった者もいます。' },
      { lv: 3, q: '鎌倉・室町時代の文化について述べた文として正しいものはどれですか。', choices: ['運慶らは、東大寺南大門の金剛力士像をつくった。', '雪舟は、観阿弥とともに能を大成した。', '世阿弥は、明にわたって水墨画を学んだ。', '兼好法師は、随筆『方丈記』を書いた。'], a: 'A(運慶らは、東大寺南大門の金剛力士像をつくった。)', exp: '能を大成したのは観阿弥・世阿弥の父子、水墨画は雪舟です。兼好法師の随筆は『徒然草』で、『方丈記』は鴨長明の作品です。' },
      { lv: 3, q: '室町時代の農民が、土一揆を起こすほど強く団結できたのはなぜですか。「惣」という語を使って説明しなさい。', a: '村ごとに惣とよばれる自治組織をつくり、寄合を開いておきてを定めるなど、ふだんから団結して村を運営していたから。', exp: '惣では農業用水の管理や祭りなどを自分たちで決めました。この団結が、借金の帳消しを求める土一揆などの力になりました。' }
    ]
  });

  /* ===== 中学歴史:近世 ===== */
  add('c_early', {
    pat: [
      { name: '三大改革(と田沼の政治)の人物・政策の組み合わせ', freq: 'とてもよく出る', when: '「目安箱」「囲米」「株仲間」など、政策の名前と人物を結びつける問題は、この型です。', how: ['享保の改革=徳川吉宗(目安箱・公事方御定書・上げ米の制)。', '田沼意次=株仲間を奨励し、商業の力で財政を立て直そうとした。', '寛政の改革=松平定信(囲米・棄捐令・朱子学以外を禁じる)。', '天保の改革=水野忠邦(株仲間の解散・上知令)。株仲間は「田沼=奨励、水野=解散」と逆の向きで出る。'], ex: { q: '株仲間の解散を命じたのは、どの改革のだれですか。', a: '天保の改革の水野忠邦', exp: '物価が上がる原因を、株仲間が商品の流通を独占していることだと考えて解散させました。田沼意次は反対に株仲間を奨励したので、向きのちがいに注意しましょう。' } },
      { name: '大名・朝廷・民衆の統制のしくみ', freq: 'よく出る', when: '「武家諸法度」「参勤交代」「親藩・譜代・外様」などの語が出てきたら、この型です。', how: ['武家諸法度=大名が守るべききまり。城の修理や大名どうしの結婚に許可が必要。', '参勤交代=1635年に3代将軍徳川家光が制度化。大名は1年おきに江戸と領地を往復。', '大名の配置=信頼できる親藩・譜代を要地に、外様は遠くに置いた。'], ex: { q: '参勤交代を武家諸法度に加え、制度として整えた将軍はだれですか。', a: '徳川家光', exp: '3代将軍徳川家光が1635年に制度化しました。往復の費用や江戸での生活費が大名の負担となり、大名の力をおさえる働きをしました。' } },
      { name: '鎖国へのできごとの並べかえ', freq: 'よく出る', when: '「島原・天草一揆」「ポルトガル船の来航禁止」「オランダ商館を出島へ」などを並べさせる問題は、この型です。', how: ['キリスト教の禁止が強まる流れでとらえる。', '島原・天草一揆(1637年)→ ポルトガル船の来航禁止(1639年)→ オランダ商館を出島へ移す(1641年)。', '一揆にキリスト教徒が多かったことが、ポルトガル船の禁止につながったと因果で結ぶ。'], ex: { q: '次を古い順に並べなさい。ア オランダ商館を出島に移す イ 島原・天草一揆 ウ ポルトガル船の来航を禁止する', a: 'イ→ウ→ア', exp: '一揆(1637年)にキリスト教の信者が多くいたため、布教を行うポルトガルの船の来航を禁じ(1639年)、最後にオランダ商館を出島に移して(1641年)鎖国の体制が完成しました。' } },
      { name: '外国船への対応が変わった理由', freq: 'とてもよく出る', when: '「異国船打払令」から「薪水給与令」へ変えた理由を問われたら、この型です。', how: ['1825年の異国船打払令=近づく外国船を砲撃して追い払う。', '1840年からのアヘン戦争で、清がイギリスに敗れたことを知る。', '日本も同じように攻められるのをおそれ、1842年に燃料や水をあたえて帰らせる方針(天保の薪水給与令)に改めた。'], ex: { q: '幕府が異国船打払令をやめ、外国船に燃料や水をあたえる方針に改めたのはなぜですか。', a: 'アヘン戦争で清がイギリスに敗れたことを知り、外国船を打ち払うと日本も攻められるおそれがあると考えたから。', exp: '答えの中心は「アヘン戦争」「清の敗北」「日本も危ない」の3つです。外国の力を知ったことで、強い姿勢をゆるめたという流れで説明します。' } }
    ],
    more: [
      { lv: 1, q: '安土の城下町で、市の税を免除し、座の特権をなくして商工業をさかんにした政策を何といいますか。', a: '楽市・楽座', exp: '織田信長の政策です。だれでも自由に商売ができるようにして、城下町に人や物を集めました。' },
      { lv: 1, q: '太閤検地や刀狩を行った人物はだれですか。', a: '豊臣秀吉', exp: '太閤検地で田畑の広さや収穫量を調べ、刀狩で農民から武器を取り上げました。これで武士と農民の区別(兵農分離)が進みました。' },
      { lv: 1, q: '1600年に、徳川家康が石田三成らを破った戦いを何といいますか。', a: '関ヶ原の戦い', exp: 'この戦いに勝った徳川家康は、1603年に征夷大将軍となり、江戸幕府を開きました。' },
      { lv: 1, q: '鎖国の間、長崎での貿易を許されたヨーロッパの国はどこですか。', choices: ['ポルトガル', 'スペイン', 'オランダ', 'イギリス'], a: 'C(オランダ)', exp: 'オランダはキリスト教の布教をしなかったため、出島で貿易を許されました。ヨーロッパの国で許されたのはオランダだけです。' },
      { lv: 1, q: '1549年に鹿児島に来て、日本にキリスト教を伝えた宣教師はだれですか。', a: 'フランシスコ・ザビエル', exp: 'ザビエルはイエズス会の宣教師です。その後、キリスト教は西日本を中心に広まり、キリシタン大名も現れました。' },
      { lv: 1, q: '「富嶽三十六景」をえがいた浮世絵師はだれですか。', a: '葛飾北斎', exp: '葛飾北斎は化政文化を代表する浮世絵師です。「東海道五十三次」をえがいた歌川広重と区別しましょう。' },
      { lv: 1, q: '江戸幕府が、大名が守るべききまりとして定めた法令を何といいますか。', a: '武家諸法度', exp: '武家諸法度では、城を勝手に修理することや、大名どうしが無断で結婚することなどが禁じられました。' },
      { lv: 2, q: '関ヶ原の戦いのころから徳川家に従った大名を何といいますか。', choices: ['親藩', '譜代大名', '外様大名', '旗本'], a: 'C(外様大名)', exp: '外様大名は江戸から遠い地域に置かれました。親藩は徳川家の一族、譜代大名は古くからの家来で、重要な地域に置かれました。' },
      { lv: 2, q: '目安箱を設けて民衆の意見を聞き、公事方御定書を定めた将軍はだれですか。', a: '徳川吉宗', exp: '8代将軍徳川吉宗の享保の改革です。新田開発や上げ米の制で、幕府の収入をふやそうとしました。' },
      { lv: 2, q: 'ききんに備えて米をたくわえさせる囲米を行った人物と、その改革の名前を答えなさい。', a: '松平定信・寛政の改革', exp: '寛政の改革では、旗本・御家人の借金を帳消しにする棄捐令も出されました。厳しい倹約令は人々の反発もまねきました。' },
      { lv: 2, q: '田沼意次の政治の特色として正しいものはどれですか。', choices: ['株仲間を解散させた。', '株仲間の結成を奨励し、営業税をとった。', '目安箱を設けた。', '上知令を出した。'], a: 'B(株仲間の結成を奨励し、営業税をとった。)', exp: '田沼意次は商人の経済力を利用して幕府の収入をふやそうとしました。株仲間の解散は水野忠邦、目安箱は徳川吉宗、上知令は水野忠邦です。' },
      { lv: 2, q: '『古事記伝』を書き、国学を大成した人物はだれですか。', a: '本居宣長', exp: '国学は、仏教や儒教が伝わる前の日本人の考え方を、古典から明らかにしようとする学問です。のちの尊王攘夷の考えにも影響しました。' },
      { lv: 2, q: 'オランダ語の解剖書を翻訳して『解体新書』を出版した人物を、1人答えなさい。', a: '杉田玄白(前野良沢)', exp: '杉田玄白・前野良沢らが翻訳しました。これをきっかけに、オランダ語で西洋の学問を学ぶ蘭学がさかんになりました。' },
      { lv: 2, q: '元禄文化は、おもにどの地域の町人を中心に栄えましたか。', a: '上方(京都・大阪)', exp: '元禄文化は上方の町人が中心で、井原西鶴や近松門左衛門が活躍しました。19世紀前半の化政文化は江戸の町人が中心です。' },
      { lv: 2, q: '天保の改革で水野忠邦が出したが、大名や旗本の反対でとりやめになった、江戸・大阪周辺の土地を幕府の領地にしようとした法令を何といいますか。', a: '上知令(上地令)', exp: '江戸・大阪周辺を幕府が直接おさめ、守りと財政を強めようとしましたが、領地を取り上げられる側が強く反対し、水野忠邦は失脚しました。' },
      { lv: 3, q: '参勤交代は、大名の力を弱める働きをしました。どのようなしくみで弱めたのか説明しなさい。', a: '大名に、江戸と領地を1年おきに往復させ、妻子を江戸に住まわせたため、行列の旅費や江戸での生活費に多くのお金を使わせることになったから。', exp: '大名の財政が苦しくなると、幕府に反抗する力がたくわえにくくなります。一方で、街道や宿場町が発達し、江戸の文化が地方に広まるきっかけにもなりました。' },
      { lv: 3, q: '江戸時代の中ごろから幕府の財政が苦しくなった理由を、「年貢米」と「商品」の語を使って説明しなさい。', a: '幕府の収入はおもに年貢米だったが、商品の生産や流通がさかんになって物価が上がり、お金で買う物が多くなって支出がふえたから。', exp: '米がたくさんとれると米の値段が下がり、かえって収入がへることもありました。「収入は米、支出はお金」というずれが財政難の原因です。' },
      { lv: 3, q: '19世紀前半に、ロシアやイギリスの船が日本の近海に現れるようになった中で、幕府が1825年に出した法令と、その内容を答えなさい。', a: '異国船打払令。清とオランダ以外の外国船が近づいたら、ためらわずに砲撃して追い払うよう命じた。', exp: 'この法令にもとづき、1837年にはアメリカの商船モリソン号が砲撃されました。これを批判した渡辺崋山や高野長英は処罰されました(蛮社の獄)。' },
      { lv: 3, q: '江戸幕府の政治について述べた文として正しいものはどれですか。', choices: ['松平定信は、上知令を出して江戸・大阪周辺を幕府領にしようとした。', '徳川吉宗は、裁判の基準として公事方御定書を定めた。', '田沼意次は、物価を下げるために株仲間を解散させた。', '水野忠邦は、目安箱を設けて民衆の意見を聞いた。'], a: 'B(徳川吉宗は、裁判の基準として公事方御定書を定めた。)', exp: '上知令と株仲間の解散は水野忠邦、目安箱は徳川吉宗です。人物と政策の組み合わせを入れかえた誤りの文に注意しましょう。' },
      { lv: 3, q: '江戸時代に、鎖国の中でも日本が外国とつながっていた4つの窓口のうち、朝鮮との交流の仲立ちをした藩はどこですか。また、朝鮮から将軍の代がわりなどに送られた使節を何といいますか。', a: '対馬藩。朝鮮通信使。', exp: '4つの窓口は、長崎(オランダ・中国)、対馬(朝鮮)、薩摩(琉球)、松前(アイヌの人々)です。鎖国といっても、完全に国を閉じたわけではありません。' }
    ]
  });

  /* ===== 中学歴史:近代 ===== */
  add('c_modern', {
    pat: [
      { name: '日米和親条約と日米修好通商条約の区別', freq: 'とてもよく出る', when: '開港地や条約の内容が示され「どちらの条約か」を問われたら、この型です。', how: ['日米和親条約(1854年)=下田・函館の2港を開く。燃料・水・食料の補給。', '日米修好通商条約(1858年)=大老井伊直弼が結ぶ。函館・神奈川(横浜)・長崎・新潟・兵庫(神戸)の5港で貿易。', '修好通商条約は不平等条約=領事裁判権を認め、関税自主権がない。'], ex: { q: '下田と函館の2港を開くことを決めた条約は何ですか。', a: '日米和親条約', exp: '1854年、ペリーとの間で結ばれました。この条約では貿易は始まっていません。貿易が始まるのは1858年の日米修好通商条約からです。' } },
      { name: '明治の改革の並べかえと内容', freq: 'とてもよく出る', when: '版籍奉還・廃藩置県・学制・徴兵令・地租改正などが並んでいたら、この型です。', how: ['版籍奉還(1869年)=藩主が土地と人民を天皇に返す。', '廃藩置県(1871年)=藩を廃止し、府・県を置いて政府が府知事・県令を送る。', '学制(1872年)・徴兵令(1873年)・地租改正(1873年)と「富国強兵」の柱を続ける。'], ex: { q: '次を古い順に並べなさい。ア 廃藩置県 イ 版籍奉還 ウ 徴兵令', a: 'イ→ア→ウ', exp: '版籍奉還は1869年、廃藩置県は1871年、徴兵令は1873年です。まず土地と人民を返させ、次に藩そのものをなくして中央集権を完成させ、そのうえで全国から兵を集めました。' } },
      { name: '条約改正の2段階', freq: 'とてもよく出る', when: '「領事裁判権の撤廃」と「関税自主権の回復」の年や人物を問われたら、この型です。', how: ['1894年=外務大臣陸奥宗光が、イギリスとの間で領事裁判権の撤廃に成功(日清戦争の直前)。', '1911年=外務大臣小村寿太郎が、関税自主権の完全な回復に成功。', '国力(憲法・議会の整備、戦争の勝利)が認められて改正が進んだ、と因果でまとめる。'], ex: { q: '1911年に関税自主権の完全な回復に成功した外務大臣はだれですか。', a: '小村寿太郎', exp: '領事裁判権の撤廃(1894年・陸奥宗光)と、関税自主権の回復(1911年・小村寿太郎)は、人物と内容をすりかえて出題されます。「むつ・りょうじ」「こむら・かんぜい」とセットで覚えましょう。' } },
      { name: '選挙権の拡大(グラフ)', freq: 'とてもよく出る', when: '有権者の割合がふえていくグラフや、選挙権の条件の表が出たら、この型です。', how: ['1889年=直接国税15円以上を納める満25歳以上の男子(人口の約1%)。', '1925年=納税額の制限をなくし、満25歳以上のすべての男子(普通選挙法)。', '1945年=満20歳以上のすべての男女(女性に初めて選挙権)。', 'グラフの大きな「段」がどの改正かを、条件の変化で説明する。'], ex: { q: '1925年の選挙法改正で、選挙権の条件はどう変わりましたか。', a: '納税額による制限がなくなり、満25歳以上のすべての男子に選挙権があたえられた。', exp: '納税の条件がなくなったので、有権者は人口の約20%にふえました。ただし女性にはまだ選挙権がありません。同じ年に治安維持法も制定されています。' } }
    ],
    more: [
      { lv: 1, q: '1853年に、軍艦4隻を率いて浦賀に来航したアメリカの使節はだれですか。', a: 'ペリー', exp: 'ペリーはアメリカ大統領の国書を持って開国を求めました。翌1854年に再び来て、日米和親条約が結ばれました。' },
      { lv: 1, q: '1867年に、政権を朝廷に返す大政奉還を行った江戸幕府の将軍はだれですか。', a: '徳川慶喜', exp: '15代将軍徳川慶喜が大政奉還を行いました。これに対して朝廷は王政復古の大号令を出し、天皇中心の政治にもどすことを宣言しました。' },
      { lv: 1, q: '1868年に、明治政府が新しい政治の方針を示したものを何といいますか。', a: '五箇条の御誓文', exp: '「広く会議を興し、万機公論に決すべし」など、会議を開いてみんなの意見で政治を行う方針が示されました。' },
      { lv: 1, q: '1889年に発布された大日本帝国憲法が、おもに手本とした国はどこですか。', choices: ['アメリカ', 'イギリス', 'ドイツ(プロイセン)', 'フランス'], a: 'C(ドイツ(プロイセン))', exp: '伊藤博文がヨーロッパで調べ、君主の権力が強いドイツ(プロイセン)の憲法を手本にしました。主権は天皇にありました。' },
      { lv: 1, q: '『学問のすゝめ』を書き、人間の平等や学ぶことの大切さを説いた人物はだれですか。', a: '福沢諭吉', exp: '「天は人の上に人を造らず人の下に人を造らず」という一文で知られます。文明開化の時期に広く読まれました。' },
      { lv: 1, q: '日清戦争の講和条約を何といいますか。', a: '下関条約', exp: '1895年に結ばれ、清は朝鮮の独立を認め、遼東半島・台湾などを日本にゆずり、賠償金を支払いました。' },
      { lv: 1, q: '1925年に、普通選挙法と同じ年に制定され、社会主義などの運動を取りしまった法律を何といいますか。', a: '治安維持法', exp: '選挙権を広げる一方で、政府は社会主義の運動が広がることを警戒し、治安維持法を定めました。' },
      { lv: 2, q: '1871年の廃藩置県とは、どのような改革ですか。', a: '藩を廃止して府と県を置き、中央から府知事・県令を送って治めさせた改革。', exp: 'それまで藩主が治めていた地域を、政府が直接治めるようになりました。中央集権国家のしくみがここで整いました。' },
      { lv: 2, q: '地租改正で、税のしくみはどのように変わりましたか。', a: '収穫高ではなく地価を基準にし、その3%を土地の所有者が現金で納めるようにした。', exp: '豊作・不作にかかわらず税が一定になり、政府の収入が安定しました。しかし農民の負担は軽くならず、反対一揆も起こり、1877年に2.5%に引き下げられました。' },
      { lv: 2, q: '1874年に民撰議院設立の建白書を出し、自由民権運動を始めた中心人物はだれですか。', a: '板垣退助', exp: '板垣退助らは、一部の藩の出身者が政治を動かすことを批判し、国民が選んだ議会を開くよう求めました。のちに自由党をつくりました。' },
      { lv: 2, q: '日清戦争後、ロシア・ドイツ・フランスの三国干渉によって、日本が清に返した地域はどこですか。', choices: ['台湾', '遼東半島', '山東半島', '樺太'], a: 'B(遼東半島)', exp: '三国干渉で遼東半島を返したことで、日本国内ではロシアへの反感が高まりました。のちにロシアがこの地を借りたことも対立を深めました。' },
      { lv: 2, q: '日露戦争の講和条約(ポーツマス条約)に対して、国民が不満をもち、日比谷焼き打ち事件が起こったのはなぜですか。', a: '戦争で大きな犠牲と負担を強いられたのに、賠償金が得られなかったから。', exp: '日本は増税などで戦費をまかないましたが、ロシアから賠償金をとれませんでした。樺太の南部や南満州の鉄道の権利などは得ています。' },
      { lv: 2, q: '第一次世界大戦中の1915年に、日本が中国に示し、山東省のドイツの権益を引きつぐことなどを求めた要求を何といいますか。', a: '二十一か条の要求', exp: '日本はヨーロッパの国々がアジアに力を注げないすきに、中国での権益を広げようとしました。中国では反日の感情が強まりました。' },
      { lv: 2, q: '1918年の米騒動のあとに成立した、初めての本格的な政党内閣の首相はだれですか。', a: '原敬', exp: '原敬は立憲政友会の総裁で、陸軍・海軍・外務以外の大臣を政党の党員で組織しました。爵位をもたないことから「平民宰相」とよばれました。' },
      { lv: 2, q: '1932年の五・一五事件で、海軍の青年将校らに暗殺された首相はだれですか。', a: '犬養毅', exp: 'この事件で政党内閣の時代は終わり、軍人などが首相となる内閣が続くようになりました。1936年の二・二六事件と区別しましょう。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 日英同盟 イ 韓国併合 ウ 三国干渉', a: 'ウ→ア→イ', exp: '三国干渉は1895年、日英同盟は1902年、韓国併合は1910年です。ロシアとの対立が深まって同盟を結び、日露戦争に勝ったのち韓国を併合した、という流れです。' },
      { lv: 3, q: '日米修好通商条約が日本にとって不平等だった点を2つ説明しなさい。', a: '①アメリカに領事裁判権を認め、日本で罪をおかしたアメリカ人を日本の法律で裁けなかった。②日本に関税自主権がなく、輸入品にかける税を自由に決められなかった。', exp: '同じ内容の条約を、オランダ・ロシア・イギリス・フランスとも結びました。この2点を改めることが、明治政府の大きな目標になりました。' },
      { lv: 3, q: '1890年の第1回衆議院議員選挙で、有権者が人口の約1%しかいなかったのはなぜですか。', a: '選挙権が、直接国税15円以上を納める満25歳以上の男子に限られていたから。', exp: '高い税を納められる地主などしか選挙権をもてませんでした。女性や、税を多く納められない人には選挙権がありませんでした。' },
      { lv: 3, q: '世界恐慌のあと、イギリスやフランスが行ったブロック経済とはどのような政策ですか。', a: '本国と植民地との間で貿易を行い、ほかの国からの輸入品には高い関税をかけて、しめ出す政策。', exp: '植民地の多い国は自分たちの経済を守れましたが、植民地の少ない日本・ドイツ・イタリアは、海外に領土を求める動きを強めました。' },
      { lv: 3, q: '1933年に日本が国際連盟を脱退したのはなぜですか。', a: '国際連盟が、リットン調査団の報告にもとづいて満州国を認めず、日本軍の占領地からの引きあげを求める勧告を採択したから。', exp: '満州事変(1931年)のあと日本は満州国をつくりましたが、国際社会に認められませんでした。脱退によって日本は国際的に孤立していきます。' }
    ]
  });

  /* ===== 中学歴史:現代 ===== */
  add('c_contemp', {
    pat: [
      { name: '戦後の民主化政策の内容', freq: 'とてもよく出る', when: '「財閥解体」「農地改革」などの語や、戦後改革の目的を問われたら、この型です。', how: ['政治=満20歳以上の男女に選挙権、日本国憲法の制定。', '経済=財閥解体(経済の独占をなくす)、農地改革(小作農を自作農に)、労働組合法など。', '教育=教育基本法(9年間の義務教育)。', '「軍国主義をなくし、民主化を進める」という目的とつなげる。'], ex: { q: '農地改革で、農村のようすはどう変わりましたか。', a: '政府が地主の土地を強制的に買い上げて小作人に安く売りわたしたので、自分の土地をもつ自作農が大はばにふえた。', exp: '地主と小作人の間の大きな格差が、戦前の農村の貧しさの原因と考えられていました。農地改革でその関係が大きく変わりました。' } },
      { name: '戦後外交と首相の組み合わせ', freq: 'とてもよく出る', when: '「〇〇条約を結んだときの首相」や、外交のできごとの並べかえは、この型です。', how: ['1951年=サンフランシスコ平和条約・日米安全保障条約(吉田茂)。', '1956年=日ソ共同宣言 → 国際連合加盟(鳩山一郎)。', '1965年=日韓基本条約、1972年=沖縄返還(佐藤栄作)。', '1972年=日中共同声明(田中角栄)、1978年=日中平和友好条約(福田赳夫)。'], ex: { q: '1972年に中国との国交を正常化した日中共同声明に調印した首相はだれですか。', a: '田中角栄', exp: '1972年には沖縄返還(佐藤栄作)と日中共同声明(田中角栄)が同じ年にあります。首相を入れかえた選択肢がよく出るので注意しましょう。' } },
      { name: '高度経済成長の始まり・影・終わり', freq: 'よく出る', when: '1950年代半ば〜1970年代前半の経済や公害についての問いは、この型です。', how: ['始まり=1950年代半ばから、年平均約10%の成長。', '影=四大公害病・過密と過疎 → 公害対策基本法(1967年)、環境庁(1971年)。', '終わり=1973年の石油危機(第四次中東戦争がきっかけ)。'], ex: { q: '日本の高度経済成長が終わるきっかけになった、1973年のできごとは何ですか。', a: '石油危機(オイルショック)', exp: '第四次中東戦争をきっかけに石油の価格が大きく上がり、安い石油にたよっていた日本経済は大きな打撃を受けました。翌1974年には戦後初めてのマイナス成長になりました。' } },
      { name: '冷戦のできごとの並べかえ', freq: 'よく出る', when: '朝鮮戦争・ベルリンの壁・マルタ会談・ソ連解体などが並んだら、この型です。', how: ['始まり=第二次世界大戦後、アメリカ中心の西側とソ連中心の東側が対立。', '朝鮮戦争(1950年)→ ベトナム戦争の激化(1960年代)。', 'ベルリンの壁崩壊・マルタ会談(1989年)→ 東西ドイツ統一(1990年)→ ソ連解体(1991年)。'], ex: { q: '次を古い順に並べなさい。ア ソ連の解体 イ 朝鮮戦争 ウ ベルリンの壁の崩壊', a: 'イ→ウ→ア', exp: '朝鮮戦争は1950年、ベルリンの壁崩壊は1989年、ソ連解体は1991年です。冷戦の終結(1989年のマルタ会談)とソ連解体は同じではないので、順番に注意しましょう。' } }
    ],
    more: [
      { lv: 1, q: '敗戦後の日本で、GHQ(連合国軍最高司令官総司令部)の最高司令官を務めたのはだれですか。', a: 'マッカーサー', exp: 'GHQはマッカーサーを最高司令官とし、日本政府に指令を出す間接統治の方法で占領政策を進めました。' },
      { lv: 1, q: '日本国憲法が施行されたのは何年何月何日ですか。', a: '1947年5月3日', exp: '公布は1946年11月3日、施行は1947年5月3日です。現在、11月3日は文化の日、5月3日は憲法記念日です。' },
      { lv: 1, q: '1950年に始まり、日本の経済に「特需」をもたらした戦争は何ですか。', a: '朝鮮戦争', exp: 'アメリカ軍が日本で大量の物資を買ったため、日本の経済は急速に回復しました。これを特需景気といいます。' },
      { lv: 1, q: '1964年の東京オリンピックの開幕に合わせて開通した高速鉄道は何ですか。', a: '東海道新幹線', exp: '東京〜新大阪間が開通しました。高速道路の整備も進み、高度経済成長を象徴するできごとになりました。' },
      { lv: 1, q: '四大公害病のうち、熊本県の八代海沿岸で発生した病気は何ですか。', choices: ['イタイイタイ病', '四日市ぜんそく', '水俣病', '新潟水俣病'], a: 'C(水俣病)', exp: '水俣病は工場排水にふくまれていた有機水銀が原因です。イタイイタイ病は富山県、四日市ぜんそくは三重県、新潟水俣病は新潟県です。' },
      { lv: 1, q: '1989年に、冷戦の象徴として東西に分けられていたドイツの都市で取りこわされた壁を何といいますか。', a: 'ベルリンの壁', exp: 'ベルリンの壁の崩壊の翌年、1990年に東西ドイツが統一されました。' },
      { lv: 1, q: '1973年の石油危機のきっかけとなった戦争は何ですか。', a: '第四次中東戦争', exp: 'アラブの産油国が石油の輸出を制限し、価格を大きく引き上げました。日本では物価が急に上がり、トイレットペーパーの買いだめなどが起こりました。' },
      { lv: 2, q: 'GHQが財閥解体を行った目的は何ですか。', a: '日本の経済を支配し、戦争にも協力した財閥をなくし、経済を民主化するため。', exp: '三井・三菱・住友・安田などの財閥は、多くの会社を支配していました。財閥を解体して、自由な競争ができる経済をめざしました。' },
      { lv: 2, q: '1950年に朝鮮戦争が始まると、GHQの指令でつくられ、のちに自衛隊となった組織を何といいますか。', a: '警察予備隊', exp: '警察予備隊(1950年)→ 保安隊(1952年)→ 自衛隊(1954年)と変わりました。在日アメリカ軍が朝鮮半島に出動したあとの、国内の治安を守るためでした。' },
      { lv: 2, q: '1951年に、サンフランシスコ平和条約と同じ日に結ばれ、アメリカ軍が日本にとどまることを認めた条約は何ですか。', a: '日米安全保障条約', exp: '平和条約で日本は独立を回復しましたが、同時に安全保障条約を結び、アメリカ軍の基地が日本に残ることになりました。' },
      { lv: 2, q: '1956年に日ソ共同宣言が結ばれた結果、同じ年に実現したことは何ですか。', choices: ['沖縄の返還', '国際連合への加盟', '東京オリンピックの開催', '日中国交正常化'], a: 'B(国際連合への加盟)', exp: 'それまでは、安全保障理事会の常任理事国であるソ連が日本の加盟に反対していました。ソ連との国交が回復し、加盟が認められました。' },
      { lv: 2, q: '公害問題の深刻化を受けて、1971年に国が設置した役所を何といいますか。', a: '環境庁', exp: '1967年に公害対策基本法が定められ、1971年に環境庁が置かれました。環境庁は2001年に環境省となりました。' },
      { lv: 2, q: '1972年に沖縄が日本に返還されたときの首相はだれですか。', a: '佐藤栄作', exp: '佐藤栄作は「核兵器をもたず、つくらず、もちこませず」という非核三原則をかかげました。返還後も沖縄には多くのアメリカ軍基地が残っています。' },
      { lv: 2, q: '1980年代後半に、株や土地の価格が実際の価値以上に大きく上がった経済の状態を何といいますか。', a: 'バブル経済', exp: '泡(バブル)のようにふくらんだ価格は、1990年代の初めに一気に下がりました。その後、日本の経済は長い不況に入りました。' },
      { lv: 2, q: '1965年に、韓国の政府を朝鮮半島の唯一の合法的な政府と認め、国交を正常化した条約を何といいますか。', a: '日韓基本条約', exp: '佐藤栄作内閣のときに結ばれました。北朝鮮とは、現在も国交が開かれていません。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 日韓基本条約 イ 日中平和友好条約 ウ 日ソ共同宣言', a: 'ウ→ア→イ', exp: '日ソ共同宣言は1956年、日韓基本条約は1965年、日中平和友好条約は1978年です。日中は1972年の共同声明で国交を正常化し、1978年に条約を結んだ、という2段階に注意しましょう。' },
      { lv: 3, q: '冷戦が始まると、アメリカの日本に対する占領政策はどのように変わりましたか。', a: '日本の民主化や非軍事化を重視する方針から、日本の経済の復興を優先し、日本をアジアで共産主義に対抗する国として育てる方針に変わった。', exp: '中国で共産党の政権ができ(1949年)、朝鮮戦争が始まったことで、アメリカは日本を西側の重要な仲間と考えるようになりました。' },
      { lv: 3, q: '石油危機のあと、日本の工業の中心はどのように変わりましたか。', a: '鉄鋼や石油化学など、多くの資源やエネルギーを使う工業から、自動車や電子機器など、省エネルギーで高い技術を生かす工業へと中心が移った。', exp: '工場では省エネルギーの技術開発が進み、日本は石油危機からいち早く立ち直りました。小型で燃費のよい自動車の輸出もふえました。' },
      { lv: 3, q: '1951年のサンフランシスコ平和条約で、ソ連などと講和できなかった理由を説明しなさい。', a: '冷戦のもとで、日本がアメリカなど西側の国々を中心に講和を結んだため、ソ連などの東側の国々は条約に調印しなかったから。', exp: 'ソ連とは1956年の日ソ共同宣言で国交を回復しましたが、平和条約はまだ結ばれていません。北方領土問題がその理由の1つです。' },
      { lv: 3, q: '日本の高度経済成長を支えた要因を2つ説明しなさい。', a: '①石油などの資源を安く輸入できたこと。②企業が新しい技術や機械に積極的に投資し、農村から都市へ移った若い労働力も豊富だったこと。', exp: 'ほかに、国民の貯蓄が多く企業に資金が回ったことや、所得がふえて家庭電化製品などがよく売れたことも挙げられます。1973年に安い石油の前提がくずれ、成長は終わりました。' }
    ]
  });

  /* ===== 中学歴史:時代の流れ ===== */
  add('c_m2', {
    pat: [
      { name: '西暦を世紀に直す', freq: 'とてもよく出る', when: '「〇〇年は何世紀か」「〇世紀に起きたできごとを選べ」と問われたら、この型です。', how: ['西暦の下2けたが00でなければ、百の位までの数に1を足す(1467年 → 14+1=15世紀)。', '下2けたが00ならそのままの数(1600年 → 16世紀)。', '紀元前も同じ数え方で、「紀元前〇世紀」と答える。'], ex: { q: '1467年に始まった応仁の乱は、何世紀のできごとですか。', a: '15世紀', exp: '1467年の百の位までは14なので、1を足して15世紀です。15世紀は1401年から1500年までの100年間をさします。' } },
      { name: '「Ⅰ・Ⅱ・Ⅲ」の並べかえ', freq: 'とてもよく出る', when: '3つの文や資料を古い順に並べ、6通りの組み合わせから選ぶ問題は、この型です。', how: ['3つそれぞれの時代(できれば世紀)を書きこむ。', 'いちばん古いもの、いちばん新しいものを先に決める。', '時代が同じなら、原因→結果の順に並べる。'], ex: { q: 'Ⅰ 元寇 Ⅱ 応仁の乱 Ⅲ 承久の乱 を古い順に並べなさい。', a: 'Ⅲ→Ⅰ→Ⅱ', exp: '承久の乱は1221年(13世紀前半)、元寇は1274年・1281年(13世紀後半)、応仁の乱は1467年(15世紀)です。鎌倉の2つを先に、室町の応仁の乱を最後に置きます。' } },
      { name: '手がかりの語から時代を推理する', freq: 'よく出る', when: '史料や説明文の中に、時代を特定できる語(役職・税・身分など)がうめこまれていたら、この型です。', how: ['役職名(執権・管領・老中など)や税の名(租・調・庸、年貢、地租など)に印をつける。', 'その語が使われた時代を思い出す。', '複数の手がかりが同じ時代を指しているか確かめる。'], ex: { q: '「御家人が地頭として各地に置かれ、北条氏が執権として政治を動かした」という説明は、どの時代のものですか。', a: '鎌倉時代', exp: '「御家人」「地頭」「執権」「北条氏」はどれも鎌倉時代を示す手がかりです。室町時代なら「管領」「守護大名」、江戸時代なら「老中」「大名」が手がかりになります。' } },
      { name: '同じ世紀の日本と世界を結ぶ', freq: 'よく出る', when: '世界のできごとが示され「同じころの日本」を選ばせる問題は、この型です。', how: ['世界のできごとを西暦と世紀に直す。', '日本のできごとの選択肢も世紀に直す。', '同じ世紀のものを選び、近いものが2つあるときは年代まで比べる。'], ex: { q: 'コロンブスがアメリカ大陸近くの島に到達した(1492年)のと同じ世紀の日本のできごとはどれですか。ア 応仁の乱 イ 関ヶ原の戦い ウ 承久の乱', a: 'ア(応仁の乱)', exp: '1492年は15世紀です。応仁の乱は1467年で15世紀、関ヶ原の戦いは1600年で16世紀、承久の乱は1221年で13世紀です。' } }
    ],
    more: [
      { lv: 1, q: '794年は何世紀ですか。', a: '8世紀', exp: '百の位までの数は7なので、1を足して8世紀です。794年は平安京に都がうつされた年です。' },
      { lv: 1, q: '1185年は何世紀ですか。', a: '12世紀', exp: '百の位までの数11に1を足して12世紀です。1185年は壇ノ浦の戦いで平氏がほろんだ年です。' },
      { lv: 1, q: '鎌倉時代の次の時代は何ですか。', a: '室町時代(南北朝時代をふくむ)', exp: '鎌倉幕府がほろんだあと、建武の新政をはさんで室町時代になります。室町時代の初めは南北朝の対立が続きました。' },
      { lv: 1, q: '紀元前100年は何世紀ですか。', a: '紀元前1世紀', exp: '紀元前も、下2けたが00ならそのままの数で数えます。紀元前100年から紀元前1年までが紀元前1世紀です。' },
      { lv: 1, q: '江戸時代の前の時代は何ですか。', choices: ['室町時代', '安土桃山時代', '鎌倉時代', '明治時代'], a: 'B(安土桃山時代)', exp: '織田信長・豊臣秀吉が天下統一を進めた時代が安土桃山時代です。そのあと徳川家康が江戸幕府を開きました。' },
      { lv: 1, q: '都が京都の平安京に置かれ、貴族が政治を行った時代は何ですか。', a: '平安時代', exp: '794年に平安京に都がうつされてから、鎌倉幕府ができるまでの約400年を平安時代といいます。' },
      { lv: 1, q: '明治時代の次の時代は何ですか。', a: '大正時代', exp: '明治(1868〜1912年)→ 大正(1912〜1926年)→ 昭和(1926〜1989年)→ 平成 → 令和と続きます。' },
      { lv: 2, q: '1600年は何世紀ですか。', choices: ['15世紀', '16世紀', '17世紀', '18世紀'], a: 'B(16世紀)', exp: '下2けたが00のときは、百の位までの数がそのまま世紀になります。16世紀は1501〜1600年なので、1600年は16世紀の最後の年です。' },
      { lv: 2, q: '19世紀は、何年から何年までですか。', a: '1801年から1900年まで', exp: '1世紀が1〜100年なので、19世紀は1801〜1900年です。「1800年から」とまちがえやすいので注意しましょう。' },
      { lv: 2, q: '2001年は何世紀の最初の年ですか。', a: '21世紀', exp: '21世紀は2001年から2100年までです。2000年は20世紀の最後の年になります。' },
      { lv: 2, q: '「歌舞伎や浮世絵が町人に楽しまれ、寺子屋で読み書きを学ぶ子どもがふえた」のは、どの時代ですか。', a: '江戸時代', exp: '町人が文化のにない手になったことが江戸時代の大きな特色です。寺子屋は庶民の子どもの教育の場でした。' },
      { lv: 2, q: '「勘合を用いて明と貿易を行った」のは、どの時代ですか。', a: '室町時代', exp: '足利義満が始めた日明貿易(勘合貿易)です。倭寇と正式な貿易船を区別するために勘合が使われました。' },
      { lv: 2, q: '武士の政権のうち、京都に政治の中心を置いた幕府はどれですか。', choices: ['鎌倉幕府', '室町幕府', '江戸幕府', 'どれもちがう'], a: 'B(室町幕府)', exp: '鎌倉幕府は鎌倉、江戸幕府は江戸に置かれましたが、室町幕府は京都の室町に置かれました。名前の由来も京都の地名です。' },
      { lv: 2, q: '13世紀に起きた日本のできごとはどれですか。', choices: ['承久の乱', '応仁の乱', '大化の改新', '関ヶ原の戦い'], a: 'A(承久の乱)', exp: '承久の乱は1221年で13世紀です。応仁の乱は15世紀(1467年)、大化の改新は7世紀(645年)、関ヶ原の戦いは16世紀(1600年)です。' },
      { lv: 2, q: '11世紀の終わりに、位をゆずった天皇(上皇)が政治を行うしくみが始まりました。このしくみを何といいますか。', a: '院政', exp: '1086年に白河上皇が始めました。摂関政治のあとに来る政治のしくみで、天皇の父や祖父が実権をにぎりました。' },
      { lv: 3, q: '紀元前221年に秦の始皇帝が中国を統一しました。これは紀元前何世紀ですか。', a: '紀元前3世紀', exp: '紀元前も、百の位までの数(2)に1を足して数えます。紀元前300年〜紀元前201年が紀元前3世紀です。' },
      { lv: 3, q: 'フランス革命(1789年)と同じ世紀に起きた日本のできごとはどれですか。', choices: ['寛政の改革', '天保の改革', '大政奉還', '鎖国の完成'], a: 'A(寛政の改革)', exp: 'フランス革命は18世紀です。寛政の改革(1787年〜)は18世紀、天保の改革(1841年〜)と大政奉還(1867年)は19世紀、鎖国の完成(1641年)は17世紀です。' },
      { lv: 3, q: 'Ⅰ ペリーの来航 Ⅱ 異国船打払令 Ⅲ アヘン戦争の始まり を古い順に並べなさい。', a: 'Ⅱ→Ⅲ→Ⅰ', exp: '異国船打払令は1825年、アヘン戦争の始まりは1840年、ペリー来航は1853年です。アヘン戦争の結果を見て幕府が方針を変え、その後ペリーが来た、という流れで覚えましょう。' },
      { lv: 3, q: '「荘園の年貢を守護が半分取ることが認められ、守護が国を支配する大名へと成長した」という説明は、どの時代のことですか。', a: '室町時代', exp: '守護が年貢の半分を取ること(半済)が認められ、力をつけた守護は守護大名とよばれました。「守護大名」が室町時代を示す手がかりです。' },
      { lv: 3, q: '「平安時代」「鎌倉時代」「江戸時代」は、どれも何を基準に名前がつけられていますか。', a: '政治の中心地(都や幕府が置かれた場所)', exp: '平安京、鎌倉、江戸と、政治の中心が置かれた地名が時代名になっています。一方、明治・大正などは元号による時代区分です。' }
    ]
  });

  /* ===== 中学歴史:因果の鎖(総合) ===== */
  add('cx_jh3', {
    pat: [
      { name: '「原因 → できごと → 結果」の3段で書く', freq: 'とてもよく出る', when: '「〇〇が起こった理由と、その結果を説明しなさい」と、原因と結果の両方を問われたら、この型です。', how: ['できごとの前に何があったか(原因)を1つ決める。', 'できごとそのものを短く書く。', 'そのあと、だれの立場や何のしくみがどう変わったか(結果)を書く。', '「〜ため、〜した。その結果、〜になった」の形でつなぐ。'], ex: { q: '元寇と鎌倉幕府のほろびを、因果の鎖で説明しなさい。', a: '元寇は国を守る戦いで新しい領地が得られず、御家人は十分な恩賞をもらえなかった。そのため御家人の生活が苦しくなり、幕府への不満が高まって、幕府はおとろえていった。', exp: '「恩賞が不十分」→「御家人の不満」→「幕府のおとろえ」という3段の鎖が中心です。徳政令を出してもかえって混乱したことを加えると、さらによい答えになります。' } },
      { name: '「その結果どうなったか」を複数の方向に広げる', freq: 'よく出る', when: '1つのできごとの「影響」「結果」を2つ以上書かせる問題は、この型です。', how: ['政治・経済・人々のくらし・外交の4つの方向で考える。', 'それぞれの方向で、いちばん直接の変化を1つずつ書き出す。', '問題で求められている数だけ、方向のちがうものを選ぶ。'], ex: { q: '開国して貿易が始まった結果、国内で起きたことを2つ答えなさい。', a: '①生糸などが大量に輸出されて品不足となり、物価が上がった。②人々の生活が苦しくなり、幕府への不満や攘夷の動きが高まった。', exp: '経済(物価上昇)とくらし・政治(不満の高まり)の2つの方向に分けて書くと、同じことのくり返しにならずにすみます。金の流出を書いてもよいでしょう。' } },
      { name: '指定語句つきの記述', freq: 'とてもよく出る', when: '「次の語句を使って説明しなさい」と、2〜3語が指定されていたら、この型です。', how: ['指定語句どうしを原因・結果の順に並べる。', '並べた語句を「ため」「その結果」でつないで1〜2文にする。', '指定語句を全部使ったか、最後にチェックする。'], ex: { q: '「アヘン戦争」「異国船打払令」の語を使って、幕府の外国船への対応の変化を説明しなさい。', a: '幕府は異国船打払令で外国船を追い払っていたが、アヘン戦争で清がイギリスに敗れたことを知り、外国船に燃料や水をあたえて帰らせる方針に改めた。', exp: '「最初の方針 → きっかけ → 新しい方針」の順に並べると、指定語句が自然に入ります。語句を入れるだけでなく、変化の理由がわかるように書くことが大切です。' } },
      { name: '「外からの衝撃 → 国内の大改革」の型', freq: '難関校で出る', when: 'ちがう時代のできごとを比べ、「共通点」を問う問題は、この型です。', how: ['外国からの圧力や戦争の負け(衝撃)を見つける。', 'それに対して国内で何を急いで整えたか(改革)を見つける。', '「外国に負けない国をつくるため」という共通の目的でまとめる。'], ex: { q: '白村江の戦いの後と、ペリー来航の後に共通する、国内の動きは何ですか。', a: '外国の強さを知り、外国に対抗できる国をつくるため、政治のしくみを大きく改めようとする動きが起こった。', exp: '白村江の敗戦後は律令国家づくりが急がれ、ペリー来航後は幕府がたおれて明治の中央集権国家がつくられました。どちらも外の衝撃が改革を急がせた例です。' } }
    ],
    more: [
      { lv: 1, q: '元寇のあと生活に苦しむ御家人を救うため、1297年に鎌倉幕府が出した法令は何ですか。', a: '永仁の徳政令', exp: '御家人が手放した土地をただで取りもどせるようにしました。しかし、その後お金を貸す人がいなくなり、かえって御家人は困りました。' },
      { lv: 1, q: '開国後、日本からの輸出品で最も多かったものはどれですか。', choices: ['綿織物', '生糸', '鉄砲', '石炭'], a: 'B(生糸)', exp: '生糸は大量に輸出され、国内では品不足から値上がりしました。一方、安い綿織物が輸入され、国内の綿の生産は打撃を受けました。' },
      { lv: 1, q: '1860年の桜田門外の変で暗殺された大老はだれですか。', a: '井伊直弼', exp: '井伊直弼は朝廷の許可なしに日米修好通商条約を結び、反対する人々を安政の大獄で処罰しました。そのうらみから暗殺されました。' },
      { lv: 1, q: '1877年に、鹿児島の士族らが起こした最大の士族の反乱を何といいますか。', a: '西南戦争', exp: '西郷隆盛を中心に起こりましたが、徴兵令による政府軍に敗れました。これ以後、政府への批判は言論による自由民権運動が中心になります。' },
      { lv: 1, q: '応仁の乱の結果、幕府の力はどうなりましたか。', a: '幕府の力がおとろえ、各地で戦国大名が争う戦国時代になった。', exp: '京都は焼け野原になり、将軍の権威は弱まりました。実力で領地を広げる下剋上の風潮が広がりました。' },
      { lv: 1, q: '1937年の盧溝橋事件をきっかけに始まった戦争は何ですか。', a: '日中戦争', exp: '北京郊外の盧溝橋付近で日本軍と中国軍が衝突し、全面的な戦争に広がりました。長期化した戦争のなかで国家総動員法が定められました。' },
      { lv: 1, q: '1543年に種子島に伝わった鉄砲は、その後の戦い方をどう変えましたか。', a: '足軽の鉄砲隊が活躍するようになり、城も鉄砲に備えた石垣などをもつ形に変わった。', exp: '織田信長は長篠の戦い(1575年)で鉄砲を効果的に使い、武田氏の騎馬隊を破ったとされます。' },
      { lv: 2, q: '井伊直弼が安政の大獄を行ったのはなぜですか。', a: '朝廷の許可を得ずに日米修好通商条約を結んだことや、将軍のあとつぎの決め方を批判した大名・公家・武士たちをおさえこむため。', exp: '吉田松陰らが処刑されました。この強い弾圧が反発をまねき、桜田門外の変へとつながります。' },
      { lv: 2, q: '開国後、日本から大量の金が外国へ流れ出たのはなぜですか。', a: '金と銀の交換の比率が日本と外国でちがい、外国人が外国の銀を日本で金に替えて持ち出すと、もうかったから。', exp: '日本では外国より金が安く手に入ったため、金貨が大量に流出しました。幕府は小判の質を落として対応し、物価がさらに上がりました。' },
      { lv: 2, q: '1866年に、対立していた薩摩藩と長州藩の間を仲立ちし、薩長同盟を結ばせた土佐藩出身の人物はだれですか。', a: '坂本竜馬(坂本龍馬)', exp: '攘夷が難しいことを知った両藩が手を結び、幕府をたおす力の中心になりました。' },
      { lv: 2, q: '薩摩藩が生麦事件のあとの薩英戦争を経て、方針をどのように変えたか説明しなさい。', a: 'イギリスの軍事力の強さを知って攘夷が不可能だとさとり、イギリスに近づいて軍備の近代化を進め、倒幕へと向かった。', exp: '長州藩も下関で四か国の艦隊に砲台を占領され、攘夷をあきらめました。外国の力を知ったことが、両藩の方針転換のきっかけになりました。' },
      { lv: 2, q: '日露戦争での日本の勝利は、アジアの人々にどのような影響をあたえましたか。', a: 'アジアの国がヨーロッパの大国に勝ったことで、欧米の支配に苦しむアジアの人々の独立運動や民族運動を勇気づけた。', exp: '一方で日本自身は韓国への支配を強め、1910年に韓国を併合しました。プラスとマイナスの両面があることも押さえましょう。' },
      { lv: 2, q: '世界恐慌が日本にあたえた影響として正しいものはどれですか。', choices: ['好景気になり、米の値段が大きく上がった。', '昭和恐慌となり、生糸の輸出が減って農村が特に苦しんだ。', '関税自主権を回復した。', '普通選挙法が制定された。'], a: 'B(昭和恐慌となり、生糸の輸出が減って農村が特に苦しんだ。)', exp: 'アメリカへの生糸の輸出が大きく減り、繭の値段が下がって養蚕農家が苦しみました。不況の中で、政党への不信と軍部への期待が高まりました。' },
      { lv: 2, q: '豊臣秀吉の刀狩の結果、社会はどのように変わりましたか。', a: '農民が武器をもてなくなり、武士と農民の身分の区別がはっきりした(兵農分離)。', exp: '太閤検地で農民を土地にしばりつけ、刀狩で武器を取り上げたことで、武士と農民の区別が進みました。' },
      { lv: 2, q: '遣唐使が停止された結果、文化にどのような変化がありましたか。', a: 'それまでに学んだ唐の文化をもとに、日本の生活や感覚に合った国風文化が発達した。', exp: 'かな文字が使われるようになり、『源氏物語』や『枕草子』などの文学が生まれました。' },
      { lv: 3, q: '開国のあと、民衆の間で世直し一揆や打ちこわしがふえた理由を、因果の鎖で説明しなさい。', a: '貿易が始まって生糸などが大量に輸出されたため国内で品不足になり、さらに金の流出への対策で貨幣の質が落とされたことで物価が上がった。その結果、民衆の生活が苦しくなり、世の中を変えてほしいという不満が高まったから。', exp: '「貿易開始 → 品不足・貨幣の質の低下 → 物価上昇 → 生活の悪化 → 一揆・打ちこわし」の順で鎖をつなぎます。とちゅうの段を飛ばさないことが大切です。' },
      { lv: 3, q: '承久の乱の結果を、「朝廷」と「幕府の支配地域」の2つの方向から説明しなさい。', a: '朝廷:後鳥羽上皇が隠岐に流され、京都に六波羅探題が置かれて朝廷が監視されるようになった。幕府の支配地域:上皇方の土地に東国の御家人が地頭として置かれ、幕府の力が西国にまで広がった。', exp: '1つのできごとの結果を、ちがう方向に分けて書く練習です。乱の後に御成敗式目がつくられたこともつなげられます。' },
      { lv: 3, q: '地租改正のあと、税率が地価の3%から2.5%に引き下げられた理由を説明しなさい。', a: '地租改正で農民の負担が軽くならなかったため、各地で地租改正に反対する一揆が起こり、政府がこれをおさえる必要があったから。', exp: '1877年に2.5%に引き下げられました。同じ年に西南戦争が起きており、士族と農民の不満が結びつくことを政府はおそれました。' },
      { lv: 3, q: '江戸幕府がほろんだ原因を、国内と国外の2つの面から説明しなさい。', a: '国外:開国を求める欧米の圧力に対して幕府が十分に対応できず、朝廷の許可なしに条約を結んで権威を落とした。国内:貿易による物価上昇で人々の不満が高まり、薩摩・長州などの雄藩が倒幕に動いた。', exp: '1つの結果(幕府の滅亡)には、いくつもの原因があります。外からの圧力と内部の不満の両方を書くと説得力が高まります。' },
      { lv: 3, q: '1936年の二・二六事件のあと、日本の政治はどのように変わりましたか。', a: '事件はしずめられたが、その後、軍部が事件の再発をおそれる政府に強く影響をあたえるようになり、政治に対する軍部の発言力がいっそう強まった。', exp: '陸軍の青年将校らが大臣などを殺傷した事件です。五・一五事件(1932年)で政党内閣が終わり、二・二六事件でさらに軍部の力が強まった、と2段階で整理しましょう。' }
    ]
  });

  /* ===== 世界史の流れ ===== */
  add('c_h2', {
    pat: [
      { name: '「同じころ、別の地域では?」(時代の横並び)', freq: 'とてもよく出る', when: 'ある地域のできごとが示され「同じころの別の地域(日本・中国など)」を選ばせる問題は、この型です。', how: ['示されたできごとを世紀に直す。', '中国の王朝は「唐(7〜10世紀初め)→ 宋 → 元 → 明 → 清」の順と、日本の時代の対応で覚える。', '選択肢を世紀に直して、重なるものを選ぶ。'], ex: { q: '日本で奈良時代に平城京が栄えていたころ、中国を支配していた王朝はどれですか。ア 漢 イ 唐 ウ 宋 エ 明', a: 'イ(唐)', exp: '平城京は8世紀の都です。唐は7世紀初めから10世紀初めまで続き、日本は遣唐使を送って制度や文化を学びました。' } },
      { name: '宗教と開祖・聖典の組み合わせ', freq: 'よく出る', when: '仏教・キリスト教・イスラームの開祖や聖典、広まった地域を問われたら、この型です。', how: ['仏教=シャカ(インド)、経典。', 'キリスト教=イエス(パレスチナ)、聖書。', 'イスラーム=ムハンマド(アラビア半島)、コーラン(クルアーン)。', '起こった順(仏教 → キリスト教 → イスラーム)も確認する。'], ex: { q: '7世紀にアラビア半島でイスラームを開いた人物はだれですか。', a: 'ムハンマド', exp: 'ムハンマドは唯一の神アッラーへの信仰を説きました。聖典はコーラン(クルアーン)です。3つの宗教の中ではいちばん新しい宗教です。' } },
      { name: '市民革命の比較', freq: 'よく出る', when: '権利章典・独立宣言・人権宣言などの文書と、国の組み合わせを問われたら、この型です。', how: ['イギリス=名誉革命(1688年)→ 権利章典(1689年)。議会の力を確立。', 'アメリカ=独立宣言(1776年)。イギリスからの独立。', 'フランス=フランス革命(1789年)→ 人権宣言(1789年)。', '共通点は「国王の専制に反対し、人々の自由や権利を求めた」こと。'], ex: { q: '1789年に、人は生まれながらにして自由で平等な権利をもつと宣言した文書は何ですか。', a: '(フランスの)人権宣言', exp: 'フランス革命の中で国民議会が発表しました。アメリカ独立宣言(1776年)の影響を受けています。権利章典はイギリスの文書なので区別しましょう。' } },
      { name: '帝国主義とアジアの抵抗', freq: 'よく出る', when: '19世紀のイギリス・インド・清の関係や、反乱の名前を問われたら、この型です。', how: ['イギリスの綿製品の流入 → インドの手工業が打撃 → インド大反乱(1857年)→ イギリスが直接支配(インド帝国、1877年)。', '三角貿易 → アヘン戦争(1840〜42年)→ 南京条約で香港を割譲。', '「何が原因で反乱・戦争が起き、結果どう支配が強まったか」を鎖にする。'], ex: { q: 'インド大反乱のあと、イギリスはインドをどのように支配しましたか。', a: '東インド会社を解散し、イギリス政府がインドを直接支配するようになった(のちにインド帝国を成立させた)。', exp: '反乱をきっかけに、会社を通じた支配から国による直接の支配へ変わりました。1877年にはイギリスのヴィクトリア女王がインド皇帝を兼ねるインド帝国が成立しました。' } }
    ],
    more: [
      { lv: 1, q: '仏教を開いた人物はだれですか。', a: 'シャカ(ガウタマ・シッダールタ)', exp: 'シャカは紀元前5世紀ごろのインドで仏教を開き、さとりを開けば苦しみから救われると説きました。' },
      { lv: 1, q: 'キリスト教を開いた人物はだれですか。', a: 'イエス', exp: 'イエスはパレスチナで神の愛を説きました。教えは弟子たちによって広められ、のちにローマ帝国の国教になりました。' },
      { lv: 1, q: '1492年に、スペインの援助を受けて大西洋を横断し、西インド諸島に到達した人物はだれですか。', a: 'コロンブス', exp: 'コロンブスはインドをめざして西へ向かいました。これをきっかけに、ヨーロッパの国々がアメリカ大陸に進出していきます。' },
      { lv: 1, q: '1517年に、教会が免罪符(贖宥状)を売ることを批判して宗教改革を始めたドイツの人物はだれですか。', a: 'ルター', exp: 'ルターは信仰のよりどころは聖書だと説きました。彼の考えを支持する人々はプロテスタントとよばれました。' },
      { lv: 1, q: '18世紀後半に、世界で最初に産業革命が始まった国はどこですか。', choices: ['フランス', 'イギリス', 'ドイツ', 'アメリカ'], a: 'B(イギリス)', exp: 'イギリスでは綿織物の生産から機械化が進み、蒸気機関が動力として使われるようになりました。' },
      { lv: 1, q: 'フランス革命のあと、皇帝となってヨーロッパの多くを支配した人物はだれですか。', a: 'ナポレオン', exp: 'ナポレオンは1804年に皇帝となり、法の前の平等などを定めたナポレオン法典をつくりました。' },
      { lv: 1, q: '第一次世界大戦が始まったのは何年ですか。', a: '1914年', exp: 'サラエボ事件をきっかけに、1914年に始まりました。1918年に終わり、翌1919年にヴェルサイユ条約が結ばれました。' },
      { lv: 2, q: '14世紀ごろに、古代ギリシャ・ローマの文化を見直す動きであるルネサンスが始まった国はどこですか。', a: 'イタリア', exp: 'イタリアの都市は地中海の貿易で豊かで、古代ローマの遺跡も多くありました。レオナルド・ダ・ヴィンチやミケランジェロが活躍しました。' },
      { lv: 2, q: 'マゼランが率いた船隊が成しとげたことは何ですか。', a: '初めての世界一周', exp: 'マゼラン自身は途中のフィリピンで亡くなりましたが、残った船隊が世界一周に成功し、地球が丸いことが確かめられました。' },
      { lv: 2, q: 'アヘン戦争の講和条約である南京条約で、清がイギリスにゆずった土地はどこですか。', choices: ['台湾', '香港島', 'マカオ', '遼東半島'], a: 'B(香港島)', exp: '南京条約で清は香港島をイギリスにゆずり、上海など5港を開きました。香港は1997年に中国に返還されました。' },
      { lv: 2, q: '11世紀末から行われた十字軍の目的は何ですか。', a: 'キリスト教の聖地エルサレムを、イスラーム勢力から取りもどすこと。', exp: 'ローマ教皇のよびかけで始まりました。聖地の奪回は一時的にしか成功しませんでしたが、東西の交流がさかんになるきっかけになりました。' },
      { lv: 2, q: 'モンゴル帝国を建てた人物と、国号を元とした人物の組み合わせとして正しいものはどれですか。', choices: ['チンギス・ハン と フビライ・ハン', 'フビライ・ハン と チンギス・ハン', 'チンギス・ハン と マルコ・ポーロ', 'フビライ・ハン と ムハンマド'], a: 'A(チンギス・ハン と フビライ・ハン)', exp: 'チンギス・ハンが13世紀初めにモンゴル帝国を建て、孫のフビライ・ハンが国号を元とし、都を大都(今の北京)に置きました。' },
      { lv: 2, q: '4世紀末に東西に分裂した、地中海をとりまく大帝国は何ですか。', a: 'ローマ帝国', exp: 'ローマ帝国は東西に分かれ、西ローマ帝国は5世紀にほろびました。東ローマ帝国(ビザンツ帝国)は15世紀まで続きました。' },
      { lv: 2, q: '紀元前3世紀に中国を初めて統一した秦の始皇帝が行ったこととして正しいものはどれですか。', choices: ['万里の長城を修築し、文字やものさし・ますを統一した。', '律令を定め、遣唐使を受け入れた。', '科挙を始め、仏教を国教とした。', 'シルクロードを通ってローマに使いを送った。'], a: 'A(万里の長城を修築し、文字やものさし・ますを統一した。)', exp: '始皇帝は北方の遊牧民に備えて長城を修築し、度量衡(ものさし・ます・はかり)や文字・貨幣を統一しました。' },
      { lv: 2, q: '1945年に発足した国際連合の本部が置かれている都市はどこですか。', a: 'ニューヨーク', exp: '国際連合の本部はアメリカのニューヨークにあります。第一次世界大戦後の国際連盟の本部(スイスのジュネーブ)と区別しましょう。' },
      { lv: 3, q: '19世紀に、ヨーロッパの国々が世界の多くの地域を支配できたのはなぜですか。', a: '産業革命によって工業の生産力と軍事力が大きく高まり、原料の産地や製品を売る市場を求めて、アジアやアフリカに進出したから。', exp: '機械で大量につくった製品を売る先と、原料を手に入れる場所が必要になりました。蒸気船や鉄道、近代的な武器が進出を支えました。' },
      { lv: 3, q: 'フランス革命(1789年)が起こったころ、中国を支配していた王朝はどれですか。', choices: ['唐', '宋', '明', '清'], a: 'D(清)', exp: '清は17世紀から20世紀初め(1912年)まで中国を支配しました。18世紀は清の最盛期にあたります。日本では江戸時代です。' },
      { lv: 3, q: '15世紀末からヨーロッパの国々が新しい航路を開こうとした背景を説明しなさい。', a: 'アジアの香辛料などを、イスラーム商人などを通さずに直接手に入れたかったから。また、キリスト教を広めたいという目的もあった。', exp: '香辛料は肉の保存や味つけに使われ、高く売れました。羅針盤の改良や航海術の発達も、遠い海への航海を可能にしました。' },
      { lv: 3, q: 'アメリカ独立革命とフランス革命に共通する考え方を説明しなさい。', a: '人は生まれながらに自由で平等な権利をもち、政府は人々の権利を守るためにあるという考え方。', exp: 'ロックやルソーなどの啓蒙思想の影響を受けています。独立宣言と人権宣言は、その考え方を文章にしたものです。' },
      { lv: 3, q: 'モンゴル帝国について述べた文として正しいものはどれですか。', choices: ['モンゴル帝国の時代には、ユーラシアの東西を結ぶ交通路が整い、交流がさかんになった。', 'フビライ・ハンは、都をサマルカンドに置いた。', 'チンギス・ハンが、国号を元と定めた。', 'モンゴル帝国は日本を2度攻め、九州北部を長く支配した。'], a: 'A(モンゴル帝国の時代には、ユーラシアの東西を結ぶ交通路が整い、交流がさかんになった。)', exp: '駅伝制が整えられ、商人や旅行者が行き来しました。元の都は大都、国号を元としたのはフビライです。元寇で日本は九州北部を支配されていません。' }
    ]
  });

  /* ===== 世界史の因果 ===== */
  add('hx_whist', {
    pat: [
      { name: '「因果の向き」のすりかえを見ぬく正誤判定', freq: 'とてもよく出る', when: '選択肢が「〇〇の結果、△△が起こった」の形で、どれも聞いたことのある語でできているときは、この型を疑います。', how: ['「結果」と書かれた側のできごとが、本当に後に起きたかを年代で確かめる。', '原因と結果が逆になっていないか(△△の結果〇〇、が正しくないか)を考える。', '年代がわからなくても、「なぜそうなるのか」を説明できるかで判定する。'], ex: { q: '正誤を判定しなさい。「ドイツの賠償金の支払い停止によって、世界恐慌が始まった。」', a: '誤り', exp: '世界恐慌は1929年のニューヨーク株式市場の株価暴落から始まりました。恐慌によってドイツの経済が悪化し、賠償金の支払いが困難になったので、原因と結果の向きが逆です。' } },
      { name: '「主語」のすりかえを見ぬく', freq: 'とてもよく出る', when: '正しいできごとの説明なのに、国名・人物名だけが入れかわっていそうな選択肢は、この型です。', how: ['できごとの中身だけを読み、だれがしたことかを自分で思い出す。', '選択肢の主語と照らし合わせる。', '似た立場の国(イギリスとフランス、清と明など)の入れかえに特に注意する。'], ex: { q: '正誤を判定しなさい。「アヘン戦争の結果、清はフランスに香港島を割譲した。」', a: '誤り', exp: '南京条約(1842年)で香港島をゆずった相手はイギリスです。内容は正しく見えても、主語や相手の国がすりかえられていないかを確かめます。' } },
      { name: '世界をめぐる銀の流れ', freq: '難関大で出る', when: '16〜17世紀のアメリカ大陸の銀・日本の銀・中国の税制が一緒に出てきたら、この型です。', how: ['スペインがアメリカ大陸(ポトシ銀山など)で銀を大量に得た。', 'その銀がヨーロッパへ、さらにアジア(マニラ経由など)へ流れた。日本銀も中国へ流れこんだ。', '銀が大量に入った明では、税を銀で納める一条鞭法が広まった。'], ex: { q: '明で一条鞭法が広まった背景を説明しなさい。', a: '日本やアメリカ大陸の銀が貿易を通じて大量に中国に流れこみ、銀が広く使われるようになったから。', exp: '一条鞭法は、さまざまな税や労役を銀にまとめて納めさせる制度です。銀が手に入りやすくなったことが前提でした。ヨーロッパでは銀の流入で物価が上がる価格革命が起こりました。' } },
      { name: '戦後処理が次の戦争の原因になる', freq: 'よく出る', when: '第一次世界大戦後の条約と、第二次世界大戦の原因を結びつける論述は、この型です。', how: ['ヴェルサイユ条約でドイツに課された内容(巨額の賠償金・領土の削減・軍備制限)を書く。', 'ドイツ国民の不満と経済の混乱を書く。', '世界恐慌でさらに苦しくなり、ナチ党が支持を集めた流れにつなぐ。'], ex: { q: 'ヴェルサイユ条約がナチ党の台頭につながった理由を説明しなさい。', a: 'ドイツは巨額の賠償金や領土の削減などを課され、国民は強い不満をもった。そこへ世界恐慌で失業者があふれ、条約の破棄をとなえるナチ党が支持を集めたから。', exp: '「条約への不満」と「恐慌による生活苦」の2つが重なったことがポイントです。どちらか一方だけでは説明が不十分になります。' } },
      { name: '革命のドミノ(大西洋をこえる連鎖)', freq: 'よく出る', when: 'アメリカ独立・フランス革命・ラテンアメリカの独立の関係を問われたら、この型です。', how: ['アメリカ独立戦争にフランスが参戦し、フランスの財政が悪化した。', '財政難を解決するため三部会が開かれ、フランス革命が始まった(1789年)。', 'フランス革命の理念やナポレオンのスペイン侵攻が、ハイチやラテンアメリカの独立につながった。'], ex: { q: 'アメリカ独立戦争が、フランス革命の原因の1つになったのはなぜですか。', a: 'フランスがアメリカを支援して参戦したため財政がさらに苦しくなり、その解決のために開かれた三部会から革命が始まったから。', exp: '独立宣言の考え方(自由・平等)がフランスに伝わったことも原因の1つです。お金(財政)と考え方(理念)の2つの面から説明するとよいでしょう。' } }
    ],
    more: [
      { lv: 1, q: '1095年にクレルモン宗教会議で十字軍をよびかけたローマ教皇はだれですか。', a: 'ウルバヌス2世', exp: 'ビザンツ皇帝からの救援の要請を受けて、聖地エルサレムの奪回をよびかけました。第1回十字軍はエルサレムを占領しました。' },
      { lv: 1, q: '1498年に、アフリカ南端の喜望峰を回ってインドのカリカットに到達したポルトガルの人物はだれですか。', a: 'ヴァスコ・ダ・ガマ', exp: 'これによってヨーロッパからインドへの海の道が開かれ、ポルトガルはアジアの香辛料貿易に乗り出しました。' },
      { lv: 1, q: '1919年に結ばれた、第一次世界大戦の連合国とドイツとの講和条約は何ですか。', a: 'ヴェルサイユ条約', exp: 'ドイツはすべての植民地を失い、巨額の賠償金を課され、軍備も制限されました。' },
      { lv: 1, q: '世界恐慌は、何年にどこの株価暴落から始まりましたか。', a: '1929年、ニューヨーク(ウォール街)の株式市場', exp: 'アメリカの株価暴落が、銀行の倒産や貿易の縮小を通じて世界中に広がりました。' },
      { lv: 1, q: '世界恐慌に対してニューディール政策を行ったアメリカ大統領はだれですか。', a: 'フランクリン・ローズヴェルト', exp: '公共事業をおこして失業者を雇い、農業や工業の生産を調整し、労働者の権利を保護しました。' },
      { lv: 1, q: '18世紀後半に蒸気機関を改良し、産業革命を進めたイギリスの人物はだれですか。', choices: ['ワット', 'スティーヴンソン', 'エジソン', 'ニュートン'], a: 'A(ワット)', exp: 'ワットの改良した蒸気機関は、工場の機械を動かす動力として使われました。スティーヴンソンは蒸気機関車を実用化した人物です。' },
      { lv: 1, q: '1776年のアメリカ独立宣言を中心となって起草した人物はだれですか。', a: 'ジェファソン', exp: 'ジェファソンはのちに第3代大統領になりました。独立宣言にはロックの思想の影響が見られます。' },
      { lv: 2, q: '十字軍が失敗に終わった結果、ヨーロッパでどのような変化が起こりましたか。2つ答えなさい。', a: '①ローマ教皇の権威がおとろえ、国王の力が強まった。②遠征で交通が発達し、イタリアの都市を中心に東方との貿易がさかんになった。', exp: '遠征に参加した諸侯や騎士の中には没落する者もいて、国王が力をのばしました。イスラーム世界の学問や文化が伝わったことも大きな変化です。' },
      { lv: 2, q: '16世紀のヨーロッパで、アメリカ大陸から大量の銀が流れこんだ結果、物価が大きく上がった現象を何といいますか。', a: '価格革命', exp: '銀の量がふえて銀の価値が下がり、物価が上がりました。決まった額の地代で暮らす領主には打撃となりました。' },
      { lv: 2, q: 'フランス革命が始まる直前、国王ルイ16世が三部会を開いたのはなぜですか。', a: '戦争などで国の財政が苦しくなり、それまで税を免除されていた特権身分にも課税しようとしたから。', exp: '三部会では身分ごとの議決方法をめぐって対立が起こり、第三身分の代表が国民議会をつくりました。これが革命の始まりです。' },
      { lv: 2, q: '1804年に独立し、黒人を中心とする初めての共和国となったカリブ海の国はどこですか。', a: 'ハイチ', exp: 'フランスの植民地で、奴隷とされた黒人の反乱から独立を達成しました。フランス革命の理念が大西洋をこえて広がった例です。' },
      { lv: 2, q: 'イギリスの産業革命は、インドの産業にどのような影響をあたえましたか。', a: 'イギリスの機械でつくられた安い綿製品がインドに大量に流れこみ、インドの手織りの綿布産業が打撃を受けた。', exp: 'インドはもともと綿布の輸出国でしたが、19世紀には綿花をイギリスに輸出し、綿製品を輸入する立場に変わりました。' },
      { lv: 2, q: '19世紀にイギリス・インド・清の間で行われた三角貿易で、インドから清に運ばれたものはどれですか。', choices: ['茶', '綿織物', 'アヘン', '銀'], a: 'C(アヘン)', exp: 'イギリスは綿織物をインドへ、インドのアヘンを清へ、清の茶をイギリスへ運びました。アヘンの代金として清から銀が流れ出し、アヘン戦争の原因となりました。' },
      { lv: 2, q: '世界恐慌のあと、イギリスやフランスがブロック経済を行ったことは、日本・ドイツ・イタリアにどのような影響をあたえましたか。', a: '植民地が少なく、製品を売る市場をしめ出されたため、軍事力で新しい領土や勢力圏を広げようとする動きを強めた。', exp: '「持てる国」と「持たざる国」の対立が深まりました。日本は満州事変、イタリアはエチオピア侵攻へと進みました。' },
      { lv: 2, q: '1930年代のドイツで、ナチ党が支持を広げた背景として誤っているものはどれですか。', choices: ['世界恐慌で失業者がふえた。', 'ヴェルサイユ条約への不満があった。', 'ドイツが植民地を多くもち、経済が安定していた。', '共産党への不安が広がっていた。'], a: 'C(ドイツが植民地を多くもち、経済が安定していた。)', exp: 'ドイツはヴェルサイユ条約ですべての植民地を失っており、恐慌で経済も混乱していました。不安と不満の中で、強い指導者を求める声が高まりました。' },
      { lv: 3, q: 'ヴェルサイユ体制が、のちの第二次世界大戦の原因の1つとなったといわれる理由を、ドイツの立場から論述しなさい。', a: 'ドイツは戦争の責任を負わされ、植民地をすべて失い、巨額の賠償金と軍備の制限を課された。国民の不満は強く、世界恐慌で生活がさらに苦しくなると、ヴェルサイユ体制の打破をとなえるナチ党が政権をにぎり、再軍備や領土の拡大を進めたから。', exp: '「厳しい戦後処理 → 国民の不満 → 恐慌 → ナチ党の台頭 → 体制の破壊」という鎖でまとめます。敗戦国を追いつめすぎた反省は、第二次世界大戦後の戦後処理にも生かされました。' },
      { lv: 3, q: '次の文のうち、主語や相手がすりかえられていない、正しい文はどれですか。', choices: ['南京条約で、清はイギリスに香港島をゆずった。', 'アメリカ独立戦争で、イギリスはアメリカを支援して参戦した。', 'ニューディール政策は、イギリスの首相が行った。', 'インド大反乱のあと、フランスがインドを直接支配した。'], a: 'A(南京条約で、清はイギリスに香港島をゆずった。)', exp: 'アメリカを支援して参戦したのはフランス、ニューディールはアメリカのフランクリン・ローズヴェルト大統領、インドを直接支配したのはイギリスです。' },
      { lv: 3, q: '価格革命によって、ヨーロッパの領主の立場はどのように変わりましたか。理由もあわせて説明しなさい。', a: '物価が上がる一方で、領主が農民から受けとる地代は決まった額のままだったため、実質的な収入がへり、多くの領主の立場が弱まった。', exp: '物価が上がると、同じ額のお金で買える物が少なくなります。名目の収入が変わらなければ、実質の収入は下がるという考え方です。' },
      { lv: 3, q: 'クリミア戦争での敗北が、ロシアの国内改革につながった理由を説明しなさい。', a: '南下をめざしたロシアは、イギリス・フランスなどに敗れ、工業や軍事の近代化の遅れを思い知らされた。そこで皇帝アレクサンドル2世は、1861年に農奴解放令を出して近代化を進めようとしたから。', exp: '外からの衝撃(敗戦)が国内の大改革を生む型です。南下に失敗したロシアは、のちに東アジアへ目を向け、日本との対立にもつながっていきます。' },
      { lv: 3, q: '大航海時代のあと、ヨーロッパの商業の中心はどのように移りましたか。理由もあわせて説明しなさい。', a: '地中海沿岸のイタリアの都市から、大西洋に面したスペイン・ポルトガルやオランダ・イギリスなどへ移った。アジアやアメリカ大陸との貿易が大西洋を通る航路で行われるようになったから。', exp: 'この変化を商業革命といいます。とくにアントウェルペン(アントワープ)やアムステルダムなどが栄えました。交通路の変化が、都市の盛衰を決めた例です。' }
    ]
  });

  /* ===== 世界史の並べかえ(近現代) ===== */
  add('hd_wsoc', {
    pat: [
      { name: '1つの国の流れを鎖にする(フランス革命〜ウィーン体制)', freq: 'とてもよく出る', when: 'フランス革命・ナポレオン・ウィーン会議に関するできごとが並んだら、この型です。', how: ['バスティーユ牢獄の襲撃・人権宣言(1789年)→ 王政廃止・第一共和政(1792年)。', 'ルイ16世の処刑(1793年)→ ナポレオンが皇帝に(1804年)。', 'ナポレオンの没落 → ウィーン会議(1814〜15年)で革命前の秩序にもどそうとした。', '「王がいる → 王がいない → 皇帝 → 王政の復活」という政治体制の変化で並べる。'], ex: { q: '次を古い順に並べなさい。ア ナポレオンが皇帝になる イ 人権宣言 ウ ウィーン会議', a: 'イ→ア→ウ', exp: '人権宣言は1789年、ナポレオンの皇帝即位は1804年、ウィーン会議は1814〜15年です。革命 → 皇帝 → 革命前の秩序への復帰、という流れで並べます。' } },
      { name: '「同じ時期のかたまり」で並べる(1848年と1860年代)', freq: 'よく出る', when: 'ヨーロッパ・アメリカ・日本のできごとが入りまじった並べかえは、この型です。', how: ['1848年=フランス二月革命、ドイツ・オーストリアの三月革命 → ウィーン体制の崩壊。', '1860年代=イタリア王国の成立(1861年)、アメリカ南北戦争(1861〜65年)、明治維新(1868年)。', '1871年=ドイツ帝国の成立。', 'まずかたまりに分け、かたまりの中で年を比べる。'], ex: { q: '次を古い順に並べなさい。ア ドイツ帝国の成立 イ イタリア王国の成立 ウ フランス二月革命', a: 'ウ→イ→ア', exp: '二月革命は1848年、イタリア王国の成立は1861年、ドイツ帝国の成立は1871年です。「1848年のかたまり」と「1860〜70年代のかたまり」に分けると速く解けます。' } },
      { name: '19世紀の中国の並べかえ', freq: 'とてもよく出る', when: 'アヘン戦争・太平天国・アロー戦争・義和団などが並んだら、この型です。', how: ['外からの圧力:アヘン戦争(1840〜42年)→ アロー戦争(1856〜60年)→ 日清戦争(1894〜95年)。', '内の動揺:太平天国(1851〜64年)→ 義和団事件(1900年)→ 辛亥革命(1911年)。', '外と内を交互に入れながら一本の年表にする。'], ex: { q: '次を古い順に並べなさい。ア 義和団事件 イ 太平天国の乱 ウ アヘン戦争', a: 'ウ→イ→ア', exp: 'アヘン戦争は1840年、太平天国の乱は1851年、義和団事件は1900年です。外の戦争に負けて重税や混乱が広がり、内の反乱が起こったという因果でもつながります。' } },
      { name: '冷戦の始まりから終わりまでの並べかえ', freq: 'とてもよく出る', when: 'トルーマン・ドクトリン・NATO・キューバ危機・マルタ会談などが並んだら、この型です。', how: ['始まり=トルーマン・ドクトリン(1947年)→ ベルリン封鎖(1948〜49年)→ NATO結成(1949年)。', '熱い戦争と危機=朝鮮戦争(1950年)→ キューバ危機(1962年)→ ベトナム戦争の激化。', '緊張緩和と終結=ニクソン訪中(1972年)→ ベルリンの壁崩壊・マルタ会談(1989年)→ ソ連解体(1991年)。'], ex: { q: '次を古い順に並べなさい。ア キューバ危機 イ NATOの結成 ウ マルタ会談', a: 'イ→ア→ウ', exp: 'NATOの結成は1949年、キューバ危機は1962年、マルタ会談は1989年です。「始まり → 危機 → 終わり」の3段階に分けて考えます。' } }
    ],
    more: [
      { lv: 1, q: 'フランス革命の始まりとされる、パリの民衆によるバスティーユ牢獄の襲撃は何年ですか。', a: '1789年', exp: '同じ1789年に人権宣言も出されました。フランス革命は「1789年」が基準の年です。' },
      { lv: 1, q: 'ナポレオンが皇帝の位についたのは何年ですか。', a: '1804年', exp: 'ナポレオンは1804年に国民投票を経て皇帝になりました。同じ年にナポレオン法典も公布されています。' },
      { lv: 1, q: 'ウィーン会議を主導したオーストリアの政治家はだれですか。', a: 'メッテルニヒ', exp: 'メッテルニヒは革命前の王政と秩序の回復をめざしました。こうしてできた体制をウィーン体制といいます。' },
      { lv: 1, q: '1851年に清で起こった太平天国の乱の指導者はだれですか。', a: '洪秀全', exp: '洪秀全はキリスト教の影響を受けた宗教結社を率い、清をたおして平等な社会をつくることをかかげました。' },
      { lv: 1, q: '1911年の辛亥革命のあと、中華民国の臨時大総統となった人物はだれですか。', a: '孫文', exp: '孫文は三民主義(民族・民権・民生)をとなえました。1912年に中華民国が成立し、清はほろびました。' },
      { lv: 1, q: '1949年に、アメリカと西ヨーロッパの国々が結成した軍事同盟を何といいますか。', a: 'NATO(北大西洋条約機構)', exp: 'これに対抗して、ソ連と東ヨーロッパの国々は1955年にワルシャワ条約機構をつくりました。' },
      { lv: 1, q: '1962年、ソ連がキューバにミサイル基地を建設しようとしたことから起こった米ソの危機を何といいますか。', choices: ['ベルリン封鎖', 'キューバ危機', 'スエズ危機', '朝鮮戦争'], a: 'B(キューバ危機)', exp: 'アメリカのケネディ大統領とソ連のフルシチョフ首相の間で、核戦争の寸前までいきました。ソ連が基地を撤去して危機は回避されました。' },
      { lv: 2, q: '次を古い順に並べなさい。ア イタリア王国の成立 イ ウィーン会議 ウ ドイツ帝国の成立', a: 'イ→ア→ウ', exp: 'ウィーン会議は1814〜15年、イタリア王国の成立は1861年、ドイツ帝国の成立は1871年です。ウィーン体制がくずれたあと、国民国家の統一が進みました。' },
      { lv: 2, q: 'アメリカ南北戦争のときの大統領で、奴隷解放宣言を出した人物はだれですか。', a: 'リンカン(リンカーン)', exp: '南北戦争は1861〜65年です。リンカンは1863年に奴隷解放宣言を出し、ゲティスバーグで「人民の、人民による、人民のための政治」の演説を行いました。' },
      { lv: 2, q: '「鉄血政策」をかかげ、ドイツの統一を進めたプロイセンの首相はだれですか。', a: 'ビスマルク', exp: 'ビスマルクはオーストリアやフランスとの戦争に勝ち、1871年にドイツ帝国を成立させました。' },
      { lv: 2, q: 'アロー戦争の結果、1860年に清とイギリス・フランスなどの間で結ばれた条約を何といいますか。', a: '北京条約', exp: '北京条約で天津などが開港され、イギリスは九竜半島の南部を得ました。ロシアも仲介の見返りに沿海州を得ています。' },
      { lv: 2, q: '1900年に、「扶清滅洋(清を助けて外国をほろぼす)」をかかげて外国勢力を攻撃した中国の運動を何といいますか。', a: '義和団事件', exp: '日本やロシアなど8か国の連合軍が出兵してしずめました。この後もロシアは満州に軍隊を残し、日露戦争の原因の1つになりました。' },
      { lv: 2, q: '1947年にアメリカ大統領が発表したトルーマン・ドクトリンの目的は何ですか。', a: '共産主義の勢力の拡大を食い止める(封じこめる)こと。', exp: 'ギリシャやトルコへの援助を表明しました。同じ年に、ヨーロッパの経済復興を助けるマーシャル・プランも発表されました。' },
      { lv: 2, q: '1948年に、ソ連が西ベルリンへの陸上の交通路をふさいだできごとを何といいますか。', a: 'ベルリン封鎖', exp: 'アメリカなどは飛行機で物資を運んで対抗しました。翌1949年にドイツは東西に分かれて2つの国家が成立しました。' },
      { lv: 2, q: '1950年代の後半から、社会主義の国どうしであるソ連と中国の関係が悪化したことを何といいますか。', a: '中ソ対立', exp: '社会主義の進め方や、アメリカとの向き合い方をめぐって対立しました。この対立が、のちのアメリカと中国の接近につながります。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 明治維新 イ ドイツ帝国の成立 ウ アメリカ南北戦争の終結 エ イタリア王国の成立', a: 'エ→ウ→ア→イ', exp: 'イタリア王国の成立は1861年、南北戦争の終結は1865年、明治維新は1868年、ドイツ帝国の成立は1871年です。4つとも1860〜70年代の「国づくりのかたまり」です。' },
      { lv: 3, q: '次を古い順に並べなさい。ア アロー戦争の開始 イ 太平天国の乱の開始 ウ アヘン戦争の開始', a: 'ウ→イ→ア', exp: 'アヘン戦争は1840年、太平天国の乱は1851年、アロー戦争は1856年に始まりました。太平天国の乱の最中にアロー戦争が起こったことに注意しましょう。' },
      { lv: 3, q: '1972年にアメリカのニクソン大統領が中国を訪問した背景を、2つ説明しなさい。', a: '①ベトナム戦争が行きづまり、戦争を終わらせる道を探していた。②中国はソ連と対立していたので、アメリカと中国はソ連に対抗するという点で利害が一致した。', exp: '冷戦は「米ソの二極」だけでなく、中ソ対立によって三角形の関係になっていました。同じ年に日本も日中共同声明で中国と国交を正常化しました。' },
      { lv: 3, q: '1848年にヨーロッパ各地で起こった革命に共通する目的と、それがウィーン体制にあたえた影響を説明しなさい。', a: '自由主義(憲法や議会、選挙権の拡大を求める)やナショナリズム(民族の独立や統一を求める)を目的とした。その結果、メッテルニヒが失脚し、ウィーン体制は崩壊した。', exp: 'フランス二月革命の影響がドイツ・オーストリアの三月革命に広がり、「諸国民の春」とよばれました。同じ1848年にマルクスとエンゲルスが『共産党宣言』を発表しています。' },
      { lv: 3, q: '次を古い順に並べなさい。ア ニクソン大統領の中国訪問 イ 朝鮮戦争の休戦 ウ アメリカによる北ベトナムへの爆撃(北爆)の開始 エ サイゴンの陥落(ベトナム戦争の終結)', a: 'イ→ウ→ア→エ', exp: '朝鮮戦争の休戦は1953年、北爆の開始は1965年、ニクソン訪中は1972年、サイゴン陥落は1975年です。アジアの冷戦を「朝鮮 → ベトナム → 米中接近 → ベトナム統一」の順でとらえましょう。' }
    ]
  });

  /* ===== 日本史テーマ史 ===== */
  add('c_h1', {
    pat: [
      { name: 'テーマ史「土地と税」の並べかえ', freq: 'とてもよく出る', when: '土地制度や税制度に関する説明文が並び、時代順を問われたら、この型です。', how: ['古代=班田収授法(口分田)→ 墾田永年私財法(743年)→ 荘園の広がり。', '近世=太閤検地(石高で年貢)。', '近代=地租改正(1873年、地価の3%を現金で)。', '現代=農地改革(戦後、自作農の創出)。「だれが土地をもち、税をどう納めたか」の変化で並べる。'], ex: { q: '次を古い順に並べなさい。ア 地租改正 イ 太閤検地 ウ 墾田永年私財法', a: 'ウ→イ→ア', exp: '墾田永年私財法は奈良時代(743年)、太閤検地は安土桃山時代、地租改正は明治時代(1873年)です。税を「稲・特産物 → 米(石高)→ 現金」と納め方の変化でも確かめられます。' } },
      { name: 'テーマ史「中国とのつきあい方」', freq: 'よく出る', when: '金印・卑弥呼・遣隋使・日明貿易など、中国との外交の文が並んだら、この型です。', how: ['冊封=中国の皇帝から王の位を認めてもらう関係。奴国王・卑弥呼・倭の五王・足利義満など。', '遣隋使(607年の国書)は対等な立場を示そうとした。', '日明貿易は朝貢の形で行われた。', '「中国の皇帝の下に入るか、対等をめざすか」で整理する。'], ex: { q: '遣隋使が持参した国書で、倭の王が示そうとした中国との関係はどのようなものですか。', a: '中国の皇帝に従うのではなく、対等な立場の関係。', exp: '「日出づる処の天子、書を日没する処の天子に致す」という国書は、隋の皇帝を怒らせたと伝えられます。それまでの冊封を受ける関係とはちがう姿勢です。' } },
      { name: 'テーマ史「お金(貨幣)の歴史」', freq: '難関大で出る', when: '和同開珎・宋銭・寛永通宝・円・金解禁など、貨幣に関する文が並んだら、この型です。', how: ['古代=富本銭・和同開珎(708年)を朝廷が発行。', '中世=宋銭・明銭など中国の銭を輸入して使った。', '近世=江戸幕府が金・銀・銭(寛永通宝)を発行。元禄の改鋳など質の変更。', '近代=新貨条例(1871年)で円・銭・厘、金本位制(1897年)、金解禁(1930年)。'], ex: { q: '鎌倉・室町時代に、日本で広く使われていた銭は、どこでつくられたものが中心でしたか。', a: '中国(宋銭・明銭)', exp: 'この時代の日本は銭を自分でほとんどつくらず、日宋貿易や日明貿易で輸入した中国の銭を使いました。商業がさかんになると、定期市などで銭の使用が広がりました。' } },
      { name: 'テーマ史「文化の担い手」', freq: 'よく出る', when: '文化の説明文が並び「担い手がだれか」や時代順を問われたら、この型です。', how: ['飛鳥・天平・国風=皇族・貴族・僧が中心。', '鎌倉・室町=武士と民衆にも広がる(わかりやすい仏教、能・狂言)。', '江戸=町人(元禄は上方、化政は江戸)。', '大正・昭和=大衆(新聞・雑誌・ラジオ)。'], ex: { q: '大正時代に文化の担い手が「大衆」へと広がった理由を1つ答えなさい。', a: '新聞や雑誌が多く発行され、1925年にラジオ放送が始まるなど、多くの人が情報や娯楽にふれられるようになったから。', exp: '義務教育の普及で文字を読める人がふえたことも背景です。だれが文化を楽しみ、つくったのかという視点で時代を区別します。' } }
    ],
    more: [
      { lv: 1, q: '708年に発行された、日本で広く流通させようとした最初の銭とされるものは何ですか。', a: '和同開珎', exp: '和同開珎は平城京の建設の費用などに使われました。それより前の富本銭も見つかっていますが、広く流通させようとしたのは和同開珎です。' },
      { lv: 1, q: '豊臣秀吉が全国の田畑の面積や収穫量を調べ、石高で表したことを何といいますか。', a: '太閤検地', exp: '田畑ごとに耕す農民を決めて検地帳に記し、年貢を納める責任を負わせました。これで荘園のしくみは完全になくなりました。' },
      { lv: 1, q: '1873年の地租改正で、税はどのような方法で納めることになりましたか。', a: '地価の3%を現金で納める。', exp: '米で納めていた年貢を現金に変えたことで、政府の収入が安定しました。納めるのは土地の所有者です。' },
      { lv: 1, q: '戦後の農地改革によって大はばにふえたのは、どのような農家ですか。', choices: ['小作農', '自作農', '地主', '荘園領主'], a: 'B(自作農)', exp: '政府が地主の農地を買い上げて小作人に安く売ったので、自分の土地を耕す自作農がふえました。' },
      { lv: 1, q: '「漢委奴国王」と刻まれた金印が発見された場所はどこですか。', a: '志賀島(福岡県)', exp: '57年に奴国の王が後漢の皇帝から金印を授かったと中国の歴史書にあり、江戸時代に志賀島で見つかりました。' },
      { lv: 1, q: '江戸幕府が発行し、全国に流通した銅銭は何ですか。', a: '寛永通宝', exp: '寛永通宝によって、それまで使われていた中国の銭にかわって、国内でつくった銭が広く使われるようになりました。' },
      { lv: 1, q: '607年に遣隋使として隋に送られた人物はだれですか。', a: '小野妹子', exp: '聖徳太子(厩戸皇子)の時代に派遣されました。隋の進んだ制度や文化を学ぶことが目的でした。' },
      { lv: 2, q: '平安時代に、地方の豪族などが自分の開いた土地を有力な貴族や寺社に寄進したのはなぜですか。', a: '有力な貴族や寺社の荘園にすることで、税を免除されたり(不輸)、国司の立ち入りを拒んだり(不入)できたから。', exp: '寄進した者は現地の管理者として、実際の支配を続けました。こうして荘園がふえ、国の税収はへっていきました。' },
      { lv: 2, q: '足利義満が始めた日明貿易は、どのような形式で行われましたか。', a: '日本の王が明の皇帝にみつぎ物をおくり、そのお返しを受けとる朝貢の形式。', exp: '義満は明から「日本国王」として認められました。対等な関係をめざした遣隋使とはちがう姿勢です。' },
      { lv: 2, q: '1871年の新貨条例で定められた、お金の単位をすべて答えなさい。', a: '円・銭・厘', exp: '1円=100銭、1銭=10厘と、10進法で単位が整理されました。江戸時代の両・分・朱などの複雑な単位にかわりました。' },
      { lv: 2, q: '元禄時代に、幕府が小判にふくまれる金の量を減らして発行したことは、どのような結果をもたらしましたか。', a: '幕府は差額で一時的に収入を得たが、貨幣の価値が下がって物価が上がった。', exp: '金の量を減らせば、同じ量の金からたくさんの小判がつくれます。しかし出回るお金がふえ、1枚の価値は下がるので、物の値段が上がりました。' },
      { lv: 2, q: '元禄文化のおもな担い手はだれですか。', choices: ['貴族', '武士', '上方の町人', '江戸の町人'], a: 'C(上方の町人)', exp: '元禄文化は京都・大阪の町人が中心で、井原西鶴の浮世草子や近松門左衛門の人形浄瑠璃が人気を集めました。化政文化は江戸の町人です。' },
      { lv: 2, q: '11世紀の終わりから、位をゆずった上皇が中心となって行った政治を何といいますか。', a: '院政', exp: '白河上皇が始めました。摂関家の力をおさえ、上皇が天皇の父・祖父として政治を動かしました。' },
      { lv: 2, q: '5世紀に、中国の南朝に使いを送り、朝鮮半島南部での軍事的な地位を認めてもらおうとした倭の王たちを何とよびますか。', a: '倭の五王', exp: '讃・珍・済・興・武の5人で、武は雄略天皇にあたると考えられています。中国の皇帝の権威を借りて地位を高めようとしました。' },
      { lv: 2, q: '1897年に日本が採用した、金を基準にして貨幣の価値を決める制度を何といいますか。', a: '金本位制', exp: '日清戦争の賠償金をもとに採用しました。欧米の多くの国と同じ制度になり、貿易がしやすくなりました。' },
      { lv: 3, q: '太閤検地と地租改正を比べて、共通点とちがいを1つずつ説明しなさい。', a: '共通点:全国の土地を調べ、税を納める者を確定した点。ちがい:太閤検地は耕す農民に米で年貢を納めさせたが、地租改正は土地の所有者に地価をもとに現金で納めさせた。', exp: 'どちらも全国規模の土地調査で、国の財政の土台をつくりました。「だれが」「何で」納めるかが変わった点が、テーマ史でよく問われます。' },
      { lv: 3, q: '1930年の金解禁が、昭和恐慌を深刻にした理由を説明しなさい。', a: '金解禁で為替相場が円高に近づき輸出が不利になったうえ、前年に始まった世界恐慌と重なって輸出が大きく減り、金も大量に海外へ流出したから。', exp: '金解禁の目的は、為替を安定させて貿易をのばすことでしたが、時期が悪く逆効果になりました。1931年には金の輸出が再び禁止されました。' },
      { lv: 3, q: '次の土地制度を古い順に並べなさい。ア 墾田永年私財法 イ 太閤検地 ウ 班田収授法 エ 地租改正', a: 'ウ→ア→イ→エ', exp: '班田収授法(7世紀末〜8世紀初めに整備)→ 墾田永年私財法(743年)→ 太閤検地(16世紀末)→ 地租改正(1873年)です。「国が分ける → 私有を認める → 石高で把握 → 所有者が現金で」の流れです。' },
      { lv: 3, q: '足利義満が明から「日本国王」として認められたことには、どのような利点と問題点がありましたか。', a: '利点:明との朝貢貿易で大きな利益を得られた。問題点:明の皇帝に従う形式をとることになり、のちに4代将軍足利義持が、臣下の礼をとることをきらって貿易を一時中止した。', exp: '中国との関係では「実利(貿易の利益)」と「体面(対等かどうか)」がいつも問題になりました。遣隋使の対等外交と比べると理解が深まります。' },
      { lv: 3, q: '鎌倉時代と江戸時代を比べて、文化の担い手がどのように広がったかを説明しなさい。', a: '鎌倉時代には貴族に加えて武士が文化の担い手となり、わかりやすい新しい仏教が民衆にも広がった。江戸時代には、経済力をつけた町人が浮世草子や浮世絵、歌舞伎などの文化をつくり楽しむようになった。', exp: '文化の担い手は「貴族 → 武士・民衆 → 町人 → 大衆」と広がっていきます。経済力や教育の広がりが、文化を楽しむ人をふやしてきました。' }
    ]
  });

  /* ===== 日本史の因果(論述) ===== */
  add('hx_jhist', {
    pat: [
      { name: '開国が国内経済にあたえた影響', freq: 'とてもよく出る', when: '「開港後の経済の変化」「物価の上昇の理由」を問われたら、この型です。', how: ['輸出:生糸・茶が大量に輸出され、国内で品不足 → 値上がり。', '金の流出:金銀の交換比率の差 → 幕府は小判の質を落とす(万延小判)→ さらに物価上昇。', '流通の混乱:産地の商人が直接横浜へ運び、江戸の問屋を通さなくなる → 幕府は五品江戸廻送令(1860年)を出す。'], ex: { q: '幕府が1860年に五品江戸廻送令を出したのはなぜですか。', a: '生糸などが産地から横浜へ直接運ばれ、江戸の問屋を通らなくなって江戸の品不足が深刻になったので、雑穀・水油・ろう・呉服・生糸の5品は江戸の問屋を通してから輸出させようとしたから。', exp: '江戸の流通を守ることがねらいでしたが、外国や在郷商人の反対もあり、効果は十分ではありませんでした。開港が国内の流通のしくみを変えた例です。' } },
      { name: 'なぜその政策が裏目に出たのか', freq: 'よく出る', when: '「〇〇の政策は期待した効果を上げられなかった。その理由を説明せよ」と問われたら、この型です。', how: ['政策の目的(何を良くしようとしたか)を書く。', '実際に起きたこと(予想とちがう反応)を書く。', 'その反応がなぜ起きたか(時期の悪さ、利害の対立など)を書く。'], ex: { q: '天保の改革で株仲間を解散させても、物価が下がらなかった理由を説明しなさい。', a: '物価が上がる原因は株仲間の独占よりも、生産地から大坂への商品の流れが変わって物が届きにくくなったことにあり、株仲間の解散で流通がかえって混乱したから。', exp: '目的(物価を下げる)、結果(流通の混乱)、理由(原因の見誤り)の3段で書くと、論述の形になります。株仲間はのちに再興が許されました。' } },
      { name: '経済の変化が政治を動かす', freq: 'とてもよく出る', when: '好景気・不景気・物価の変化と、内閣の交代や政治の変化を結びつける問題は、この型です。', how: ['経済の変化を書く(物価の急上昇、恐慌など)。', '人々の生活と不満を書く(米騒動、農村の困窮)。', '政治の変化を書く(内閣の交代、政党への不信、軍部の台頭)。'], ex: { q: '1918年の米騒動のあと、原敬内閣が成立した流れを説明しなさい。', a: '第一次世界大戦中の好景気で物価が上がり、さらにシベリア出兵を見こした米の買い占めで米価が急上昇して、全国で米騒動が起きた。その責任をとって寺内正毅内閣が退陣し、立憲政友会の原敬が本格的な政党内閣を組織した。', exp: '「物価上昇 → 米騒動 → 内閣の退陣 → 政党内閣」の鎖です。経済の混乱が、政治の担い手を変えた例として出題されます。' } },
      { name: '明治十四年の政変を「背景・きっかけ・結果」で書く', freq: '難関大で出る', when: '1881年の政変について論述を求められたら、この型です。', how: ['背景:自由民権運動が高まり、国会開設を求める声が強まっていた。政府内でも、早期の国会開設を主張する大隈重信と、慎重な伊藤博文らが対立していた。', 'きっかけ:開拓使官有物払下げ事件で政府への批判が高まった。', '結果:大隈重信を政府から追放し、払下げを中止するとともに、国会開設の勅諭で1890年に国会を開くことを約束した。'], ex: { q: '明治十四年の政変の結果、政府が国民に約束したことは何ですか。', a: '国会開設の勅諭を出し、1890年に国会を開くことを約束した。', exp: '批判をおさえるため、期限を示して国会開設を約束しました。これを受けて板垣退助は自由党を、政府を追われた大隈重信は立憲改進党を結成しました。' } }
    ],
    more: [
      { lv: 1, q: '1881年に、10年後の国会開設を約束した天皇の言葉を何といいますか。', a: '国会開設の勅諭', exp: '明治十四年の政変のときに出されました。約束どおり1890年に第1回帝国議会が開かれました。' },
      { lv: 1, q: '国会開設に備えて、1881年に板垣退助が結成した政党は何ですか。', a: '自由党', exp: '自由党はフランス流の急進的な自由主義の影響を受けていました。翌年、大隈重信はイギリス流の議会政治をめざす立憲改進党を結成しました。' },
      { lv: 1, q: '1882年に立憲改進党を結成した人物はだれですか。', a: '大隈重信', exp: '大隈重信は明治十四年の政変で政府を追われたあと、立憲改進党をつくりました。のちに東京専門学校(現在の早稲田大学)を創立しました。' },
      { lv: 1, q: '1918年の米騒動のきっかけになった、日本の軍事行動は何ですか。', choices: ['シベリア出兵', '日清戦争', '満州事変', '山東出兵'], a: 'A(シベリア出兵)', exp: 'ロシア革命に干渉するためのシベリア出兵を見こして、商人が米を買い占め、米の値段が急に上がりました。' },
      { lv: 1, q: '開国後に、物価の上昇を受けて民衆が「世直し」を求めて起こした一揆を何といいますか。', a: '世直し一揆', exp: '幕末には世直し一揆や打ちこわしが各地で起こりました。1867年には「ええじゃないか」という民衆の騒ぎも広がりました。' },
      { lv: 1, q: '1884年に、埼玉県の農民らが借金の返済の延期などを求めて起こした事件を何といいますか。', a: '秩父事件', exp: '松方正義のデフレ政策で農産物の値段が下がり、借金に苦しむ農民がふえていました。自由党員の一部も加わった激化事件の1つです。' },
      { lv: 1, q: '第1回帝国議会が開かれたのは何年ですか。', a: '1890年', exp: '同じ1890年に第1回衆議院議員選挙が行われました。帝国議会は貴族院と衆議院の二院制でした。' },
      { lv: 2, q: '1880年代に大蔵卿松方正義が行ったデフレ政策は、農村にどのような影響をあたえましたか。', a: '米や繭などの農産物の値段が大きく下がり、地租を納められなくなった自作農が土地を手放して小作農になる例がふえた。', exp: '地租は定額の現金だったので、物価が下がると農民の負担は重くなりました。土地を集めた地主が力を強め、寄生地主制が広がりました。' },
      { lv: 2, q: '1873年の明治六年の政変で、西郷隆盛や板垣退助が政府を去った原因となった対立は何ですか。', a: '朝鮮に武力を背景に開国をせまろうとする征韓論をめぐる対立。', exp: '欧米から帰国した岩倉具視・大久保利通らは、国内の政治の整備を優先すべきだとして反対しました。政府を去った人々は、士族の反乱や自由民権運動の中心になりました。' },
      { lv: 2, q: '1930年に浜口雄幸内閣の蔵相井上準之助が行った金解禁が、裏目に出た理由を説明しなさい。', a: '前年に始まった世界恐慌と時期が重なり、輸出が大きく減って金が大量に海外へ流出し、不景気がいっそう深刻になったから。', exp: '金解禁は為替を安定させて輸出をのばすねらいでしたが、旧平価(実際より円高の水準)での解禁だったことも、輸出に不利に働きました。' },
      { lv: 2, q: '1931年に金輸出を再び禁止し、積極的な財政支出で恐慌からの回復をはかった大蔵大臣はだれですか。', a: '高橋是清', exp: '円安で輸出がのび、軍事費の支出もあって、日本は他国より早く恐慌から回復しました。高橋是清は1936年の二・二六事件で暗殺されました。' },
      { lv: 2, q: '初期議会で、民党(野党)が政府に求めた「政費節減・民力休養」とはどのような主張ですか。', a: '政府の支出をへらし、その分で地租を軽くして国民の負担をやわらげよという主張。', exp: '初期議会では、軍事費をふやしたい政府と、予算をけずりたい民党が衆議院で激しく対立しました。' },
      { lv: 2, q: '戦後すぐの日本で、石炭と鉄鋼の生産に資金や資材を集中させた政策を何といいますか。', choices: ['傾斜生産方式', 'ドッジ・ライン', '所得倍増計画', '殖産興業'], a: 'A(傾斜生産方式)', exp: '石炭と鉄鋼は産業の土台なので、そこから回復させようとしました。しかし資金を大量に出したことでインフレが進みました。' },
      { lv: 2, q: '1949年のドッジ・ラインは、日本経済にどのような効果と影響をもたらしましたか。', a: '赤字を出さない予算や1ドル=360円の単一為替レートの設定でインフレはおさまったが、不景気になり、失業者や倒産がふえた。', exp: 'インフレを止める薬が、不況という副作用を生みました。この不況は、1950年の朝鮮戦争による特需で回復に向かいます。' },
      { lv: 2, q: '開港後、日本の輸出入で、輸出が輸入を大きく上回った最初の数年間に、最大の貿易相手国だったのはどこですか。', a: 'イギリス', exp: '開国を求めたのはアメリカですが、アメリカは南北戦争(1861〜65年)で貿易どころではなくなり、イギリスが最大の貿易相手国となりました。' },
      { lv: 3, q: '明治十四年の政変を、背景・きっかけ・結果の3つにふれて論述しなさい。', a: '背景:自由民権運動が高まり、政府内でも早期の国会開設を主張する大隈重信と、慎重な伊藤博文らが対立していた。きっかけ:開拓使官有物払下げ事件で政府への批判が強まった。結果:政府は大隈を追放し、払下げを中止したうえで、国会開設の勅諭を出して1890年の国会開設を約束した。こうして伊藤らを中心にドイツ流の憲法づくりが進められた。', exp: '3つの段を順に書くと、論述の骨組みができます。政変後に自由党・立憲改進党が結成されたことまで書けると、さらによい答えです。' },
      { lv: 3, q: '永仁の徳政令が、御家人を救うどころか、かえって困らせた理由を説明しなさい。', a: '御家人の手放した土地をただで取りもどさせたため、お金を貸した商人などが損をし、その後は御家人にお金を貸さなくなったから。', exp: '目先の借金は消えても、お金を借りる手段を失いました。「政策が裏目に出る」型の典型で、金解禁などと並べて出題されることがあります。' },
      { lv: 3, q: '1929年に始まった世界恐慌が、日本の政治で軍部が力を強めることにつながった理由を説明しなさい。', a: '昭和恐慌で農村や都市の人々の生活が苦しくなる中、政党は財閥と結びついて有効な手を打てないと批判された。そのため、満州などへの進出で行きづまりを打開しようとする軍部への期待が高まったから。', exp: '「経済の危機 → 政党への不信 → 軍部への期待 → 満州事変(1931年)」の鎖です。経済の変化が政治を動かす型の代表例です。' },
      { lv: 3, q: '1950年の朝鮮戦争が、日本の経済と安全保障にあたえた影響を、それぞれ説明しなさい。', a: '経済:アメリカ軍が日本で大量の物資を調達した特需で景気が回復し、ドッジ・ラインによる不況から立ち直った。安全保障:GHQの指令で警察予備隊がつくられ、のちの自衛隊につながった。また講和が急がれ、1951年にサンフランシスコ平和条約と日米安全保障条約が結ばれた。', exp: '1つの外のできごとが、経済・軍事・外交の3方向に影響しています。結果を方向ごとに分けて書くと、整理された答えになります。' },
      { lv: 3, q: '7世紀後半の日本が、唐にならった律令国家づくりを急いだ理由を、白村江の戦いにふれて説明しなさい。', a: '663年の白村江の戦いで唐と新羅の連合軍に大敗し、攻めこまれるおそれが出てきたため、国の守りを固め、全国の人と土地を天皇のもとに一つにまとめて、強い国の力をもつ必要があったから。', exp: '九州に防人や水城を置いたこと、戸籍をつくったことなども同じ流れです。「外からの衝撃が国内の大改革を生む」型の最初の例です。' }
    ]
  });

  /* ===== 日本史の並べかえ(年代の近いできごと) ===== */
  add('hd_jsoc', {
    pat: [
      { name: '満州事変から国際連盟脱退まで', freq: 'とてもよく出る', when: '1931〜33年のできごとが並んだら、この型です。', how: ['1931年9月=柳条湖事件(満州事変の始まり)。', '1932年3月=満州国の建国宣言 → 5月=五・一五事件 → 9月=日満議定書で満州国を承認。', '1932年10月=リットン報告書の公表 → 1933年3月=国際連盟脱退の通告。', '「事変 → 建国 → 政党内閣の終わり → 承認 → 報告 → 脱退」とつなぐ。'], ex: { q: '次を古い順に並べなさい。ア 国際連盟脱退の通告 イ 柳条湖事件 ウ 五・一五事件', a: 'イ→ウ→ア', exp: '柳条湖事件は1931年、五・一五事件は1932年、国際連盟脱退の通告は1933年です。満州国を認めない犬養毅首相が暗殺されたあと、日本は満州国を承認し、連盟と対立していきました。' } },
      { name: '幕末の近いできごとの並べかえ', freq: 'とてもよく出る', when: '1853〜67年のできごとが並んだら、この型です。', how: ['開国期:ペリー来航(1853年)→ 日米和親条約(1854年)→ 日米修好通商条約・安政の大獄(1858年〜)→ 桜田門外の変(1860年)。', '攘夷期:生麦事件(1862年)→ 薩英戦争(1863年)→ 四国艦隊下関砲撃事件(1864年)。', '倒幕期:薩長同盟(1866年)→ 大政奉還(1867年)。', '「開国 → 攘夷の失敗 → 倒幕」の3つのかたまりで並べる。'], ex: { q: '次を古い順に並べなさい。ア 薩長同盟 イ 桜田門外の変 ウ 薩英戦争', a: 'イ→ウ→ア', exp: '桜田門外の変は1860年、薩英戦争は1863年、薩長同盟は1866年です。薩摩藩は薩英戦争で攘夷の無理をさとり、のちに長州藩と手を結びました。' } },
      { name: '首相の名前で「時代のかたまり」をつくる', freq: 'よく出る', when: '選択肢の文に首相の名前が入っていて、その内閣のできごとで並べる問題は、この型です。', how: ['首相の順を大きく覚える:伊藤博文(初代)→ … → 桂太郎(日露戦争)→ … → 原敬(1918年〜)→ 加藤高明(普通選挙法)→ … → 犬養毅(五・一五事件)→ 東条英機(太平洋戦争開戦)。', 'できごとを首相に結びつけて、かたまりに入れる。', '同じかたまりの中だけ年代を比べる。'], ex: { q: '1925年に普通選挙法を成立させたときの首相はだれですか。', a: '加藤高明', exp: '加藤高明内閣は護憲三派(憲政会・立憲政友会・革新倶楽部)の連立内閣で、普通選挙法と治安維持法を成立させました。原敬内閣(1918年〜)より後のかたまりです。' } },
      { name: '同じ年の中を月で並べる', freq: '難関大で出る', when: '同じ年(1941年・1945年など)のできごとが複数並んでいたら、この型です。', how: ['1941年:4月 日ソ中立条約 → 7月 南部仏印進駐 → 12月 真珠湾攻撃・マレー半島上陸。', '1945年:7月 ポツダム宣言 → 8月6日 広島 → 8月8日 ソ連の宣戦 → 8月9日 長崎 → 8月14日 宣言受諾。', '「外交の準備 → 南進 → 開戦」のように、因果でも順番を確かめる。'], ex: { q: '次の1941年のできごとを古い順に並べなさい。ア 真珠湾攻撃 イ 日ソ中立条約 ウ 南部仏印進駐', a: 'イ→ウ→ア', exp: '北の安全を確保するため4月に日ソ中立条約を結び、7月に資源を求めて南部仏印へ進駐しました。これに対してアメリカが石油の輸出を禁止し、12月の開戦へと進みました。' } }
    ],
    more: [
      { lv: 1, q: '満州事変のきっかけとなった柳条湖事件が起こったのは何年ですか。', a: '1931年', exp: '関東軍が奉天郊外の柳条湖で南満州鉄道の線路を爆破し、中国軍のしわざだとして軍事行動を始めました。' },
      { lv: 1, q: '徳川慶喜が大政奉還を行ったのは何年ですか。', a: '1867年', exp: '同じ1867年に王政復古の大号令が出されました。翌1868年に戊辰戦争が始まり、五箇条の御誓文が出されます。' },
      { lv: 1, q: '桜田門外の変(1860年)の直前に、井伊直弼が反対派を処罰したできごとは何ですか。', a: '安政の大獄', exp: '1858年から翌年にかけて、吉田松陰らが処刑されました。この弾圧への反発が桜田門外の変を生みました。' },
      { lv: 1, q: '1940年に日本がドイツ・イタリアと結んだ同盟を何といいますか。', a: '日独伊三国同盟', exp: 'この同盟でアメリカとの対立が深まりました。アメリカをけん制するねらいがありましたが、かえって関係を悪くしました。' },
      { lv: 1, q: '1945年8月6日に原子爆弾が投下された都市はどこですか。', choices: ['長崎', '広島', '東京', '沖縄'], a: 'B(広島)', exp: '8月6日に広島、8月9日に長崎に原子爆弾が投下されました。8月8日にはソ連が日本に宣戦布告しています。' },
      { lv: 1, q: '1912〜13年の第一次護憲運動で退陣に追いこまれた首相はだれですか。', a: '桂太郎', exp: '尾崎行雄や犬養毅らが「閥族打破・憲政擁護」をかかげ、民衆も加わって桂太郎内閣を倒しました(大正政変)。' },
      { lv: 1, q: '1871年に、条約改正の予備交渉と欧米の視察のために出発した使節団を何といいますか。', a: '岩倉使節団', exp: '岩倉具視を代表に、大久保利通・木戸孝允・伊藤博文らが参加しました。条約改正の交渉は成功しませんでしたが、欧米の進んだ制度を学びました。' },
      { lv: 2, q: '次を古い順に並べなさい。ア 薩長同盟 イ 生麦事件 ウ 薩英戦争', a: 'イ→ウ→ア', exp: '生麦事件は1862年、薩英戦争は1863年、薩長同盟は1866年です。生麦事件の報復として薩英戦争が起こり、攘夷の無理を知った薩摩が長州と結びました。' },
      { lv: 2, q: '次を古い順に並べなさい。ア 国際連盟脱退の通告 イ 満州国の建国宣言 ウ リットン報告書の公表', a: 'イ→ウ→ア', exp: '満州国の建国宣言は1932年3月、リットン報告書の公表は1932年10月、脱退の通告は1933年3月です。報告書をもとにした勧告が採択されたことで脱退しました。' },
      { lv: 2, q: '次を古い順に並べなさい。ア 普通選挙法の成立 イ 米騒動 ウ 関東大震災', a: 'イ→ウ→ア', exp: '米騒動は1918年、関東大震災は1923年、普通選挙法は1925年です。大正期のかたまりの中で、前半・中ごろ・後半に分けて覚えましょう。' },
      { lv: 2, q: '次を古い順に並べなさい。ア 国会開設の勅諭 イ 民撰議院設立の建白書 ウ 西南戦争', a: 'イ→ウ→ア', exp: '民撰議院設立の建白書は1874年、西南戦争は1877年、国会開設の勅諭は1881年です。武力による反抗が終わったあと、言論による自由民権運動が高まりました。' },
      { lv: 2, q: '次を古い順に並べなさい。ア サンフランシスコ平和条約 イ 日本国憲法の公布 ウ 警察予備隊の創設', a: 'イ→ウ→ア', exp: '日本国憲法の公布は1946年、警察予備隊の創設は1950年、サンフランシスコ平和条約は1951年です。朝鮮戦争をはさんで占領政策が変わったことをとらえましょう。' },
      { lv: 2, q: '次の1941年のできごとを古い順に並べたものとして正しいものはどれですか。', choices: ['日ソ中立条約 → 南部仏印進駐 → 真珠湾攻撃', '南部仏印進駐 → 日ソ中立条約 → 真珠湾攻撃', '真珠湾攻撃 → 日ソ中立条約 → 南部仏印進駐', '日ソ中立条約 → 真珠湾攻撃 → 南部仏印進駐'], a: 'A(日ソ中立条約 → 南部仏印進駐 → 真珠湾攻撃)', exp: '4月に日ソ中立条約、7月に南部仏印進駐、12月8日に真珠湾攻撃です。南進の前に北の安全を確保した、という因果で覚えましょう。' },
      { lv: 2, q: '日露戦争が起こったとき(1904年)の首相はだれですか。', a: '桂太郎', exp: '桂太郎内閣のときに日英同盟(1902年)を結び、日露戦争を戦いました。桂太郎と西園寺公望が交互に首相をつとめた時期を桂園時代といいます。' },
      { lv: 2, q: '次の1945年のできごとを古い順に並べなさい。ア 長崎への原子爆弾投下 イ ポツダム宣言の発表 ウ 広島への原子爆弾投下', a: 'イ→ウ→ア', exp: 'ポツダム宣言は7月26日、広島への投下は8月6日、長崎への投下は8月9日です。日本は8月14日に宣言の受諾を決め、15日に国民に知らされました。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 二・二六事件 イ 盧溝橋事件 ウ 五・一五事件 エ 柳条湖事件', a: 'エ→ウ→ア→イ', exp: '柳条湖事件は1931年、五・一五事件は1932年、二・二六事件は1936年、盧溝橋事件は1937年です。「満州事変のかたまり(31〜33年)」と「日中戦争へのかたまり(36〜37年)」に分けると解きやすくなります。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 沖縄返還 イ 日韓基本条約 ウ 東京オリンピック エ 日中平和友好条約', a: 'ウ→イ→ア→エ', exp: '東京オリンピックは1964年、日韓基本条約は1965年、沖縄返還は1972年、日中平和友好条約は1978年です。1972年の日中共同声明と1978年の条約を混同しないようにしましょう。' },
      { lv: 3, q: '次の1940年のできごとを古い順に並べなさい。ア 大政翼賛会の結成 イ 日独伊三国同盟 ウ 北部仏印進駐', a: 'ウ→イ→ア', exp: '北部仏印進駐は9月23日、日独伊三国同盟は9月27日、大政翼賛会の結成は10月12日です。南進と同盟で外の体制を固め、国内では政党が解散して大政翼賛会にまとめられました。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 日朝修好条規 イ 徴兵令 ウ 西南戦争 エ 廃藩置県', a: 'エ→イ→ア→ウ', exp: '廃藩置県は1871年、徴兵令は1873年、日朝修好条規は1876年、西南戦争は1877年です。日朝修好条規は前年の江華島事件をきっかけに結ばれた、日本に有利な不平等条約でした。' },
      { lv: 3, q: '原敬内閣と加藤高明内閣を比べて、選挙制度に関して行ったことのちがいを説明しなさい。', a: '原敬内閣は選挙権の納税額の条件を直接国税3円以上に引き下げたが、普通選挙には慎重だった。加藤高明内閣は納税額の条件をなくし、満25歳以上のすべての男子に選挙権をあたえる普通選挙法を成立させた。', exp: '原敬は小選挙区制も導入しました。同じ「政党内閣」でも、選挙権の広げ方がちがう点がよく問われます。' }
    ]
  });

  /* ===== 中学公民:現代社会 ===== */
  add('c_gendai', {
    pat: [
      { name: '「効率」と「公正」で案を評価する', freq: 'とてもよく出る', when: '2つ以上の案(ルール)が示され「どちらがよいか、効率と公正の観点から説明しなさい」と問われたら、この型です。', how: ['効率=時間・お金・物・労力のむだがないか、をチェックする。', '公正=手続きの公正(みんなが参加できたか)、機会の公正、結果の公正(一部の人だけが損をしないか)をチェックする。', 'それぞれの案の長所と短所を「効率では〜、公正では〜」の形で書く。'], ex: { q: '体育館の使用を「先着順」で決める案は、公正の点でどのような問題が考えられますか。', a: '早く来られる人だけが有利になり、授業や部活動の都合で遅くなる人が使えないなど、機会の公正が保たれないおそれがある。', exp: '先着順はすぐに決まるので効率はよいですが、だれにでも同じ機会があるとは限りません。くじ引きや交代制など、機会を公平にする工夫と比べて評価します。' } },
      { name: '人口ピラミッドの読み取り', freq: 'とてもよく出る', when: '年齢別の人口グラフが出て「どの国(年)か」「何が読み取れるか」と問われたら、この型です。', how: ['すその広さ(子どもの多さ)と、上の部分(高齢者の多さ)を見る。', '富士山型=子どもが多い(発展途上国・昔の日本)、つりがね型=出生と死亡が少ない、つぼ型=少子高齢化が進む。', '数値があれば、65歳以上の割合を計算して7%・14%・21%の基準と比べる。'], ex: { q: '人口ピラミッドのすそがせまく、上の年齢層がふくらんだ「つぼ型」から読み取れることは何ですか。', a: '子どもの数が少なく、高齢者の割合が大きい、少子高齢化が進んだ社会であること。', exp: 'つぼ型は、出生数が減り続けている国に見られる形です。現在の日本はこの形です。高度経済成長期より前の日本は、子どもが多い富士山型に近い形でした。' } },
      { name: '情報の信頼性を手順で判断する', freq: 'よく出る', when: 'インターネットやSNSの情報について「どうすれば正しいか確かめられるか」と問われたら、この型です。', how: ['発信者はだれか(専門機関か、匿名か)を確かめる。', 'いつの情報か(日付)を確かめる。', 'ほかの複数の情報源(新聞・公的機関など)と比べて、同じ内容か確かめる。', '根拠(データの出どころ)が示されているかを見る。'], ex: { q: 'SNSで「〇〇が品切れになる」という投稿を見たとき、すぐに拡散する前にすべきことを1つ答えなさい。', a: '投稿した人がだれか、ほかの信頼できる情報源(公的機関や報道など)でも同じことが伝えられているかを確かめる。', exp: '不確かな情報を広めると、買い占めなどの混乱を引き起こすことがあります。情報を正しく読み取り活用する力を、メディアリテラシーといいます。' } },
      { name: '「得意なものに集中する」と全体がふえる(比較優位)', freq: '難関校で出る', when: '2つの国(人)が2つの物をつくる表が出て「どちらが何に集中するとよいか」と問われたら、この型です。', how: ['それぞれの国で、1つの物をつくるために、もう一方の物をどれだけあきらめるか(相対的な手間)を比べる。', 'あきらめる量が少ないほう(相対的に得意なほう)がその物に集中する。', '集中したあと交換(貿易)すると、両国を合わせた生産量がふえることを確かめる。'], ex: { q: 'A国は小麦1単位に2人、布1単位に4人が必要です。B国は小麦1単位に6人、布1単位に8人が必要です。A国はどちらの生産に集中するとよいですか。', a: '小麦', exp: 'A国は小麦1単位をつくるのに布0.5単位分(2÷4)の手間、B国は0.75単位分(6÷8)の手間がかかります。A国のほうが小麦を相対的に安くつくれるので、A国は小麦、B国は布に集中して交換すると、全体の生産量がふえます。' } }
    ],
    more: [
      { lv: 1, q: '生まれる子どもの数がへり、人口にしめる高齢者の割合がふえることを何といいますか。', a: '少子高齢化', exp: '日本では出生数の減少と平均寿命ののびにより、少子高齢化が急速に進んでいます。' },
      { lv: 1, q: '人やもの、お金、情報が国境をこえて行き来し、世界の結びつきが強まることを何といいますか。', a: 'グローバル化', exp: '交通や通信の発達でグローバル化が進みました。国際分業が進む一方、国どうしの競争も激しくなっています。' },
      { lv: 1, q: '情報通信技術を、アルファベット3文字で何といいますか。', choices: ['AI', 'ICT', 'SNS', 'GPS'], a: 'B(ICT)', exp: 'ICTはInformation and Communication Technologyの略です。AIは人工知能、SNSはソーシャル・ネットワーキング・サービスです。' },
      { lv: 1, q: '人間のように学習したり判断したりするコンピューターの技術を何といいますか。', a: '人工知能(AI)', exp: 'AIは画像の認識や翻訳などに使われています。便利になる一方、仕事の変化や情報の扱い方などの課題もあります。' },
      { lv: 1, q: '夫婦だけ、または親と未婚の子どもだけからなる家族を何といいますか。', a: '核家族', exp: '日本では核家族の世帯が多く、近年は一人で暮らす単独世帯もふえています。' },
      { lv: 1, q: '2015年に国連で採択された、2030年までに達成をめざす17の目標を何といいますか。', a: '持続可能な開発目標(SDGs)', exp: '貧困をなくす、質の高い教育をみんなに、気候変動への対策など17の目標があります。' },
      { lv: 1, q: '対立を合意に導くときに大切な2つの考え方は何ですか。', a: '効率と公正', exp: '効率はむだがないかという考え方、公正は手続きや機会、結果が一部の人に不当にならないかという考え方です。' },
      { lv: 2, q: '情報を正しく読み取り、目的に合わせて活用する力を何といいますか。', a: '情報リテラシー(メディアリテラシー)', exp: '情報があふれる社会では、うのみにせず、発信者や根拠を確かめる力が大切です。' },
      { lv: 2, q: '「効率」の考え方にあてはまるものはどれですか。', choices: ['全員が話し合いに参加できるようにする。', '少ない費用で、より多くの人が満足できる方法を選ぶ。', '一部の人だけが不利にならないようにする。', '決める前に少数の意見も聞く。'], a: 'B(少ない費用で、より多くの人が満足できる方法を選ぶ。)', exp: 'むだを省き、限られた資源で大きな成果を得るのが効率です。ほかの3つは公正の考え方にあたります。' },
      { lv: 2, q: '学級でルールを決めるときに、全員が話し合いに参加できるようにすることは、公正のうち何の公正にあたりますか。', a: '手続きの公正', exp: 'みんなが決定に参加できるかが手続きの公正です。だれにでも同じ機会があるかが機会の公正、結果が不当でないかが結果の公正です。' },
      { lv: 2, q: '人口にしめる65歳以上の人の割合が21%をこえた社会を何といいますか。', a: '超高齢社会', exp: '7%をこえると高齢化社会、14%をこえると高齢社会、21%をこえると超高齢社会とよばれます。日本はすでに超高齢社会です。' },
      { lv: 2, q: '国内の工場が人件費の安い海外へ移り、国内の産業がおとろえることを何といいますか。', a: '産業の空洞化', exp: 'グローバル化の影の部分の1つです。国内の雇用がへるなどの問題が起こります。' },
      { lv: 2, q: '多数決で物事を決めるときに、気をつけるべきことは何ですか。', a: '決める前に十分に話し合い、少数の意見も尊重すること。', exp: '多数決は短い時間で決められる方法ですが、少数の意見が無視されるおそれがあります。話し合いをつくしてから行うことが大切です。' },
      { lv: 2, q: 'ちがう国籍や文化をもつ人々が、たがいの文化を認め合い、ともに暮らすことを何といいますか。', a: '多文化共生', exp: '日本で暮らす外国人がふえる中で、言葉や習慣のちがいを理解し合う取り組みが進められています。' },
      { lv: 2, q: 'SNSに写真を投稿するときに、個人情報を守るために注意すべきことを1つ答えなさい。', a: '写真に写った建物や制服などから、住所や学校がわからないようにする。また、ほかの人の顔を無断でのせない。', exp: '一度ネットに出た情報は、完全に消すことが難しくなります。自分だけでなく、ほかの人のプライバシーや肖像権にも気をつけます。' },
      { lv: 3, q: 'A国は機械1台に4人、米1トンに2人が必要です。B国は機械1台に5人、米1トンに5人が必要です。両国が得意なものに集中して交換するとき、A国とB国はそれぞれ何をつくるとよいですか。', a: 'A国は米、B国は機械', exp: 'A国は米1トンに機械0.5台分(2÷4)の手間、B国は1台分(5÷5)の手間がかかります。米はA国が相対的に得意、機械はB国が相対的に得意(B国は機械1台に米1トン分、A国は米2トン分の手間)です。どちらもA国のほうが少ない人数でつくれても、集中する物は相対的な得意さで決まります。' },
      { lv: 3, q: '少子高齢化が進むと、社会保障の面でどのような課題が生まれますか。', a: '年金や医療などの費用がふえる一方、それを保険料や税で支える働く世代の人数がへるので、一人あたりの負担が重くなる。', exp: '支えられる人がふえ、支える人がへることが問題の中心です。働く人をふやす取り組みや、給付と負担の見直しが議論されています。' },
      { lv: 3, q: 'マンションのごみ置き場の掃除を「1階の住人だけが毎週行う」という案があります。この案を、公正の観点から評価しなさい。', a: '1階の住人だけに負担が集中し、ほかの住人は負担しないので、結果の公正の点で問題がある。全員が交代で担当するなど、負担を公平に分ける案のほうが望ましい。', exp: '「だれが得をして、だれが損をするか」を考えるのが公正の評価です。決め方に全員が参加したかという手続きの公正も合わせて考えるとよいでしょう。' },
      { lv: 3, q: 'インターネット上で見つけた「〇〇が健康によい」という情報の信頼性を確かめる手順を、3つ答えなさい。', a: '①発信者が専門の機関や研究者かを確かめる。②いつ発信された情報かを確かめる。③公的機関などほかの複数の情報源と比べ、根拠となる調査が示されているかを確かめる。', exp: '「だれが」「いつ」「何を根拠に」の3点を確かめるのが基本です。広告や宣伝の目的で書かれた情報もあるので、目的にも注意します。' },
      { lv: 3, q: '人口2万人の町で、65歳以上の人口が5600人でした。この町の高齢化率は何%で、どのような社会にあたりますか。', a: '28%で、超高齢社会にあたる。', exp: '5600÷20000=0.28なので28%です。21%をこえているので超高齢社会です。7%・14%・21%の3つの基準を覚えておきましょう。' }
    ]
  });

  /* ===== 中学公民:政治のしくみ ===== */
  add('c_m3', {
    pat: [
      { name: '国会・選挙の「数字」問題', freq: 'とてもよく出る', when: '任期・定数・年齢・改選の数字を問う問題や、数字を入れかえた正誤問題は、この型です。', how: ['衆議院=任期4年・解散あり・被選挙権25歳以上。', '参議院=任期6年・3年ごとに半数を改選・解散なし・被選挙権30歳以上。', '選挙権は18歳以上。', '「解散があるのはどちらか」「半数改選はどちらか」を必ず区別する。'], ex: { q: '3年ごとに議員の半数を改選し、解散のない議院はどちらですか。', a: '参議院', exp: '参議院は任期6年で、3年ごとに半数ずつ選挙をします。衆議院は任期4年ですが、解散があるので任期の途中で選挙になることが多くあります。' } },
      { name: '衆議院の優越と「出席議員の3分の2」', freq: 'とてもよく出る', when: '衆議院と参議院の議決が異なった場合の扱いを問われたら、この型です。', how: ['法律案=衆議院で出席議員の3分の2以上の多数で再可決すれば成立。', '予算・条約の承認・内閣総理大臣の指名=両院協議会でも一致しなければ衆議院の議決が国会の議決になる。', '予算は衆議院が先に審議する(先議権)。内閣不信任決議も衆議院だけ。', '憲法改正の発議には優越がない(両院とも総議員の3分の2以上)。'], ex: { q: '法律案が衆議院で可決され、参議院で否決されました。法律を成立させるには、どうすればよいですか。', a: '衆議院で、出席議員の3分の2以上の賛成で再び可決する。', exp: '法律案は、予算などとちがい、衆議院の議決がそのまま国会の議決にはなりません。再可決には「出席議員」の3分の2以上が必要で、「総議員」ではない点に注意しましょう。' } },
      { name: '一票の格差の計算', freq: 'よく出る', when: '選挙区ごとの有権者数と定数の表が出て「格差は何倍か」と問われたら、この型です。', how: ['各選挙区で「議員1人あたりの有権者数」を計算する(有権者数 ÷ 定数)。', '最も多い選挙区の値 ÷ 最も少ない選挙区の値 で格差を出す。', '議員1人あたりの有権者数が少ない選挙区ほど、一票の価値が重いと判断する。'], ex: { q: 'X選挙区は有権者48万人で定数1、Y選挙区は有権者16万人で定数1です。一票の格差は何倍で、一票が重いのはどちらですか。', a: '3倍。Y選挙区のほうが一票が重い。', exp: '48万÷16万=3なので3倍の格差です。Yでは16万人で1人を選ぶので、1票がしめる割合が大きく、Xの3倍の重さになります。憲法の法の下の平等にかかわる問題です。' } },
      { name: 'ドント式で議席を配分する', freq: 'よく出る', when: '比例代表制の得票数が示され、各政党の獲得議席数を問われたら、この型です。', how: ['各政党の得票数を1、2、3…でわった表をつくる。', '表の中の数字を大きい順に並べる。', '定数の数だけ上から選び、政党ごとに数える。'], ex: { q: '定数5の比例代表選挙で、A党12000票、B党7500票、C党4500票でした。ドント式で各党の議席数を求めなさい。', a: 'A党3議席、B党1議席、C党1議席', exp: 'わり算の結果は、A党12000・6000・4000、B党7500・3750、C党4500…です。大きい順に5つ選ぶと12000(A)、7500(B)、6000(A)、4500(C)、4000(A)なので、A党3、B党1、C党1です。' } },
      { name: '地方自治の直接請求(署名数と請求先)', freq: 'よく出る', when: '「条例の制定」「首長の解職」などの請求で、必要な署名数や請求先を問われたら、この型です。', how: ['条例の制定・改廃、監査の請求=有権者の50分の1以上の署名。', '議会の解散、首長・議員の解職=原則として有権者の3分の1以上の署名。', '請求先:条例は首長、監査は監査委員、解散・解職は選挙管理委員会。'], ex: { q: '有権者12万人の市で、条例の制定を請求するには何人以上の署名が必要ですか。また、請求先はどこですか。', a: '2400人以上。請求先は市長。', exp: '条例の制定には有権者の50分の1以上が必要なので、120000÷50=2400人です。請求を受けた市長は議会にかけ、その結果を公表します。' } }
    ],
    more: [
      { lv: 1, q: '日本国憲法で「国権の最高機関であつて、国の唯一の立法機関」とされているのは何ですか。', a: '国会', exp: '国会は国民が選んだ議員で構成されるため、国権の最高機関とされます。法律をつくれるのは国会だけです。' },
      { lv: 1, q: '内閣総理大臣を指名するのはどこですか。', choices: ['天皇', '国会', '最高裁判所', '国民の直接選挙'], a: 'B(国会)', exp: '国会が国会議員の中から指名し、天皇が任命します。日本では首相を国民が直接選ぶしくみはありません。' },
      { lv: 1, q: '最高裁判所の長官を指名するのはどこですか。', a: '内閣', exp: '最高裁判所長官は内閣が指名し、天皇が任命します。そのほかの最高裁判所の裁判官は内閣が任命します。' },
      { lv: 1, q: '衆議院議員の任期は何年ですか。', a: '4年', exp: '衆議院議員の任期は4年ですが、解散があると任期の途中でも資格を失います。参議院議員は6年です。' },
      { lv: 1, q: '参議院議員に立候補できるのは何歳以上ですか。', a: '30歳以上', exp: '衆議院議員・市町村長・地方議会議員は25歳以上、参議院議員・都道府県知事は30歳以上です。' },
      { lv: 1, q: '国政選挙で投票できるのは何歳以上ですか。', a: '18歳以上', exp: '2015年の公職選挙法改正により、2016年から18歳以上に引き下げられました。' },
      { lv: 1, q: '『法の精神』で三権分立を主張したフランスの思想家はだれですか。', a: 'モンテスキュー', exp: 'モンテスキューは、権力を立法・行政・司法に分けて互いにおさえ合わせることで、国民の自由が守られると考えました。' },
      { lv: 2, q: '衆議院の優越が認められていないものはどれですか。', choices: ['予算の議決', '条約の承認', '内閣総理大臣の指名', '憲法改正の発議'], a: 'D(憲法改正の発議)', exp: '憲法改正の発議には、衆議院・参議院それぞれで総議員の3分の2以上の賛成が必要で、どちらかが優越することはありません。' },
      { lv: 2, q: '衆議院で内閣不信任案が可決されたとき、内閣はどうしなければなりませんか。', a: '10日以内に衆議院を解散するか、内閣が総辞職しなければならない。', exp: '内閣は国会の信任の上に成り立っているので(議院内閣制)、信任を失えば辞職するか、解散して国民の判断を問うことになります。' },
      { lv: 2, q: '法律などが憲法に違反していないかを最終的に判断するため、「憲法の番人」とよばれる裁判所はどこですか。', a: '最高裁判所', exp: '違憲審査権はすべての裁判所がもちますが、最終的な判断を下すのは最高裁判所です。' },
      { lv: 2, q: '裁判員制度で、裁判員が参加するのはどのような裁判ですか。', a: '重大な犯罪についての刑事裁判の第一審(地方裁判所)。', exp: '裁判員は満18歳以上の国民からくじで選ばれ、裁判官といっしょに有罪か無罪か、有罪ならどのくらいの刑にするかを決めます。' },
      { lv: 2, q: '第一審の判決に不服があるときに、上級の裁判所に訴えることを何といいますか。', a: '控訴', exp: '第一審から第二審へが控訴、第二審から第三審へが上告です。3回まで裁判を受けられるしくみを三審制といいます。' },
      { lv: 2, q: '地方公共団体で、住民が条例の制定を求めるとき、署名を提出する相手はだれですか。', choices: ['選挙管理委員会', '首長', '監査委員', '国会'], a: 'B(首長)', exp: '条例の制定・改廃は有権者の50分の1以上の署名を集めて首長に請求します。解職や解散の請求先は選挙管理委員会です。' },
      { lv: 2, q: '内閣が国会の信任にもとづいて成立し、国会に対して連帯して責任を負うしくみを何といいますか。', a: '議院内閣制', exp: '内閣総理大臣は国会議員の中から選ばれ、国務大臣の過半数も国会議員でなければなりません。' },
      { lv: 2, q: '都道府県知事に立候補できるのは何歳以上ですか。', a: '30歳以上', exp: '都道府県知事は30歳以上、市町村長は25歳以上です。地方議会の議員はどちらも25歳以上です。' },
      { lv: 3, q: '定数5の比例代表選挙で、A党18000票、B党10000票、C党7000票でした。ドント式で各党の獲得議席数を求めなさい。', a: 'A党3議席、B党1議席、C党1議席', exp: 'A党は18000・9000・6000、B党は10000・5000、C党は7000・3500です。大きい順に18000(A)、10000(B)、9000(A)、7000(C)、6000(A)の5つなので、A党3、B党1、C党1です。' },
      { lv: 3, q: 'P選挙区は有権者60万人で定数2、Q選挙区は有権者20万人で定数1です。議員1人あたりの有権者数で比べた一票の格差は何倍ですか。', a: '1.5倍', exp: 'P選挙区は60万÷2=30万人、Q選挙区は20万÷1=20万人です。30万÷20万=1.5倍で、Q選挙区のほうが一票が重くなります。定数でわってから比べるのがポイントです。' },
      { lv: 3, q: '有権者9万人の市で、市長の解職を請求するには何人以上の署名が必要ですか。また、署名を提出する相手はどこですか。', a: '3万人以上。選挙管理委員会。', exp: '解職請求は原則として有権者の3分の1以上なので、90000÷3=30000人です。その後、住民投票で過半数が賛成すれば市長は職を失います。' },
      { lv: 3, q: '最高裁判所の裁判官がその職にふさわしいかを、国民が判断する制度を何といいますか。また、それはいつ行われますか。', a: '国民審査。任命後最初の衆議院議員総選挙のときに行われる(その後は、10年を過ぎてから最初の総選挙のとき)。', exp: '投票者の過半数が「やめさせるべき」とした裁判官はやめさせられます。司法に対する、国民の直接の監視のしくみです。' },
      { lv: 3, q: '国会と内閣の関係について、内閣が国会におよぼす働きと、国会が内閣におよぼす働きを1つずつ答えなさい。', a: '内閣→国会:衆議院の解散を決める。国会→内閣:内閣不信任の決議を行う(または内閣総理大臣を指名する)。', exp: '三権分立は、権力どうしがおさえ合うしくみです。矢印の向きをまちがえると誤りになるので、「だれが・だれに」を確かめましょう。' }
    ]
  });

  /* ===== 中学公民:経済 ===== */
  add('c_econ', {
    pat: [
      { name: '需要・供給曲線の「どちらが動いたか」', freq: 'とてもよく出る', when: 'グラフの曲線が移動していて「何が起きたか」「価格はどうなるか」を問われたら、この型です。', how: ['できごとが「買う側(需要)」と「売る側(供給)」のどちらに影響するかを決める。', '人気が出た・所得がふえた → 需要曲線が右へ。不作・原料の値上がり → 供給曲線が左へ。', '新しい交点を見て、価格と数量の変化を読む。'], ex: { q: 'ある野菜が天候不良で不作になりました。供給曲線はどちらに動き、価格はどうなりますか。', a: '供給曲線が左に動き、価格は上がる。', exp: '不作は売る側の量がへる変化なので、供給曲線が左へ動きます。需要はそのままなので、新しい交点では価格が上がり、取引される量はへります。' } },
      { name: '景気に合わせた金融政策の向き', freq: 'とてもよく出る', when: '「不景気のとき日本銀行はどうするか」など、日銀の政策の向きを問われたら、この型です。', how: ['不景気のとき=市場にお金を流したい → 日銀が銀行から国債などを買う(買いオペレーション)。', '好景気(インフレ)のとき=お金を減らしたい → 日銀が国債などを売る(売りオペレーション)。', 'お金がふえると金利が下がり、企業がお金を借りやすくなる、と順につなげる。'], ex: { q: '不景気のとき、日本銀行は銀行との間で国債をどうしますか。', a: '銀行から国債を買う。', exp: '日銀が国債を買うと、代金が銀行に入り、銀行が貸し出せるお金がふえます。金利が下がって企業がお金を借りやすくなり、生産や投資が活発になることが期待されます。' } },
      { name: '景気に合わせた財政政策の向き', freq: 'よく出る', when: '「不景気のとき政府はどうするか」を、税と公共事業で答えさせる問題は、この型です。', how: ['不景気=減税して家計・企業の使えるお金をふやす、公共事業をふやして仕事をつくる。', '好景気=増税する、公共事業をへらして景気の過熱をおさえる。', '日銀(金融政策)と政府(財政政策)の主語を区別する。'], ex: { q: '不景気のとき、政府が行う財政政策を2つ答えなさい。', a: '減税を行う。公共事業をふやす。', exp: '減税で消費をうながし、公共事業で雇用と需要を生みます。金融政策は日本銀行、財政政策は政府が行うので、主語のすりかえに注意しましょう。' } },
      { name: '「名目」と「実質」の計算', freq: 'よく出る', when: '給料や預金の増加率と物価の上昇率が両方示されたら、この型です。', how: ['名目=見た目の金額の変化。', '実質=物価の変化を考えに入れた、実際に買える量の変化。', 'おおよそ「名目の伸び率 − 物価の上昇率」で実質の伸び率を求める。'], ex: { q: '給料が3%上がり、物価が5%上がりました。実質的な給料はどうなりましたか。', a: '約2%下がった。', exp: '3−5=−2なので、実際に買える物の量は約2%へりました(正確には1.03÷1.05≒0.981で約1.9%減)。金額がふえても、物価がそれ以上に上がれば暮らしは苦しくなります。' } },
      { name: '信用創造の計算', freq: '難関校で出る', when: '「最初の預金」と「支払準備率」が示され、預金の総額や新たに生まれた預金を問われたら、この型です。', how: ['預金総額 = 最初の預金 ÷ 支払準備率。', '信用創造で新たに生まれた預金 = 預金総額 − 最初の預金。', '支払準備率が小さいほど、ふえる額が大きくなる。'], ex: { q: '最初の預金が100万円、支払準備率が10%のとき、銀行全体の預金総額はいくらになりますか。', a: '1000万円', exp: '100万÷0.1=1000万円です。新たに生まれた預金は1000万−100万=900万円です。銀行が貸したお金がまた別の銀行に預けられることをくり返して、預金がふえていきます。' } }
    ],
    more: [
      { lv: 1, q: '家計が企業に提供し、その見返りに賃金を受けとるものは何ですか。', a: '労働力', exp: '家計は労働力を提供して賃金を得て、そのお金で企業から商品を買います。家計・企業・政府の3つが経済の主体です。' },
      { lv: 1, q: 'ほかの条件が同じとき、商品の価格が上がると、需要量はどうなりますか。', a: 'へる', exp: '高くなると買いたい人が少なくなるので、需要量はへります。そのため需要曲線は右下がりになります。' },
      { lv: 1, q: '株式会社が利益の一部を株主に分けるものを何といいますか。', a: '配当(配当金)', exp: '株主は株式会社の出資者で、配当を受けとり、株主総会で議決に参加できます。会社が倒産しても、出資した額以上の責任は負いません(有限責任)。' },
      { lv: 1, q: '日本銀行が紙幣(日本銀行券)を発行する役割を何といいますか。', choices: ['政府の銀行', '銀行の銀行', '発券銀行', '中央銀行'], a: 'C(発券銀行)', exp: '日本銀行の3つの役割は、発券銀行・銀行の銀行・政府の銀行です。中央銀行は日本銀行そのものの位置づけです。' },
      { lv: 1, q: '労働三法とは、労働基準法・労働組合法と、もう1つは何ですか。', a: '労働関係調整法', exp: '労働関係調整法は、労働者と使用者の争いを解決するための法律です。労働基準法は労働条件の最低基準を定めています。' },
      { lv: 1, q: '消費税は、直接税と間接税のどちらですか。', a: '間接税', exp: '消費税は、税を負担する人(買う人)と納める人(お店)がちがうので間接税です。所得税のように負担する人と納める人が同じものは直接税です。' },
      { lv: 1, q: '物価が上がり続け、お金の価値が下がっていく現象を何といいますか。', a: 'インフレーション(インフレ)', exp: '反対に、物価が下がり続ける現象をデフレーション(デフレ)といいます。' },
      { lv: 2, q: '需要量と供給量が一致するときの価格を何といいますか。', a: '均衡価格', exp: '需要曲線と供給曲線の交点で決まる価格です。価格がこれより高いと売れ残りが出て、安いと品不足になります。' },
      { lv: 2, q: '独占禁止法にもとづいて、企業の公正な競争を監視している行政機関はどこですか。', a: '公正取引委員会', exp: '企業どうしが価格を話し合って決めること(カルテル)などを取りしまり、消費者の利益を守っています。' },
      { lv: 2, q: '所得が多い人ほど、高い税率がかけられるしくみを何といいますか。', a: '累進課税', exp: '所得税や相続税で採用されています。所得の格差を小さくする働き(所得の再分配)があります。' },
      { lv: 2, q: '好景気で物価が上がりすぎているとき、日本銀行が行う公開市場操作として正しいものはどれですか。', choices: ['銀行から国債を買う。', '銀行に国債を売る。', '紙幣を大量に発行する。', '税金を下げる。'], a: 'B(銀行に国債を売る。)', exp: '日銀が国債を売ると、銀行は代金を日銀に払うので、貸し出せるお金がへります。金利が上がり、景気の過熱がおさえられます。税金を変えるのは政府の財政政策です。' },
      { lv: 2, q: '好景気で景気が過熱しているとき、政府が行う財政政策を2つ答えなさい。', a: '増税を行う。公共事業をへらす。', exp: '使えるお金をへらし、政府の需要もへらすことで、景気の行きすぎをおさえます。' },
      { lv: 2, q: '企業が株式や社債を発行して、家計などから直接資金を集めることを何といいますか。', a: '直接金融', exp: '銀行が預金を集めて企業に貸し出す方法は、銀行が間に入るので間接金融といいます。' },
      { lv: 2, q: '労働基準法で定められた、労働時間の上限は1日何時間、1週間で何時間ですか。', a: '1日8時間、1週間40時間', exp: 'これをこえて働かせるには、労働者の代表との協定などが必要で、割増賃金を払わなければなりません。' },
      { lv: 2, q: '少数の企業が市場の大部分をしめる状態を何といい、そのときどのような問題が起こりやすいですか。', a: '寡占。価格競争が起こりにくくなり、価格が高めに保たれやすい(管理価格)。', exp: '競争が弱まると、消費者は不当に高い価格で買わされるおそれがあります。そのため独占禁止法で公正な競争を守っています。' },
      { lv: 3, q: '最初の預金が200万円、支払準備率が20%のとき、信用創造によって新たに生まれる預金はいくらですか。', a: '800万円', exp: '預金総額は200万÷0.2=1000万円です。新たに生まれた預金は1000万−200万=800万円です。最初の預金をふくめた総額と、新たな分を区別しましょう。' },
      { lv: 3, q: '給料が2%上がり、同じ期間に物価が4%上がりました。実質的な給料は、およそ何%どうなりましたか。', a: '約2%下がった(正確には約1.9%)', exp: '2−4=−2で、約2%の減少です。正確には1.02÷1.04≒0.981なので約1.9%減です。名目ではふえていても、実質ではへっていることがあります。' },
      { lv: 3, q: 'あるスニーカーがテレビで紹介されて急に人気が出ました。需要曲線・供給曲線のどちらがどちらに動き、価格と取引量はどうなりますか。', a: '需要曲線が右に動き、価格は上がり、取引量はふえる。', exp: '人気は買う側の変化なので需要曲線が動きます。供給曲線はそのままなので、新しい交点は右上に移ります。供給曲線が動いたと考えるのがよくあるまちがいです。' },
      { lv: 3, q: '原油の値上がりで、ガソリンをつくる費用が上がりました。供給曲線はどちらに動き、価格と取引量はどうなりますか。', a: '供給曲線が左に動き、価格は上がり、取引量はへる。', exp: '費用が上がると、同じ価格では売りたい量がへるので、供給曲線は左(上)に動きます。需要が同じなら、新しい交点は左上になります。' },
      { lv: 3, q: '「デフレスパイラル」とはどのような状態か、物価・企業の利益・賃金の語を使って説明しなさい。', a: '物価が下がると企業の利益がへり、賃金が下がったり雇用がへったりする。すると人々が物を買わなくなり、さらに物価が下がる、という悪い循環が続く状態。', exp: 'スパイラルは「らせん」の意味で、悪循環がくり返されることを表します。日本では1990年代後半から2000年代にかけて、デフレが長く続きました。' }
    ]
  });

  /* ===== 中学公民:国際社会 ===== */
  add('c_kokusai', {
    pat: [
      { name: '国際機関の「略称と仕事」の組み合わせ', freq: 'とてもよく出る', when: 'アルファベットの略称と、その機関の仕事を結びつける問題は、この型です。', how: ['UNESCO=教育・科学・文化(世界遺産)。UNICEF=子どもの支援。', 'WHO=保健・医療。UNHCR=難民の保護。', 'WTO=貿易のルール。IAEA=原子力の平和利用と監視。', '略称の一部(HCR=High Commissioner for Refugees など)を手がかりにする。'], ex: { q: '難民の保護や支援を行う国連の機関はどれですか。ア UNESCO イ UNHCR ウ WHO エ WTO', a: 'イ(UNHCR)', exp: 'UNHCRは国連難民高等弁務官事務所です。UNESCOは教育・科学・文化、WHOは保健、WTOは貿易を担当します。名前と仕事の組み合わせをすりかえた選択肢がよく出ます。' } },
      { name: '安全保障理事会の議決(拒否権)', freq: 'とてもよく出る', when: '安保理の投票結果が示され「可決か否決か」を問われたら、この型です。', how: ['安保理は常任理事国5か国(アメリカ・イギリス・フランス・ロシア・中国)と非常任理事国10か国の計15か国。', '重要な問題は、9か国以上の賛成が必要で、さらに常任理事国が1か国でも反対すると否決(拒否権)。', '賛成の数と、常任理事国の反対があるかの2点を確かめる。'], ex: { q: '安保理で、賛成13か国・反対2か国(どちらも常任理事国)でした。この決議は成立しますか。', a: '成立しない(否決)。', exp: '賛成は9か国以上ありますが、常任理事国が反対しているので拒否権が使われたことになり、否決されます。賛成の多さだけで判断しないことが大切です。' } },
      { name: '地球環境問題の国際的な取り決め', freq: 'よく出る', when: '京都議定書・パリ協定などの名前と内容を問われたら、この型です。', how: ['1992年=地球サミット(国連環境開発会議)で気候変動枠組条約。', '1997年=京都議定書。先進国に温室効果ガスの削減を義務づけた。', '2015年=パリ協定。途上国をふくむすべての国が削減目標を出す。', '「先進国だけ」か「すべての国」かで区別する。'], ex: { q: '2015年に採択され、発展途上国をふくむすべての参加国が温室効果ガスの削減目標を立てることになった取り決めは何ですか。', a: 'パリ協定', exp: '京都議定書は先進国だけに削減を義務づけたため、排出量のふえた途上国との公平さが問題になりました。パリ協定は、すべての国が目標を出して取り組むしくみです。' } },
      { name: '南北問題と南南問題', freq: 'よく出る', when: '1人あたりの所得の表などが示され、国どうしの経済格差を問われたら、この型です。', how: ['南北問題=おもに北半球にある先進国と、南側に多い発展途上国の格差。', '南南問題=発展途上国の中での格差(資源をもつ国・工業化した国と、そうでない国)。', '原因として、モノカルチャー経済(特定の産物にたよる経済)などを挙げる。'], ex: { q: '発展途上国の中で、産油国や工業化が進んだ国と、そうでない国との間で経済格差が広がっていることを何といいますか。', a: '南南問題', exp: '先進国と途上国の格差が南北問題、途上国どうしの格差が南南問題です。どちらの国どうしの比較かを確かめて区別しましょう。' } }
    ],
    more: [
      { lv: 1, q: '国家が成り立つための3つの要素は、領域・国民と、もう1つは何ですか。', a: '主権', exp: '主権とは、ほかの国から支配や干渉を受けずに、自分の国のことを決める権利です。領域は領土・領海・領空からなります。' },
      { lv: 1, q: '国際連合の本部が置かれている都市はどこですか。', a: 'ニューヨーク', exp: '国連は1945年に発足し、本部はアメリカのニューヨークにあります。' },
      { lv: 1, q: '安全保障理事会の常任理事国は何か国ですか。', a: '5か国', exp: 'アメリカ・イギリス・フランス・ロシア・中国の5か国です。非常任理事国は10か国で、任期は2年です。' },
      { lv: 1, q: '難民の保護や支援を行う国連の機関を何といいますか。', choices: ['UNICEF', 'UNHCR', 'UNESCO', 'IMF'], a: 'B(UNHCR)', exp: 'UNHCRは国連難民高等弁務官事務所です。UNICEFは国連児童基金で、子どもの支援を行います。' },
      { lv: 1, q: '東南アジアの国々がつくる地域協力の組織を何といいますか。', a: 'ASEAN(東南アジア諸国連合)', exp: 'ASEANは東南アジアの国々が経済や政治の面で協力するための組織です。' },
      { lv: 1, q: '地球温暖化のおもな原因とされる、二酸化炭素などのガスをまとめて何といいますか。', a: '温室効果ガス', exp: '石油や石炭などの化石燃料を燃やすと二酸化炭素が出ます。温室効果ガスが熱を閉じこめ、地球の気温が上がると考えられています。' },
      { lv: 1, q: '日本が核兵器について定めている「もたず、つくらず、もちこませず」の原則を何といいますか。', a: '非核三原則', exp: '唯一の被爆国として、日本は非核三原則をかかげています。' },
      { lv: 2, q: '安保理で、賛成12か国・反対1か国(常任理事国)・棄権2か国でした。この重要な問題の決議は成立しますか。', a: '成立しない(否決)。', exp: '賛成は9か国以上ありますが、常任理事国が1か国でも反対すれば拒否権によって否決されます。' },
      { lv: 2, q: '国連総会での投票のしくみとして正しいものはどれですか。', choices: ['人口に応じて票数が決まる。', 'すべての加盟国が1国1票をもつ。', '常任理事国だけが投票できる。', '分担金の多い国ほど票が多い。'], a: 'B(すべての加盟国が1国1票をもつ。)', exp: '総会では、国の大きさや人口に関係なく、すべての加盟国が平等に1票をもちます。' },
      { lv: 2, q: '紛争が起きた地域で、停戦の監視などを行う国連の活動を何といいますか。', a: '平和維持活動(PKO)', exp: '日本も1992年にPKO協力法をつくり、自衛隊がカンボジアなどで活動しました。' },
      { lv: 2, q: '1997年に採択された京都議定書の特色は何ですか。', a: '先進国に、温室効果ガスの排出量を削減することを義務づけた。', exp: '一方で、発展途上国には削減義務がなく、アメリカも離脱したため、効果が限られるという課題がありました。' },
      { lv: 2, q: '先進国の政府が、発展途上国に資金や技術を提供する援助を何といいますか。', a: '政府開発援助(ODA)', exp: '日本は道路や橋などのインフラの整備や、技術者の派遣などを行ってきました。青年海外協力隊の派遣もその一部です。' },
      { lv: 2, q: '発展途上国の産物を、生産者の生活が成り立つ公正な価格で取引するしくみを何といいますか。', a: 'フェアトレード', exp: 'コーヒーやチョコレートなどで取り組まれています。生産者の暮らしの安定や、児童労働をなくすことにつながります。' },
      { lv: 2, q: '領海は、海岸線から何海里までですか。', a: '12海里', exp: '領海は12海里(約22km)まで、排他的経済水域は200海里(約370km)までです。どこの国の領海でもない公海では、どの国の船も自由に航行や漁業ができます(公海自由の原則)。' },
      { lv: 2, q: '1993年に発足し、多くの加盟国が共通通貨ユーロを導入している地域統合を何といいますか。', a: 'EU(ヨーロッパ連合)', exp: 'EUでは人・もの・お金が国境をこえて自由に移動できます。2020年にイギリスが離脱しました。' },
      { lv: 3, q: '南南問題とは何か、例を挙げて説明しなさい。', a: '発展途上国どうしの間に生じた経済格差の問題。たとえば、石油を産出する国や工業化が進んだ国は豊かになった一方、資源が少なく産業が育っていない国は貧しいままである。', exp: '「途上国の中での差」であることがポイントです。南北問題(先進国と途上国の格差)と区別して書きましょう。' },
      { lv: 3, q: 'モノカルチャー経済の国が、経済的に不安定になりやすいのはなぜですか。', a: '特定の農産物や鉱産資源の輸出にたよっているため、天候や国際価格の変動によって、国の収入が大きく左右されるから。', exp: 'たとえばカカオやコーヒーの価格が下がると、国全体の収入がへってしまいます。産業の多角化が課題になっています。' },
      { lv: 3, q: 'EUの統合によって得られた長所と、課題を1つずつ説明しなさい。', a: '長所:国境での検査や関税がなくなり、人やもの・お金の移動が自由になって、経済が活発になった。課題:加盟国の間の経済格差が大きく、豊かな国の負担がふえたり、仕事を求めて人が移動することで問題が生じたりしている。', exp: '共通通貨のため、各国が自由に金融政策を行えない点も課題です。イギリスの離脱は、統合への不満が表れた例です。' },
      { lv: 3, q: '安保理で、非常任理事国10か国と常任理事国4か国が賛成し、常任理事国1か国が棄権しました。この重要な問題の決議は成立しますか。', a: '成立する(可決)。', exp: '賛成は14か国で9か国以上あり、常任理事国の反対もありません。慣例として、常任理事国の棄権は拒否権の行使とはみなされません。「反対」と「棄権」の区別が問われます。' },
      { lv: 3, q: '太陽光や風力などの再生可能エネルギーの長所と課題を、1つずつ説明しなさい。', a: '長所:発電のときに二酸化炭素をほとんど出さず、資源がなくならない。課題:天候や季節によって発電量が変わりやすく、安定した電力の供給が難しい。', exp: 'ほかの課題として、発電の費用や、設置に広い土地が必要なことも挙げられます。蓄電の技術の進歩が期待されています。' }
    ]
  });

  /* ===== 高校公共・政治経済 ===== */
  add('c_h3', {
    pat: [
      { name: '円高・円安の判定と換算', freq: 'とてもよく出る', when: '「1ドル=〇円から△円になった」と為替相場の変化が示されたら、この型です。', how: ['1ドルを買うのに必要な円が少なくなれば円高、多くなれば円安(数字が小さくなると円高)。', '円での価格 → ドルでの価格は「円 ÷ レート」、ドル → 円は「ドル × レート」。', '円高は輸入に有利・輸出に不利、円安はその逆、と影響を確かめる。'], ex: { q: '1ドル=100円から1ドル=125円になりました。日本でつくった200万円の機械は、アメリカでは何ドルから何ドルになりますか。', a: '2万ドルから1万6000ドルになる(円安)。', exp: '200万÷100=2万ドル、200万÷125=1万6000ドルです。円安になるとドルで見た日本製品の価格が下がるので、輸出に有利になります。' } },
      { name: 'GDPを付加価値で求める', freq: 'よく出る', when: '原料 → 加工 → 販売と、各段階の売上額が示されてGDPを問われたら、この型です。', how: ['各段階の付加価値 = その段階の売上 − 仕入れた中間生産物の額。', '付加価値をすべて足す。', '最終生産物(最後に売れた額)と一致することを確かめる。売上の合計を足すのは二重計算で誤り。'], ex: { q: '農家が小麦を100億円で製粉業者に売り、製粉業者が小麦粉を150億円でパン屋に売り、パン屋がパンを250億円で消費者に売りました(原料以外の仕入れはないものとします)。GDPはいくらですか。', a: '250億円', exp: '付加価値は農家100億、製粉業者150−100=50億、パン屋250−150=100億で、合計250億円です。最終生産物のパンの額と同じになります。売上の合計500億円は中間生産物を重ねて数えているので誤りです。' } },
      { name: '「市場の失敗」の種類を見分ける', freq: 'よく出る', when: '事例が示され「市場の失敗のどれにあたるか」を問われたら、この型です。', how: ['外部不経済=取引に関係のない人に悪い影響(公害など)。', '公共財=料金を払わない人も利用でき、市場では供給されにくい(道路・灯台・国防)。', '独占・寡占=競争が働かず価格が高止まり。', '情報の非対称性=売り手と買い手で持つ情報に差がある(中古車・保険)。'], ex: { q: '工場の排煙で周辺住民に健康被害が出ているのに、その費用が製品の価格にふくまれていない状態は、市場の失敗のどれにあたりますか。', a: '外部不経済', exp: '市場の取引の外にいる住民に費用(被害)を負わせているので外部不経済です。政府は規制や課税で、費用を生産者に負担させるなどの対策をとります。' } },
      { name: 'プライマリーバランス(基礎的財政収支)の判定', freq: '難関大で出る', when: '歳入・歳出の内訳が示され「財政の健全さ」を問われたら、この型です。', how: ['歳入から公債金(借金)を除いた税収などを出す。', '歳出から国債費(借金の返済と利子)を除いた政策の経費を出す。', '税収など − 政策の経費 がプラスなら黒字、マイナスなら赤字。'], ex: { q: '歳入100(税収など70・公債金30)、歳出100(国債費20・政策の経費80)の国のプライマリーバランスはいくらですか。', a: '10の赤字(−10)', exp: '税収など70で政策の経費80をまかなえていないので、70−80=−10の赤字です。政策の経費を借金なしでまかなえているかを見る指標です。' } }
    ],
    more: [
      { lv: 1, q: '1ドル=100円から1ドル=80円になることを、円高・円安のどちらといいますか。', a: '円高', exp: '1ドルを買うのに必要な円が100円から80円に減ったので、円の価値が上がった円高です。数字が小さくなると円高、と覚えましょう。' },
      { lv: 1, q: '社会保障の4つの柱のうち、生活に困っている人に生活費などを支給する生活保護は、どれにあたりますか。', choices: ['社会保険', '公的扶助', '社会福祉', '公衆衛生'], a: 'B(公的扶助)', exp: '公的扶助は、税金を財源として最低限度の生活を保障するしくみです。日本国憲法第25条の生存権にもとづきます。' },
      { lv: 1, q: '権力をもつ人も法に従わなければならないという考え方を何といいますか。', a: '法の支配', exp: '権力者が思いのままに支配する「人の支配」に対する考え方です。イギリスで発達し、立憲主義の土台になっています。' },
      { lv: 1, q: '訪問販売などで契約したあと、一定の期間内であれば無条件で契約を取り消せる制度を何といいますか。', a: 'クーリング・オフ', exp: '訪問販売や電話勧誘販売では、原則として8日以内なら書面などで契約を解除できます。店で自分から買った場合は対象外です。' },
      { lv: 1, q: '日本銀行が金融政策で最も重視している目標は何ですか。', a: '物価の安定', exp: '日本銀行は物価の安定を図ることを通じて、経済の健全な発展に役立つことを目的としています。' },
      { lv: 1, q: '欠陥のある製品で被害を受けたとき、製造者の過失を証明しなくても損害賠償を求められることを定めた法律を何といいますか。', a: '製造物責任法(PL法)', exp: '消費者は製品の欠陥を示せばよく、メーカーに過失があったかどうかを証明する必要はありません。1995年に施行されました。' },
      { lv: 1, q: '道路や灯台のように、料金を払わない人も利用でき、市場にまかせると十分に供給されないものを何といいますか。', a: '公共財', exp: '公共財は「だれかが使っても、ほかの人が使えなくなりにくい」「料金を払わない人を締め出しにくい」という性質をもち、政府が供給します。' },
      { lv: 2, q: '円安になると、日本の輸出企業にとって有利・不利のどちらですか。理由も答えなさい。', a: '有利。外国での日本製品のドル建ての価格が下がり、売れやすくなるから(または、同じドルの売上でも円に直すと受けとる額がふえるから)。', exp: '円安は輸出に有利、輸入に不利です。逆に、輸入した原料や食料は円での価格が上がるので、物価が上がりやすくなります。' },
      { lv: 2, q: '1ドル=150円のとき、アメリカで3万ドルの車を日本に輸入すると、円ではいくらになりますか。', a: '450万円', exp: 'ドルを円に直すときは、ドル × レートなので、30000×150=4500000円です。1ドル=100円のときなら300万円なので、円安ほど輸入品は高くなります。' },
      { lv: 2, q: '中古車の売り手は車の欠陥を知っているが、買い手は知らないという状態を、市場の失敗の何といいますか。', a: '情報の非対称性', exp: '買い手が品質を見分けられないと、よい商品まで安くしか売れず、市場がうまく働かなくなります。情報の開示を義務づけるなどの対策があります。' },
      { lv: 2, q: '歳入のうち、国債の発行による収入(公債金)がしめる割合を何といいますか。', a: '国債依存度(公債依存度)', exp: '日本では歳入の3割前後を国債にたよる年が多く、借金の残高が大きくなっています。' },
      { lv: 2, q: '2022年から成年年齢が18歳に引き下げられたことで、18歳・19歳の人の契約にどのような変化がありましたか。', a: '親の同意なしに一人で契約できるようになった一方、未成年者であることを理由に契約を取り消すこと(未成年者取消権)ができなくなった。', exp: '自由がふえると、責任もふえます。悪質な勧誘などのトラブルに注意し、消費生活センター(電話番号188)などに相談できることを知っておきましょう。' },
      { lv: 2, q: '社会保険にふくまれないものはどれですか。', choices: ['年金保険', '医療保険', '生活保護', '介護保険'], a: 'C(生活保護)', exp: '社会保険は保険料を出し合って備えるしくみで、年金・医療・雇用・労災・介護保険があります。生活保護は税金による公的扶助です。' },
      { lv: 2, q: '金融政策で、日本銀行が国債などを売買して市場に出回るお金の量を調節する方法を何といいますか。', a: '公開市場操作(オープン・マーケット・オペレーション)', exp: '不景気には国債を買って資金を供給し(買いオペ)、景気の過熱時には売って資金を吸収します(売りオペ)。' },
      { lv: 2, q: '名目GDPが前年より3%ふえ、物価が1%上がりました。実質GDPの成長率は、およそ何%ですか。', a: '約2%', exp: '実質成長率は、おおよそ名目成長率 − 物価上昇率で求められます。3−1=2%です。物価の上がった分を差し引いて、実際の生産量の伸びを見ます。' },
      { lv: 3, q: '林業者が木材を30万円で家具工房に売り、家具工房が家具を80万円で家具店に売り、家具店が120万円で消費者に売りました(ほかの仕入れはないものとします)。各段階の付加価値とGDPを求めなさい。', a: '付加価値は林業者30万円、家具工房50万円、家具店40万円。GDPは120万円。', exp: '家具工房は80−30=50万円、家具店は120−80=40万円です。合計は30+50+40=120万円で、最終生産物の価格と一致します。売上の合計230万円は二重計算です。' },
      { lv: 3, q: '日本の金利が上がり、アメリカの金利は変わらないとき、円相場は円高・円安のどちらに動きやすいですか。理由も説明しなさい。', a: '円高に動きやすい。日本で預けたほうが利子が多くなるので、ドルを売って円を買う動きがふえるから。', exp: '為替相場も、円を「買う人」と「売る人」の需要と供給で決まります。円を買う人がふえれば円の値段が上がる、つまり円高になります。' },
      { lv: 3, q: '歳入200(税収など130・公債金70)、歳出200(国債費50・政策の経費150)の国について、プライマリーバランスを求め、健全かどうかを答えなさい。', a: '130−150=−20で、20の赤字。政策の経費を税収などでまかなえておらず、健全とはいえない。', exp: '国債費を除いた政策の経費が、借金をせずにまかなえているかを見ます。赤字が続くと国債の残高がふえ、将来の利払いの負担が重くなります。' },
      { lv: 3, q: '1ドル=110円から1ドル=88円になりました。日本で440万円の自動車は、アメリカでのドル建て価格がどう変わり、輸出にどのような影響がありますか。', a: '4万ドルから5万ドルに上がる(円高)。アメリカでの価格が高くなるので、輸出がへりやすくなる。', exp: '440万÷110=4万ドル、440万÷88=5万ドルです。円高になるとドル建ての価格が上がり、輸出に不利になります。工場を海外に移す企業がふえる理由の1つです。' },
      { lv: 3, q: '社会保障の財源を「税」中心にする場合と、「保険料」中心にする場合の特徴を、1つずつ説明しなさい。', a: '税中心:所得に応じて広く負担を求めるので、保険料を払えない人もふくめて保障できるが、増税への合意が得にくい。保険料中心:払った人が給付を受けるので負担と給付の関係がわかりやすいが、未納の人が保障から外れるおそれがある。', exp: '少子高齢化で給付がふえる中、だれがどのように負担するかが大きな課題です。正解は1つではなく、長所と短所を比べて論じることが大切です。' }
    ]
  });

  /* ===== 中学地理:日本の諸地域 ===== */
  add('c_jregion', {
    pat: [
      { name: '雨温図で地方の都市を判定する', freq: 'とてもよく出る', when: '那覇・高松・金沢・松本・札幌などの雨温図が並んでいたら、この型です。', how: ['冬の気温が0℃を大きく下回り、梅雨がほとんどない → 札幌(北海道の気候)。', '冬の降水量が多い → 金沢など(日本海側の気候)。', '1年中雨が少なく温暖 → 高松など(瀬戸内の気候)。', '1年中暖かく、冬も15℃前後ある → 那覇(南西諸島の気候)。'], ex: { q: '1年を通じて降水量が少なく、冬も比較的温暖な雨温図は、那覇・高松・金沢のうちどれですか。', a: '高松', exp: '高松は中国山地と四国山地にはさまれた瀬戸内の気候です。金沢は冬の降水量が多く、那覇は1年中気温が高く降水量も多いので区別できます。' } },
      { name: '産業の統計から都道府県を当てる', freq: 'とてもよく出る', when: '農産物の生産量の上位県や、工業製品の出荷額の表が出たら、この型です。', how: ['確実な上位県を手がかりにする:りんご=青森県、さくらんぼ=山形県、みかん=和歌山県、ぶどう・もも=山梨県など。', 'その作物が育つ理由(すずしい気候・水はけのよい扇状地・温暖な斜面など)と結びつける。', '残りの選択肢は、地方の特色(工業地帯・観光など)で消していく。'], ex: { q: 'りんごの生産量が全国で最も多い県はどこですか。', a: '青森県', exp: 'りんごはすずしい気候を好むので、東北地方や長野県でさかんに栽培されます。中でも青森県が全国の半分以上を生産しています。' } },
      { name: '「原因 → 課題 → 取り組み」で地域の課題を説明する', freq: 'よく出る', when: '過疎・過密・環境問題など、地域の課題についての記述は、この型です。', how: ['原因:なぜその課題が起きたか(若者の都市への流出、工業化など)。', '課題:何に困っているか(学校や病院の閉鎖、交通機関の廃止など)。', '取り組み:地域で行われている工夫(地域おこし、Iターン・Uターンの受け入れ、観光など)。'], ex: { q: '中国山地の山間部で過疎が進んだ原因を1つ答えなさい。', a: '仕事が少ないため、若い人たちが仕事を求めて都市へ移り住んだから。', exp: '若い人が出ていくと高齢化が進み、学校や病院が維持できなくなる課題が生まれます。地域の特産品づくりや観光などで、人を呼びこむ取り組みが行われています。' } },
      { name: 'エネルギーの変化と地域の盛衰', freq: 'よく出る', when: '炭鉱の町・鉄の町の変化や、北九州工業地域の地位の低下などを問われたら、この型です。', how: ['1901年に八幡製鉄所が操業 → 近くの筑豊炭田の石炭と、中国から輸入した鉄鉱石を利用。', '1960年代にエネルギーの中心が石炭から石油へ(エネルギー革命)→ 炭鉱が閉山。', '産業の変化に合わせて、自動車工業や環境・リサイクル産業などへ転換した。'], ex: { q: '筑豊炭田などの炭鉱が、1960年代に次々と閉山したのはなぜですか。', a: 'エネルギーの中心が石炭から石油へ移り(エネルギー革命)、安い外国産の石炭の輸入もふえたから。', exp: '炭鉱で働いていた人々が仕事を失い、人口が大きくへりました。地域は新しい産業の誘致などで立て直しをはかりました。' } }
    ],
    more: [
      { lv: 1, q: '熊本県にある、世界最大級のカルデラをもつ火山は何ですか。', a: '阿蘇山', exp: 'カルデラは、火山の噴火で地下のマグマが出たあとにできた大きなくぼ地です。阿蘇のカルデラの中には町や田畑があります。' },
      { lv: 1, q: '鹿児島県から宮崎県南部に広がる、火山の噴出物が積もった台地を何といいますか。', a: 'シラス台地', exp: 'シラス台地は水を通しやすく稲作に向かないため、さつまいもや茶の栽培、畜産がさかんです。' },
      { lv: 1, q: '岡山県と香川県を結ぶ本州四国連絡橋を何といいますか。', choices: ['明石海峡大橋', '瀬戸大橋', 'しまなみ海道', '関門橋'], a: 'B(瀬戸大橋)', exp: '瀬戸大橋は1988年に開通し、道路と鉄道の両方が通っています。明石海峡大橋は兵庫県と淡路島、しまなみ海道は広島県と愛媛県を結びます。' },
      { lv: 1, q: '近畿地方の人々の生活用水として利用され、「近畿の水がめ」とよばれる湖は何ですか。', a: '琵琶湖', exp: '琵琶湖は滋賀県にある日本最大の湖です。琵琶湖から流れ出る淀川の水が、京都や大阪で利用されています。' },
      { lv: 1, q: '新潟県の越後平野でさかんな、冬に雪が多いため1年に1回だけ米をつくる農業を何といいますか。', a: '水田単作', exp: '冬の間は雪で農業ができないため、稲作だけを行います。新潟県は米の生産量が全国有数です。' },
      { lv: 1, q: '関東平野の台地をおおっている、火山灰が積もってできた赤土を何といいますか。', a: '関東ローム', exp: '関東ロームは富士山や浅間山などの火山灰が積もったものです。台地は畑として利用されることが多くあります。' },
      { lv: 1, q: '岩手県の伝統的工芸品で、鉄でつくる茶の湯がまや鉄びんを何といいますか。', a: '南部鉄器', exp: '南部鉄器は盛岡市や奥州市でつくられています。東北地方の伝統工芸は、冬の農作業ができない時期の副業として発達したものが多くあります。' },
      { lv: 2, q: '1901年に操業を始めた八幡製鉄所が、現在の北九州市に建てられた理由を説明しなさい。', a: '近くの筑豊炭田から石炭を得やすく、鉄鉱石を輸入した中国にも近かったから。', exp: '日清戦争の賠償金の一部も使ってつくられました。北九州は日本の重工業の出発点になりました。' },
      { lv: 2, q: '京都市が、建物の高さやデザイン、看板の色などを制限する条例を定めているのはなぜですか。', a: '寺社や町家などの歴史的な町並み(景観)を守るため。', exp: '京都は多くの観光客が訪れる歴史都市です。古い町並みを守りながら暮らしを便利にしていくことが課題になっています。' },
      { lv: 2, q: '愛知県豊田市を中心にさかんな工業は何ですか。', a: '自動車工業', exp: '豊田市は自動車会社の名前がついた都市で、周辺に部品をつくる関連工場が集まっています。中京工業地帯の中心です。' },
      { lv: 2, q: '北陸地方で、地場産業や伝統産業が発達した理由として最も適切なものはどれですか。', choices: ['冬に雪が多く、農作業ができない期間の副業としてさかんになったから。', '1年中温暖で観光客が多かったから。', '大きな港があり、原料を大量に輸入できたから。', '火山が多く、地熱を利用できたから。'], a: 'A(冬に雪が多く、農作業ができない期間の副業としてさかんになったから。)', exp: '石川県の輪島塗や、福井県鯖江市の眼鏡のフレームなどが代表例です。雪国の暮らしの工夫が産業を生みました。' },
      { lv: 2, q: '関東地方などで、大都市の近くで野菜や花を栽培し、新鮮なうちに出荷する農業を何といいますか。', a: '近郊農業', exp: '大消費地に近いので、輸送の時間と費用がかからず、新鮮な状態で届けられます。茨城県や千葉県でさかんです。' },
      { lv: 2, q: '北海道に古くから住み、独自の文化をもつ先住民族は何ですか。', a: 'アイヌの人々(アイヌ民族)', exp: '札幌や稚内など、北海道の多くの地名はアイヌの言葉がもとになっています。2019年に、アイヌの人々を先住民族と明記した法律が定められました。' },
      { lv: 2, q: '青森県で夏に行われ、大きな灯籠の山車がねり歩く祭りはどれですか。', choices: ['竿燈まつり', 'ねぶた祭', '七夕まつり', '花笠まつり'], a: 'B(ねぶた祭)', exp: '青森ねぶた祭は東北三大祭りの1つです。竿燈まつりは秋田市、七夕まつりは仙台市、花笠まつりは山形市の祭りです。' },
      { lv: 2, q: '長野県の八ケ岳や浅間山のふもとで、夏のすずしい気候を生かしてレタスやキャベツを栽培する野菜を何といいますか。', a: '高原野菜', exp: 'ほかの産地のものが少ない夏に出荷できるので、高い値段で売れます。出荷の時期を遅らせる抑制栽培の例です。' },
      { lv: 3, q: '1970年代に琵琶湖で赤潮が発生した原因と、それに対する取り組みを説明しなさい。', a: '原因:工場や家庭からの排水が流れこみ、ふくまれていたりんなどで湖が富栄養化した。取り組み:りんをふくむ合成洗剤の使用を禁止する条例をつくり、住民がせっけんを使う運動を進めた。', exp: '住民の運動が、条例という形で地域のルールになった例です。環境保全は「原因 → 課題 → 取り組み」で整理しましょう。' },
      { lv: 3, q: '瀬戸大橋などの本州四国連絡橋が開通したことで、四国の地域にはどのような良い影響と課題が生まれましたか。', a: '良い影響:本州との行き来が速く便利になり、観光客や物の輸送がふえた。課題:買い物などで人が大都市へ吸い寄せられ(ストロー現象)、地元の商店街などがおとろえたところもある。', exp: '交通の発達には、地域を結びつける面と、大きな都市に人やお金が流れ出る面があります。両面を書くことがポイントです。' },
      { lv: 3, q: '長野県の高原でレタスなどを夏に出荷することが、農家にとって有利なのはなぜですか。', a: '夏は暑さのために平地での生産が少なくなり、市場に出回る量が減るので、高い値段で売れるから。', exp: '需要と供給で考えると、供給が少ない時期に出荷するほど価格が高くなります。高速道路の整備で大都市へ新鮮なまま運べるようになったことも重要です。' },
      { lv: 3, q: '北九州工業地域の出荷額が、ほかの工業地帯にくらべて伸びなくなった理由を説明しなさい。', a: 'エネルギー革命で地元の石炭の重要性が低下し、鉄鋼の原料も海外からの輸入が中心になって、太平洋ベルトのほかの地域に比べて有利さが失われたから。', exp: 'その後、北九州では自動車工場の進出や、環境・リサイクル産業(エコタウン)の育成など、新しい産業への転換が進められました。' },
      { lv: 3, q: '過疎の地域の課題を、「原因 → 課題 → 取り組み」の順に説明しなさい。', a: '原因:仕事が少ないため、若者が進学や就職で都市へ出ていく。課題:高齢化が進み、学校の統廃合やバス路線の廃止、地域の祭りや田畑の維持が難しくなる。取り組み:特産品づくりや観光で地域をおこし、都市からの移住(Iターン・Uターン)を受け入れる。', exp: '3つの段を順につなぐことで、地域の課題をわかりやすく説明できます。取り組みは地域ごとの具体例を入れると説得力が増します。' }
    ]
  });

  /* ===== 中学公民:人権と日本国憲法 ===== */
  add('c_jinken', {
    pat: [
      { name: '人権の歴史の文書の並べかえ', freq: 'とてもよく出る', when: 'マグナ・カルタ・権利章典・独立宣言・人権宣言・ワイマール憲法などが並んだら、この型です。', how: ['マグナ・カルタ(1215年、イギリス)→ 権利章典(1689年、イギリス)。', 'アメリカ独立宣言(1776年)→ フランス人権宣言(1789年)。ここまでは自由権が中心。', 'ワイマール憲法(1919年、ドイツ)で初めて社会権を規定 → 世界人権宣言(1948年)。', '「自由権 → 社会権 → 国際的な保障」という流れで確かめる。'], ex: { q: '次を古い順に並べなさい。ア ワイマール憲法 イ 権利章典 ウ フランス人権宣言', a: 'イ→ウ→ア', exp: '権利章典は1689年、フランス人権宣言は1789年、ワイマール憲法は1919年です。ちょうど100年おきに近い年なので、まとめて覚えるとよいでしょう。' } },
      { name: '基本的人権の分類', freq: 'とてもよく出る', when: '具体的な権利(例:職業を選ぶ、教育を受ける)が示され、どの種類の権利かを問われたら、この型です。', how: ['自由権=国家から自由になる権利。精神の自由・身体の自由・経済活動の自由の3つ。', '社会権=人間らしい生活を国に求める権利。生存権・教育を受ける権利・勤労の権利・労働基本権。', '参政権(選挙権など)、請求権(裁判を受ける権利など)と区別する。'], ex: { q: '職業を自由に選ぶ権利は、自由権のうち何の自由にあたりますか。', a: '経済活動の自由', exp: '職業選択の自由・居住移転の自由・財産権は、経済活動の自由です。経済活動の自由は、ほかの自由に比べて公共の福祉による制限を受けやすいとされます。' } },
      { name: '公共の福祉による制限の事例', freq: 'よく出る', when: '「この人権の制限はどの人権を、なぜ制限しているか」という事例問題は、この型です。', how: ['制限されている人権を特定する(表現の自由、職業選択の自由、財産権など)。', '何のための制限か(ほかの人の人権や社会全体の利益)を確かめる。', '「人権どうしの衝突を調整するため」とまとめる。'], ex: { q: '医師や弁護士として働くには資格が必要です。これはどの人権が、何のために制限されている例ですか。', a: '職業選択の自由が、人々の命や権利を守るために制限されている。', exp: '資格のない人が医療を行うと、多くの人の健康が危険にさらされます。公共の福祉による制限の代表的な例です。' } },
      { name: '違憲判決の事例と条文', freq: '難関校で出る', when: '最高裁判所の違憲判決の事例が示され、関係する憲法の権利を問われたら、この型です。', how: ['事例の中で「だれが、どう不利に扱われたか」を確かめる。', '身分や性別などによる差別なら第14条(法の下の平等)を考える。', '職業や営業の制限なら第22条(職業選択の自由)を考える。'], ex: { q: '親を殺した場合だけ特に重い刑を定めていた刑法の規定が、1973年に違憲とされました。おもに憲法のどの規定に反するとされましたか。', a: '第14条の法の下の平等', exp: '尊属殺人重罰規定の違憲判決です。親という身分によって刑の重さを極端に区別することは不合理な差別だとされました。最高裁判所が初めて法律を違憲と判断した例です。' } }
    ],
    more: [
      { lv: 1, q: '日本国憲法第13条で、すべての国民は何として尊重されると定められていますか。', a: '個人', exp: '「すべて国民は、個人として尊重される」と定めています。一人ひとりを大切にするという考えが、人権保障の土台です。' },
      { lv: 1, q: '「健康で文化的な最低限度の生活を営む権利」を何といいますか。', a: '生存権', exp: '日本国憲法第25条に定められた社会権の中心となる権利です。生活保護などの社会保障制度は、この権利にもとづいています。' },
      { lv: 1, q: '日本国憲法で、天皇は日本国と日本国民統合の何とされていますか。', a: '象徴', exp: '天皇は政治の権限をもたず、内閣の助言と承認にもとづいて国事行為を行います。' },
      { lv: 1, q: '日本国憲法で、戦争の放棄・戦力の不保持・交戦権の否認を定めているのは第何条ですか。', a: '第9条', exp: '第9条は平和主義を具体的に定めた条文です。前文でも、平和のうちに生存する権利が示されています。' },
      { lv: 1, q: '国民の三大義務は、子どもに普通教育を受けさせる義務・勤労の義務と、もう1つは何ですか。', a: '納税の義務', exp: '日本国憲法では、権利に比べて義務の規定は少なく、三大義務が中心です。' },
      { lv: 1, q: '1919年に制定され、世界で初めて社会権を保障した憲法は何ですか。', choices: ['アメリカ合衆国憲法', 'ワイマール憲法', '大日本帝国憲法', 'フランス憲法'], a: 'B(ワイマール憲法)', exp: 'ドイツのワイマール憲法は、人間らしい生活を保障することを国の役割として定めました。' },
      { lv: 1, q: '1948年に国連総会で採択された、すべての人と国が守るべき人権の基準を示したものを何といいますか。', a: '世界人権宣言', exp: '世界人権宣言には法的な拘束力はありませんでした。これを条約にしたものが、1966年に採択された国際人権規約です。' },
      { lv: 2, q: '裁判官の出す令状がなければ逮捕されないことは、自由権のうち何の自由にあたりますか。', a: '身体の自由(生命・身体の自由)', exp: '大日本帝国憲法のもとでの不当な逮捕や拷問への反省から、日本国憲法は身体の自由をくわしく定めています。' },
      { lv: 2, q: '労働基本権(労働三権)を3つ答えなさい。', a: '団結権・団体交渉権・団体行動権(争議権)', exp: '労働者が労働組合をつくり(団結権)、使用者と話し合い(団体交渉権)、ストライキなどを行う(団体行動権)権利です。' },
      { lv: 2, q: '人権を守るための権利のうち、請求権にあたらないものはどれですか。', choices: ['裁判を受ける権利', '国家賠償請求権', '刑事補償請求権', '選挙権'], a: 'D(選挙権)', exp: '選挙権は政治に参加する参政権です。請求権は、人権が侵されたときなどに国に対して求める権利です。' },
      { lv: 2, q: '1985年に制定され、雇用の面での男女の差別を禁止した法律は何ですか。', a: '男女雇用機会均等法', exp: '募集・採用・昇進などで男女を差別することを禁止しています。1999年には男女共同参画社会基本法も定められました。' },
      { lv: 2, q: '2019年に制定され、アイヌの人々を法律で初めて「先住民族」と明記した法律を何といいますか。', a: 'アイヌ施策推進法(アイヌ民族支援法)', exp: 'それまでのアイヌ文化振興法にかわって定められました。アイヌの人々の誇りが尊重される社会をめざしています。' },
      { lv: 2, q: '国民が国や地方の行政機関の持つ情報を手に入れられるようにする「知る権利」を保障するため、国が定めた法律は何ですか。', a: '情報公開法', exp: '国の行政機関に情報の公開を請求できます。地方公共団体では、情報公開条例が定められています。' },
      { lv: 2, q: '大規模な開発を行う前に、環境への影響を調べて評価するしくみを何といいますか。', a: '環境アセスメント(環境影響評価)', exp: '環境権を守るためのしくみの1つです。1997年に環境影響評価法が制定されました。' },
      { lv: 2, q: '自分の私生活をみだりに公開されない権利を何といいますか。', a: 'プライバシーの権利', exp: '日本国憲法に直接の規定はありませんが、第13条の幸福追求権などを根拠に認められてきた新しい人権です。個人情報保護法も関係しています。' },
      { lv: 3, q: '次を古い順に並べなさい。ア 世界人権宣言 イ アメリカ独立宣言 ウ マグナ・カルタ エ ワイマール憲法', a: 'ウ→イ→エ→ア', exp: 'マグナ・カルタは1215年、アメリカ独立宣言は1776年、ワイマール憲法は1919年、世界人権宣言は1948年です。「王の権力の制限 → 自由権 → 社会権 → 国際的な保障」の流れです。' },
      { lv: 3, q: '道路の建設のために、正当な補償をしたうえで土地の所有者から土地を買い上げることがあります。これはどの人権が、どのような考えで制限されている例ですか。', a: '財産権が、多くの人が利用する道路をつくるという公共の福祉のために制限されている。', exp: '日本国憲法第29条は財産権を保障していますが、正当な補償のもとで公共のために用いることを認めています。補償があることがポイントです。' },
      { lv: 3, q: '「形式的平等」と「実質的平等」のちがいを、障がいのある人の雇用を例に説明しなさい。', a: '形式的平等は、すべての人を同じように扱うこと。実質的平等は、不利な立場にある人に配慮し、結果として同じ機会を得られるようにすること。たとえば、企業に障がいのある人を一定の割合で雇うことを義務づけるのは、実質的平等をめざす取り組みである。', exp: 'スロープの設置などの合理的配慮も実質的平等の考え方です。「同じに扱う」だけでは差が残る場合があることを押さえましょう。' },
      { lv: 3, q: '薬局を開くときに、ほかの薬局から一定の距離をはなさなければならないとした規定が、1975年に最高裁判所で違憲とされました。おもに憲法のどの権利に反するとされましたか。', a: '職業選択の自由(第22条)', exp: '薬事法の距離制限は、不良な医薬品を防ぐという目的に対して、必要で合理的な制限とはいえないとされました。経済活動の自由に関する代表的な違憲判決です。' },
      { lv: 3, q: '立憲主義とはどのような考え方か、「憲法」「権力」「国民」の語を使って説明しなさい。', a: '憲法によって国家の権力を制限し、国民の人権を守るという考え方。憲法は国民をしばるものではなく、権力をもつ側をしばるものである。', exp: '日本国憲法第99条は、天皇や国務大臣、国会議員、公務員などに憲法を尊重し守る義務を課しています。国民の義務としては書かれていない点が、立憲主義を表しています。' }
    ]
  });
})(WPS.LESSONS);
